                for d in c["members"][member]:
                    hits.append({"in": n, "decl": d["decl"], "deprecated": d["deprecated"], "removal": d["removal"]})
        return hits


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--javap", required=True)
    ap.add_argument("--cp", action="append", required=True, help="VERSION=classpath-file")
    ap.add_argument("--facts", default=os.path.join(HERE, "api-facts.json"))
    ap.add_argument("--out", default=os.path.join(HERE, "api-facts.verified.json"))
    a = ap.parse_args()
