    out = {"factsVersion": facts["version"], "verifiedAt": datetime.date.today().isoformat(), "javap": jv,
           "method": "javap -public -v over the version's resolved compile classpath; members resolved through all supertypes",
           "versions": list(jars), "facts": {}}
    for v, j in jars.items():
        j.load([f["class"] for f in facts["facts"]])
    for f in facts["facts"]:
        rec = {}
        for v, j in jars.items():
            c = j.cache.get(f["class"])
            if not c:
