                continue
            chain = j.chain(f["class"])
            r = {"present": True, "kind": c["kind"], "deprecated": c["deprecated"], "removal": c["removal"],
                 "cancellable": "org.bukkit.event.Cancellable" in chain, "members": {}}
            for m in f.get("members", []):
