describe("API facts: version-trap failure rules (javap-verified)", () => {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const { precheck, rulesFor } = require("../services/modbuilder/precheck.js");
  const RULES = JSON.parse(fs.readFileSync(path.join(ROOT, "services/modbuilder/rules/failure-rules.json"), "utf8"));
