    ["client-loaded-world-version", ["1.21.1"], "import io.papermc.paper.event.player.PlayerClientLoadedWorldEvent; class A {}"],
    ["connection-validate-login-version", ["1.21.1", "1.21.4"], "import io.papermc.paper.event.connection.PlayerConnectionValidateLoginEvent; class A {}"],
    ["custom-model-data-component-version", ["1.21.1"], "class A { void f(org.bukkit.inventory.meta.ItemMeta m) { m.getCustomModelDataComponent(); } }"],
    ["custom-click-event-package", ["*"], "import org.bukkit.event.player.PlayerCustomClickEvent; class A {}"],
