        assert.equal(hit(body, v, id), applies ? 1 : 0, `${id} precheck @ ${v}`);
      }
    }
    for (const id of ["knockback-event-package", "riptide-not-cancellable-old"]) assert.equal(RULES.rules.find((x: { id: string }) => x.id === id).pattern, undefined, `${id} is prompt-only`);
