    const files: { rel: string; abs: string }[] = [];
    const walk = (d: string) => { for (const e of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name); if (e.isDirectory()) walk(p); else if (p.endsWith(".java")) files.push({ rel: path.relative(ROOT, p), abs: p }); } };
