      }).flatMap((f) => precheck([f], v).filter((h: { rule: string }) => ids.has(h.rule)).map((h: { rule: string }) => `${f.rel}:${h.rule}`));
      assert.deepEqual(bad, [], `@ ${v}`);
    }
  });
});

