// ------------------------------------------------------------------------------------------ item model states
const DURING_JAVA: Record<string, string> = { cooldown: "COOLDOWN", no_charges: "NO_CHARGES", charging: "CHARGING" };
const duringText = (d: string) => (d === "cooldown" ? "cools down" : d === "no_charges" ? "has no charges" : "is charging");
/** The ModelStates wiring of a mod, or null when no design has states (or the version has no item models). */
export function modelStatesOf(designs: ItemDesign[], fe: DesignFeatures, ctx: Pick<CompileContext, "assets">): MainStates | null {
  if (!fe.itemModel) return null;
  const rules: string[] = [], flagCounts: [string, number][] = [], aims: string[] = [];
  for (const d of designs) {
    const st = d.states;
    if (!st) continue;
    const im = d.assets?.model ? ctx.assets?.itemModels?.[d.assets.model] : undefined;
    for (const m of st.modes ?? []) rules.push(`new ModelStates.Rule(${jstr(d.id)}, ${jstr(m.ability)}, ModelStates.During.${DURING_JAVA[m.during]}, ${jstr(m.value)}, -1)`);
    let n = im ? im.flags.length : 0;
    (st.flags ?? []).forEach((f, i) => { const k = im ? im.flags.indexOf(f.name) : i; if (k < 0) return; n = Math.max(n, k + 1); rules.push(`new ModelStates.Rule(${jstr(d.id)}, ${jstr(f.ability)}, ModelStates.During.${DURING_JAVA[f.during]}, null, ${k})`); });
    if (st.modes?.length || st.flags?.length) flagCounts.push([d.id, n]);
    if (st.aim) aims.push(d.id);
  }
