}

export function stateNotes(designs: ItemDesign[], fe: DesignFeatures): string[] {
  const out: string[] = [];
  for (const d of designs) {
    const st = d.states;
    if (!st) continue;
    if (!fe.itemModel) { out.push(`${d.name.text}: item model states need Minecraft 1.21.4 or newer, so on ${fe.version} its look does not change.`); continue; }
    const what = [...(st.modes ?? []).map((m) => `"${m.value}" while ${m.ability.replace(/_/g, " ")} ${duringText(m.during)}`), ...(st.flags ?? []).map((f) => `"${f.name}" while ${f.ability.replace(/_/g, " ")} ${duringText(f.during)}`)];
    if (what.length) out.push(`${d.name.text} changes its look in hand: ${what.join(", ")} (players see it with the resource pack).`);
    if (st.aim) out.push(`${d.name.text}: hold right-click to aim (like drawing a bow, you walk slower while aiming).`);
  }
  return out;
}

/** Does a design use a weapon action anywhere (then designer/Weapons.java is part of the mod)? */
export function usesWeapons(d: ItemDesign): boolean {
  let yes = false;
  for (const ab of d.abilities) walkActions(ab.actions, (a) => { if (a.type === "hitscan" || a.type === "beam" || a.type === "area_blast") yes = true; });
  return yes;
}

