export const EYE_HEIGHT = 1.62;
const norm = (v: Vec): Vec => { const l = Math.hypot(v[0], v[1], v[2]); return l < 1e-12 ? [0, 0, 0] : [v[0] / l, v[1] / l, v[2] / l]; };
