export function pelletDir(look: Vec, i: number, n: number, spreadDeg: number): Vec {
  const d = norm(look);
  if (n <= 1 || spreadDeg <= 0) return d;
  const r = (spreadDeg * Math.PI / 180) * Math.sqrt((i + 0.5) / n);
  const th = i * 2.399963229728653;
  const up: Vec = Math.abs(d[1]) > 0.999 ? [1, 0, 0] : [0, 1, 0];
  const right = norm(cross(d, up));
  const up2 = norm(cross(right, d));
  const t = Math.tan(r);
  return norm([d[0] + right[0] * t * Math.cos(th) + up2[0] * t * Math.sin(th), d[1] + right[1] * t * Math.cos(th) + up2[1] * t * Math.sin(th), d[2] + right[2] * t * Math.cos(th) + up2[2] * t * Math.sin(th)]);
}
