export function rayHitsBox(eye: Vec, dir: Vec, maxDist: number, pos: Vec, height: number, width = 0.6, grow: number = WEAPON_LIMITS.raySize): number | null {
  const h = width / 2 + grow;
  const lo: Vec = [pos[0] - h, pos[1] - grow, pos[2] - h], hi: Vec = [pos[0] + h, pos[1] + height + grow, pos[2] + h];
  let t0 = 0, t1 = maxDist;
  for (let k = 0; k < 3; k++) {
    if (Math.abs(dir[k]) < 1e-12) { if (eye[k] < lo[k] || eye[k] > hi[k]) return null; continue; }
    let a = (lo[k] - eye[k]) / dir[k], b = (hi[k] - eye[k]) / dir[k];
    if (a > b) [a, b] = [b, a];
    t0 = Math.max(t0, a); t1 = Math.min(t1, b);
    if (t0 > t1) return null;
  }
  return t0;
}

