    if (!ab.ab.manualCooldown && ab.cooldown > 0) this.cdSet(p.id, ab.key, ab.cooldown);
    if (!ab.ab.manualCharges && ab.maxCharges > 0) this.spend(p.id, ab, 1);
    this.say(ab, "fired", p.id, { target: a.target?.id ?? null, charge: a.charge });
    this.run(a, ab.ab.actions, "");
    return true;
  } finally { this.active.delete(p.id); }
}

private other(a: Act, id?: string) { return !id || id === a.ab.ab.id ? a.ab : this.abilities.find((x) => x.item.id === a.ab.item.id && x.ab.id === id) ?? null; }
private targetIs(e: SimEntity | null, kinds: string[] | undefined, types: string[] | undefined) {
  if (!e || !e.alive) return false;
  const living = e.kind !== "other" && e.kind !== "armor_stand";
  if (kinds?.length && living && (kinds.includes("living") || kinds.includes(e.kind))) return true;
  return !!types?.length && types.map((t) => t.replace(/^minecraft:/, "")).includes(e.type);
}

private cond(a: Act, c: Condition, rel: string): boolean {
  const P = (k: string) => Number(a.ab.p(`${rel}.${k}`));
  const neg = (x: boolean) => (c.negate ? !x : x);
  switch (c.type) {
    case "cooldown_ready": { const o = this.other(a, c.ability); return neg(!o || this.cdReady(a.player.id, o.key)); }
    case "has_permission": return neg((a.player.permissions ?? []).includes(`${this.opts.namespace}.${c.node}`));
    case "target_is": { const t = a.target && a.target.alive ? a.target : null; if (!t) return false; const r = this.targetIs(t, c.kinds, c.types); return c.negate ? !r : r; }
    case "world_in": return neg(c.worlds.includes(a.player.world));
    case "health_below": case "health_above": {
      const s = c.subject === "self" ? a.player : a.target && a.target.alive ? a.target : null;
      if (!s) return false;
      const f = s.maxHealth <= 0 ? 0 : s.health / s.maxHealth;
      return neg(c.type === "health_below" ? f < P("fraction") : f > P("fraction"));
    }
    case "item_identity": return neg((c.slot === "main_hand" ? a.player.mainHand : a.player.offHand) === c.item);
    case "sneaking": return neg(!!a.player.sneaking);
    case "charges_available": { const o = this.other(a, c.ability); return neg(!!o && this.chargesLeft(a.player.id, o) >= P("amount")); }
    case "random_chance": return neg(this.random.nextDouble() < P("chance"));
    case "time_of_day": { const t = ((this.worldTime % 24000) + 24000) % 24000, f = P("from"), to = P("to"); return neg(f <= to ? t >= f && t <= to : t >= f || t <= to); }
  }
}

private run(a: Act, list: Action[], prefix: string): boolean {
  for (const [i, x] of list.entries()) {
    const rel = prefix ? `${prefix}${i}` : `a${i}`;
    if (!this.take(a.budget, "actions")) { this.say(a.ab, "budget_exhausted", a.player.id, { at: rel }); return false; }
    if (!this.act(a, x, rel)) return false;
  }
  return true;
}

private act(a: Act, x: Action, rel: string): boolean {
  const P = (k: string) => a.ab.p(`${rel}.${k}`);
  const N = (k: string) => Number(P(k));
  const subj = (t: string | undefined, dflt: "self" | "target") => ((t ?? dflt) === "self" ? a.player : a.target && a.target.alive ? a.target : null);
  const where = (w?: string): Vec | null => (w === "target" ? (a.target && a.target.alive ? [a.target.pos[0], a.target.pos[1] + (a.target.height ?? 1.8) / 2, a.target.pos[2]] : null) : w === "point" ? a.point : [a.player.pos[0], a.player.pos[1] + 1, a.player.pos[2]]);
  const scale = (b?: boolean) => (b ? a.charge : 1);
  const ent = (e: SimEntity | null) => !!e && e.alive && this.take(a.budget, "entities");
  switch (x.type) {
    case "damage": { const t = subj(x.target, "target"); const amt = N("amount") * scale(x.scaleWithCharge); if (!t || !t.alive || amt <= 0 || !ent(t)) break; t.health -= amt; this.say(a.ab, "damage", t.id, { amount: amt }); if (t.health <= 0) { t.health = 0; t.alive = false; this.say(a.ab, "died", t.id); this.deathEvent(t, t === a.player ? null : a.player); } break; }
    case "heal": { const t = subj(x.target, "self"); const amt = N("amount") * scale(x.scaleWithCharge); if (!t || amt <= 0 || !ent(t)) break; t.health = Math.min(t.maxHealth, t.health + amt); this.say(a.ab, "heal", t.id, { amount: amt }); break; }
    case "potion_effect": { const t = subj(x.target, "self"); if (!t || !ent(t)) break; this.say(a.ab, "potion", t.id, { effect: x.effect, ticks: N("duration_ticks"), amplifier: N("amplifier") }); break; }
    case "knockback": case "pull_to": case "push_from": {
      const t = subj(x.target, "target");
      if (!t || !t.alive) break;
      let dir: Vec;
      if (x.type === "knockback") { if (t === a.player) break; dir = [t.pos[0] - a.player.pos[0], 0, t.pos[2] - a.player.pos[2]]; }
      else if (x.type === "pull_to") { const to = x.to === "self" ? a.player.pos : a.point; if (Math.sqrt(dist2(to, t.pos)) < 1) break; dir = [to[0] - t.pos[0], 0, to[2] - t.pos[2]]; }
      else { const from = x.from === "self" ? a.player.pos : a.point; dir = [t.pos[0] - from[0], 0, t.pos[2] - from[2]]; }
      if (!this.take(a.budget, "entities")) break;
      const len = Math.hypot(dir[0], dir[2]); const s = N("strength") * scale(x.scaleWithCharge);
      let v: Vec = len < 1e-2 ? [0, N("vertical"), 0] : [dir[0] / len * s, N("vertical"), dir[2] / len * s];
      const vl = Math.hypot(...v); if (vl > 4) v = v.map((c) => (c / vl) * 4) as Vec;
      this.say(a.ab, x.type, t.id, { velocity: v.map((c) => +c.toFixed(4)) });
      break;
    }
    case "teleport_short": this.say(a.ab, "teleport", a.player.id, { range: N("range") }); break;
    case "launch_projectile": { if (!this.take(a.budget, "projectiles")) break; this.projectiles.push({ owner: a.player.id, item: a.ab.item.id, tag: x.tag ?? "" }); this.say(a.ab, "launch", a.player.id, { kind: x.kind, speed: N("speed"), tag: x.tag ?? "" }); if (this.take(a.budget, "tasks")) this.schedule(N("lifetime_ticks"), () => {}); break; }
    case "hitscan": {
      // Weapons.hitscan twin: rays from the eye along the aim (the scenario look), each stops at the first entity box
      // (or the look point when the look names no entity: a block there); pellet damage SUMMED per target, dealt once.
      const aim = this.aimOf(a);
      if (!aim) { this.say(a.ab, "hitscan", a.player.id, { note: "no aim in the scenario: nothing to shoot along" }); break; }
      const n = Math.max(1, Math.min(12, N("pellets")));
      const range = N("range");
      const sums = new Map<SimEntity, number>();
      let rays = 0;
      for (let i = 0; i < n; i++) {
        if (!this.take(a.budget, "actions")) break;
        rays++;
        const dir = pelletDir(aim.dir, i, n, N("spread"));
        const hit = this.firstOnRay(a, aim.eye, dir, Math.min(range, aim.block ?? range), x.players ?? true);
        if (x.tracer) { const want = Math.min(WEAPON_LIMITS.tracerPoints, Math.max(1, Math.ceil((hit?.t ?? Math.min(range, aim.block ?? range)) * 2))); const k = Math.max(0, Math.min(want, BUDGET.particles - a.budget.particles)); a.budget.particles += k; if (k < want) a.budget.exhausted = true; }
        if (hit) sums.set(hit.e, (sums.get(hit.e) ?? 0) + N("damage"));
      }
      this.say(a.ab, "hitscan", a.player.id, { rays, hits: [...sums.entries()].map(([e, d]) => `${e.id} x${Math.round(d / Math.max(1e-9, N("damage")))}`), reset: x.resetInvulnerability ?? true });
      const targets: SimEntity[] = [];
      for (const [t, amt] of sums) { if (!t.alive || !ent(t)) continue; this.hurt(a, t, amt); targets.push(t); }
      if (x.actions) for (const t of targets) if (!this.run({ ...a, target: t }, x.actions, `${rel}.n`)) return false;
      break;
    }
    case "beam": {
      if (!this.take(a.budget, "tasks")) break;
      const aim = this.aimOf(a);
      const interval = Math.max(2, N("interval_ticks"));
      const pulses = Math.max(1, Math.min(WEAPON_LIMITS.beamPulses, Math.floor(N("duration_ticks") / interval)));
      const id = ++this.beamSerial;
      this.beams.set(a.player.id, id);
      this.say(a.ab, "beam", a.player.id, { pulses, interval });
      const pulse = (left: number, inActivation: boolean) => {
        if (this.beams.get(a.player.id) !== id) return;
        const p = a.player;
        if (left <= 0 || !p.online || !p.alive || p.mainHand !== a.ab.item.id || !this.take(a.budget, "actions")) { this.beams.delete(p.id); this.say(a.ab, "beam_end", p.id, { left }); return; }
        const entered = !inActivation && !this.active.has(p.id);
        if (entered) this.active.add(p.id);
        try {
          if (inActivation || entered) {
            // the simulator keeps the activation's aim (no mouse movement is modelled)
            const hit = aim ? this.firstOnRay(a, [p.pos[0], p.pos[1] + EYE_HEIGHT, p.pos[2]], aim.dir, Math.min(N("range"), aim.block ?? N("range")), x.players ?? true) : null;
            if (x.particle) { const k = Math.max(0, Math.min(WEAPON_LIMITS.beamPoints, BUDGET.particles - a.budget.particles)); a.budget.particles += k; }
            if (hit && hit.e.alive && this.take(a.budget, "entities")) this.hurt(a, hit.e, N("damage"));
          }
        } finally { if (entered) this.active.delete(p.id); }
        if (left > 1) this.schedule(interval, () => pulse(left - 1, false)); else this.beams.delete(p.id);
      };
      pulse(pulses, true);
      break;
    }
    case "area_blast": {
      const c = where(x.at ?? "point");
      if (!c) break;
      const r = N("radius"), max = Math.max(1, Math.min(16, N("max")));
      if (x.particle) { const k = Math.max(0, Math.min(WEAPON_LIMITS.blastParticles, BUDGET.particles - a.budget.particles)); a.budget.particles += k; }
      const mid = (e: SimEntity): Vec => [e.pos[0], e.pos[1] + (e.height ?? 1.8) / 2, e.pos[2]];
      const list = [...this.entities.values()].filter((e) => e !== a.player && e.alive && e.kind !== "other" && e.kind !== "armor_stand" && dist2(e.pos, c) <= r * r)
        .sort((p, q) => dist2(p.pos, c) - dist2(q.pos, c) || (p.id < q.id ? -1 : 1)).slice(0, max);
      const hits: string[] = [];
      for (const t of list) {
        const isPlayer = t.kind === "player";
        if (isPlayer && N("player_scale") <= 0) continue;
        const f = Math.max(0, 1 - Math.sqrt(dist2(mid(t), c)) / r);
        if (f <= 0) continue;
        if ((x.lineOfSight ?? true) && !this.take(a.budget, "actions")) break; // line of sight itself: blocks are not modelled
        const amt = N("damage") * f * (isPlayer ? N("player_scale") : 1);
        if (amt > 0 && this.take(a.budget, "entities")) this.hurt(a, t, amt);

          if (amt > 0 && this.take(a.budget, "entities")) this.hurt(a, t, amt);
          if (x.knockback !== undefined && N("knockback") > 0 && this.take(a.budget, "entities")) this.say(a.ab, "push_from", t.id, { strength: +(N("knockback") * f).toFixed(4) });
          hits.push(`${t.id} ${Math.round(f * 100)}%`);
        }
        this.say(a.ab, "area_blast", undefined, { center: c.map((v) => +v.toFixed(2)), hits, lineOfSight: x.lineOfSight ?? true });
        break;
      }
      case "spawn_particles": { const at = where(x.at); if (!at) break; const want = N("count"); const n = Math.max(0, Math.min(want, BUDGET.particles - a.budget.particles)); a.budget.particles += n; if (n < want) a.budget.exhausted = true; if (n > 0) this.say(a.ab, "particles", undefined, { particle: x.particle, count: n }); break; }
      case "play_sound": { const at = where(x.at); if (!at) break; this.say(a.ab, "sound", undefined, { key: P("sound"), volume: N("volume"), pitch: N("pitch") }); break; }
      case "send_message": case "actionbar": case "title": {
        const to = (x.to ?? "self") === "self" ? a.player : a.target;
        if (!to || to.kind !== "player" || !to.online) break;
        const fill = (s: string) => s.replace(/\{player\}/g, a.player.id).replace(/\{target\}/g, a.target?.id ?? "");
        this.say(a.ab, x.type, to.id, { text: fill(String(P(x.type === "title" ? "title" : "text"))) });
        break;
      }
      case "give_item": this.say(a.ab, "give", a.player.id, { item: x.item, count: N("count") }); break;
      case "set_cooldown": { const o = this.other(a, x.ability); if (o) this.cdSet(a.player.id, o.key, N("ticks")); break; }
      case "consume_charge": { const o = this.other(a, x.ability); if (o) this.spend(a.player.id, o, N("amount")); break; }
      case "apply_mark": {
        const t = a.target && a.target.alive ? a.target : null;
        const def = (a.ab.item.marks ?? []).find((m) => m.name === x.mark)!;
        const base = `items.${a.ab.item.id}.marks.${def.name}.`;
        if (!t || t === a.player || !this.take(a.budget, "entities")) break;
        if (this.markApply(a.player.id, t.id, `${a.ab.item.id}.${x.mark}`, Number(this.value(base + "duration_ticks")), Number(this.value(base + "max_per_owner")))) this.say(a.ab, "mark", t.id, { mark: x.mark });
        break;
      }
      case "query_marked": case "query_nearby": {
        const center = x.around === "point" ? a.point : a.player.pos;
        const r = N("radius"), max = N("max");
        let list: SimEntity[];
        if (x.type === "query_marked") list = this.marked(a.player.id, `${a.ab.item.id}.${x.mark}`, center, r, max);
        else {
          list = [...this.entities.values()].filter((e) => e !== a.player && e.alive && e.kind !== "other" && e.kind !== "armor_stand" && (e.kind !== "player" || !!x.includePlayers)
            && (!(x.kinds?.length || x.types?.length) || this.targetIs(e, x.kinds, x.types)) && dist2(e.pos, center) <= r * r);
          list.sort((p, q) => dist2(p.pos, center) - dist2(q.pos, center) || (p.id < q.id ? -1 : 1));
          list = list.slice(0, max);
        }
        this.say(a.ab, x.type, undefined, { found: list.map((e) => e.id) });
        for (const e of list) if (!this.run({ ...a, target: e }, x.actions, `${rel}.n`)) return false;
        break;
      }
      case "delayed": {
        if (!this.take(a.budget, "tasks")) break;
        this.schedule(N("delay_ticks"), () => {
          if (!a.player.online || !a.player.alive || this.active.has(a.player.id)) return;
          this.active.add(a.player.id);
          try { this.say(a.ab, "delayed_run", a.player.id); this.run(a, x.actions, `${rel}.n`); } finally { this.active.delete(a.player.id); }
        });
        break;
      }
      case "branch": {
        const ok = x.if.every((c, j) => this.cond(a, c, `${rel}.if${j}`));
        this.say(a.ab, "branch", undefined, { taken: ok ? "then" : x.else ? "else" : "none" });
        if (ok) return this.run(a, x.then, `${rel}.then`);
        if (x.else) return this.run(a, x.else, `${rel}.else`);
        break;
      }
    }
    return true;
  }

  /** Damage with the same bookkeeping as the damage action (the entity budget is taken by the caller). */
  private hurt(a: Act, t: SimEntity, amt: number) {
    if (amt <= 0 || !t.alive) return;
    t.health -= amt; this.say(a.ab, "damage", t.id, { amount: +amt.toFixed(4) });
    if (t.health <= 0) { t.health = 0; t.alive = false; this.say(a.ab, "died", t.id); this.deathEvent(t, t === a.player ? null : a.player); }
  }
  /** Eye + aim direction of an activation: the scenario look (an entity's middle, or a point where a block stops the ray), else its target. */
  private aimOf(a: Act): { eye: Vec; dir: Vec; block: number | null } | null {
    const eye: Vec = [a.player.pos[0], a.player.pos[1] + EYE_HEIGHT, a.player.pos[2]];
    const lt = a.look?.target ? this.ent(a.look.target) : null;
    const at: Vec | null = lt ? [lt.pos[0], lt.pos[1] + (lt.height ?? 1.8) / 2, lt.pos[2]] : a.look ? a.look.point : a.target ? [a.target.pos[0], a.target.pos[1] + (a.target.height ?? 1.8) / 2, a.target.pos[2]] : null;
    if (!at) return null;
    const v: Vec = [at[0] - eye[0], at[1] - eye[1], at[2] - eye[2]];
    if (Math.hypot(...v) < 1e-6) return null;
    return { eye, dir: norm(v), block: !lt && a.look ? Math.hypot(...v) : null };
  }
  /** The first living entity whose box the ray enters within maxDist (never the user; players only when allowed). */
  private firstOnRay(a: Act, eye: Vec, dir: Vec, maxDist: number, players: boolean): { e: SimEntity; t: number } | null {
    let best: { e: SimEntity; t: number } | null = null;
    for (const e of this.entities.values()) {
      if (e === a.player || !e.alive || e.kind === "other" || e.kind === "armor_stand" || (e.kind === "player" && !players)) continue;
      const t = rayHitsBox(eye, dir, maxDist, e.pos, e.height ?? 1.8);
      if (t !== null && (!best || t < best.t || (t === best.t && e.id < best.e.id))) best = { e, t };
    }
    return best;
  }

  /** DesignListener.onDeath twin: kill trigger (skipped while the killer's activation runs = the re-entry guard), mark cleanup, player death. */
  private deathEvent(dead: SimEntity, killer: SimEntity | null) {
    if (killer && killer !== dead) {
      const list = this.abilitiesOf(killer.mainHand, "kill_entity");
      if (this.active.has(killer.id)) { if (list.length) this.say(null, "kill_trigger_suppressed", killer.id, { dead: dead.id }); }
      else for (const a of list) this.fire(this.activation(a, killer, dead, dead.pos, 0));
    }
    this.removeTarget(dead.id);
    if (dead.kind === "player") {
      for (const d of this.designs) if ((dead.inventory ?? []).includes(d.id) || dead.mainHand === d.id) for (const a of this.abilitiesOf(d.id, "death")) this.fire(this.activation(a, dead, null, null, 0));
      this.forget(dead.id);
    }
  }

  private schedule(delay: number, run: () => void) { if (this.tasks.length < RUNTIME_CAPS.liveTasks) this.tasks.push({ at: this.tick + Math.max(1, delay), run }); }

  /** Advance time: run due tasks and held_interval timers (first run after one period, like runTaskTimer(p, p)). */
  advanceTo(tick: number) {
    while (this.tick < tick) {
      this.tick++;
      this.worldTime = (this.worldTime + 1) % 24000;
      for (const t of this.tasks.filter((x) => x.at === this.tick)) { this.tasks.splice(this.tasks.indexOf(t), 1); t.run(); }
      for (const a of this.abilities) if (a.ab.trigger.type === "held_interval") {
        const period = Math.max(10, Number(a.p("trigger.period_ticks")));
        if (this.tick % period !== 0) continue;
        for (const p of this.entities.values()) if (p.kind === "player" && p.online && p.alive) {
          const has = a.ab.trigger.slot === "inventory" ? (p.inventory ?? []).includes(a.item.id) || p.mainHand === a.item.id || p.offHand === a.item.id : p.mainHand === a.item.id;
          if (has) this.fire(this.activation(a, p, null, null, 0));
        }
      }
    }
  }

  private aim(a: SimAbility, p: SimEntity, clicked: SimEntity | null, look: { target?: string; point: Vec } | undefined, charge: number) {
    let target: SimEntity | null = null, point: Vec | null = null;
    if (a.range > 0) {
      if (clicked && clicked.kind !== "other" && Math.sqrt(dist2(clicked.pos, p.pos)) <= a.range + 1) { target = clicked; point = clicked.pos; }
      else if (look) { const t = this.ent(look.target); target = t && t.alive && Math.sqrt(dist2(t.pos, p.pos)) <= a.range + 1 ? t : null; point = look.point; }
    }
    this.fire(this.activation(a, p, target, point, charge, look));
  }
  private frac(a: SimAbility, held: number) { return Math.max(0, Math.min(1, held / Math.max(1, a.maxCharge))); }

  /** Feed one event (advances time to its tick first). */
  event(e: SimEvent) {
    this.advanceTo(e.tick);
    if (e.type === "advance") return;
    const p = this.ent(e.player);
    if (!p) throw new Error(`no entity ${e.player}`);
    switch (e.type) {
      case "hold": p.mainHand = e.mainHand; this.chargeStart.delete(p.id); break;
      case "switch_item": this.chargeStart.delete(p.id); break;
      case "right_click": {
        if (this.active.has(p.id)) return;
        const item = p.mainHand ?? null;
        if (!item || !this.item(item)) return;
        if (this.lastClick.get(p.id) === this.tick) return;
        this.lastClick.set(p.id, this.tick);
        const clicked = this.ent(e.clicked);
        if (p.sneaking) {
          let sneakAbility = false;
          const start = this.chargeStart.get(p.id);
          for (const a of this.abilitiesOf(item, "charge_release")) {
            if (a.ab.trigger.type !== "charge_release" || a.ab.trigger.release !== "right_click") continue;
            sneakAbility = true;
            if (start === undefined) continue;
            const held = this.tick - start;
            if (held < a.minCharge) { this.say(a, "blocked", p.id, { by: "not charged", held }); continue; }
            this.chargeStart.delete(p.id);
            this.aim(a, p, clicked, e.look, this.frac(a, held));
          }
          const sneak = this.abilitiesOf(item, "sneak_right_click");
          for (const a of sneak) this.aim(a, p, clicked, e.look, 0);
          if (sneakAbility || sneak.length) return;
        }
        for (const a of this.abilitiesOf(item, "right_click")) this.aim(a, p, clicked, e.look, 0);
        break;
      }
      case "sneak_start": p.sneaking = true; if (p.mainHand && this.abilitiesOf(p.mainHand, "charge_release").length) this.chargeStart.set(p.id, this.tick); else this.chargeStart.delete(p.id); break;
      case "sneak_stop": {
        p.sneaking = false;
        const start = this.chargeStart.get(p.id); this.chargeStart.delete(p.id);
        if (!p.mainHand || start === undefined || this.active.has(p.id)) break;
        const held = this.tick - start;
