/** Validate a whole mod (all its design files): each file + cross-file duplicates. */
export function validateDesigns(inputs: unknown[], ctx: Omit<DesignContext, "items">): { ok: boolean; results: DesignValidation[]; errors: DzIssue[] } {
  const keys = inputs.map((x) => (x && typeof x === "object" && typeof (x as { id?: unknown }).id === "string" ? (x as { id: string }).id : "")).filter(Boolean);
  const errors: DzIssue[] = [];
  const maxItems = ctx.limits?.maxItems ?? DESIGN_LIMITS.maxItems;
  if (inputs.length > maxItems) errors.push({ path: "(mod)", code: "too_many_items", message: `${inputs.length} design items; the limit is ${maxItems}` });
  const dup = keys.find((k, i) => keys.indexOf(k) !== i);
  if (dup) errors.push({ path: "(mod)", code: "duplicate_item", message: `design item ${dup} is defined twice` });
  const results = inputs.slice(0, maxItems).map((x) => validateDesign(x, { ...ctx, items: keys }));
  return { ok: !errors.length && results.every((r) => r.ok), results, errors };
}

