        if (Tag.IRON_ORES.isTagged(m)) return Tag.IRON_ORES;
        if (Tag.COPPER_ORES.isTagged(m)) return Tag.COPPER_ORES;
        if (Tag.GOLD_ORES.isTagged(m)) return Tag.GOLD_ORES;
        if (Tag.REDSTONE_ORES.isTagged(m)) return Tag.REDSTONE_ORES;
        if (Tag.LAPIS_ORES.isTagged(m)) return Tag.LAPIS_ORES;
