  | { tick: number; type: "break_block"; player: string; at: Vec }''')
rep('''// ------------------------------------------------------------------------------------------ weapon geometry (twin)''','''// ------------------------------------------------------------------------------------------ vein blocks (twin)
const ORE_FAMILIES = ["coal", "iron", "copper", "gold", "redstone", "lapis", "diamond", "emerald"];
/** Twin of Veins.ore / Tag.LOGS for the simulator's block ids (vanilla names without minecraft:). */
export const isOreId = (t: string) => ORE_FAMILIES.some((f) => t === `${f}_ore` || t === `deepslate_${f}_ore`) || t === "nether_gold_ore" || t === "nether_quartz_ore" || t === "ancient_debris";
export const isLogId = (t: string) => /^(stripped_)?[a-z_]+_(log|wood|stem|hyphae)$/.test(t);
/** Twin of Veins.family: an ore and its deepslate / nether twin share a family; anything else is its own. */
export const veinFamily = (t: string, exact: boolean) => { if (exact) return t; for (const f of ORE_FAMILIES) if (t === `${f}_ore` || t === `deepslate_${f}_ore` || (f === "gold" && t === "nether_gold_ore")) return `#${f}_ores`; return t; };
const bkey = (x: number, y: number, z: number) => `${x},${y},${z}`;

// ------------------------------------------------------------------------------------------ weapon geometry (twin)''')
rep('''  private readonly beams = new Map<string, number>();
  private beamSerial = 0;''','''  private readonly beams = new Map<string, number>();
  private beamSerial = 0;
  /** techniques: the block model (block id without minecraft:, keyed "x,y,z"), protected blocks, loaded chunks ("cx,cz"; absent = all loaded) */
  readonly blocks = new Map<string, string>();
  readonly protectedBlocks = new Set<string>();
  loadedChunks: Set<string> | null = null;
  private readonly veins = new Map<string, number>();
  private veinSerial = 0;''')
rep('''  add(e: SimEntity): SimEntity {''','''  setBlock(pos: Vec, type: string | null) { const k = bkey(Math.floor(pos[0]), Math.floor(pos[1]), Math.floor(pos[2])); if (!type || type === "air") this.blocks.delete(k); else this.blocks.set(k, type.replace(/^minecraft:/, "")); }
  blockAt(pos: Vec): string { return this.blocks.get(bkey(Math.floor(pos[0]), Math.floor(pos[1]), Math.floor(pos[2]))) ?? "air"; }
  private chunkLoaded(x: number, z: number) { return !this.loadedChunks || this.loadedChunks.has(`${x >> 4},${z >> 4}`); }
  add(e: SimEntity): SimEntity {''')
