      if (bt.type === "break_block" && (bt.blocks?.length || bt.types?.length)) {
        const m = this.blockAt(a.point);
        const ok = ((bt.blocks ?? []).includes("ores") && isOreId(m)) || ((bt.blocks ?? []).includes("logs") && isLogId(m)) || (bt.types ?? []).map((t) => t.replace(/^minecraft:/, "")).includes(m);
        if (!ok) { this.say(ab, "blocked", p.id, { by: "block filter", block: m }); return false; }
      }
      for (const [i, c] of (ab.ab.conditions ?? []).entries()) if (!this.cond(a, c, `c${i}`))''')
rep('''      case "area_blast": {
        const c = where(x.at ?? "point");''','''      case "vein_break": {
        // Veins.vein twin: BFS from the broken block (the aim point), same neighbour order, same caps, 1-tick steps
        const pid = a.player.id;
        if (this.veins.has(pid) || this.veins.size >= VEIN_LIMITS.liveVeins) { this.say(a.ab, "vein", pid, { note: "a vein already runs" }); break; }
        const o: Vec = [Math.floor(a.point[0]), Math.floor(a.point[1]), Math.floor(a.point[2])];
        const type = this.blockAt(o);
        if (type === "air" || !this.take(a.budget, "tasks")) break;
        const exact = (x.match ?? "family") === "same", fam = veinFamily(type, exact);
        const max = Math.max(1, Math.min(CAPS.veinBlocks[1], N("max_blocks"))), perTick = Math.max(1, Math.min(CAPS.veinPerTick[1], N("per_tick"))), r = Math.max(1, Math.min(CAPS.veinRadius[1], N("radius")));
        const diagonal = x.diagonal ?? true;
        const seen = new Set<string>([bkey(0, 0, 0)]), queue: Vec[] = [];
        let checks = max * VEIN_LIMITS.checksPerBlock, broken = 0;
        const expand = (d: Vec) => {
          for (let ax = -1; ax <= 1; ax++) for (let ay = -1; ay <= 1; ay++) for (let az = -1; az <= 1; az++) {
            if (!ax && !ay && !az) continue;
            if (!diagonal && Math.abs(ax) + Math.abs(ay) + Math.abs(az) !== 1) continue;
            if (checks <= 0) return;
            const n: Vec = [d[0] + ax, d[1] + ay, d[2] + az];
            if (n[0] ** 2 + n[1] ** 2 + n[2] ** 2 > r * r) continue;
            if (seen.has(bkey(...n))) continue;
            seen.add(bkey(...n)); checks--;
            if (!this.chunkLoaded(o[0] + n[0], o[2] + n[2])) continue;
            if (veinFamily(this.blockAt([o[0] + n[0], o[1] + n[1], o[2] + n[2]]), exact) === fam) queue.push(n);
