{
  "schemaVersion": 1,
  "id": "scatter_gun",
  "base": "minecraft:golden_horse_armor",
  "name": { "text": "Scatter Gun", "color": "gold" },
  "abilities": [
    { "id": "blast", "name": "Blast", "trigger": { "type": "right_click" }, "cooldownTicks": 4,
      "actions": [
        { "type": "hitscan", "range": 16, "damage": 1, "pellets": 4, "resetInvulnerability": true, "tracer": "smoke",
          "actions": [{ "type": "spawn_particles", "particle": "damage_indicator", "count": 2, "at": "target" }] }
      ] }
  ]
}
// Cyrus designer WEAPON components (2026-10-12, universal-modder finding 5): hitscan, beam, area_blast. Pure: the spec
// (caps, semantic checks, the click-cooldown rule that blocks server-side "full-auto"), the static budgets (rays =
// actions, hits = entities, tracer / beam / blast particles), the compiler (Weapons.java only when used, existing mods
// byte-identical, params in config.yml, README note), the Java text rules (no block changes, no timers, API names), the
// reference simulator (pellet summing, first-hit rays, beam pulses and their end, linear falloff, never the user), the
// studio palette, the prompt, routing, perf audit rows and the TS == generated JS bundle.
// Real javac + strict scan + Test Flight playtest: test/cyrus-designer-weapons-real.ts on node-2.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { BUDGET, CAPS, WEAPON_LIMITS, beamPulses, validateDesign, validateDesigns, type ItemDesign } from "../lib/cyrus/designer/spec";
import { compileDesigns, usesWeapons, type CompileOk } from "../lib/cyrus/designer/compile";
import { COMPONENTS, libraryHash } from "../lib/cyrus/designer/components";
import { WEAPONS_JAVA, WEAPONS_META } from "../lib/cyrus/designer/components/weapons";
import { DesignSimulator, EYE_HEIGHT, pelletDir, rayHitsBox, type SimEntity, type Vec } from "../lib/cyrus/designer/simulate";
import { ACTION_TEMPLATES, childLists, insertAction } from "../lib/cyrus/designer/studio/edit";
import { matchDesignerWords } from "../lib/cyrus/designer/route";
import { perfCapAudit } from "../lib/cyrus/safety/perf-caps";

const ROOT = path.join(__dirname, "..");
const FX = path.join(__dirname, "fixtures/cyrus-designer-weapons");
const NS = "nx_r7weapon";
const NAMES = ["tap_pistol", "scatter_gun", "blast_rod", "ion_beam", "rocket_launcher"];
const load = (n: string): ItemDesign => JSON.parse(fs.readFileSync(path.join(FX, `${n}.json`), "utf8"));
const ALL = () => NAMES.map(load);
const V = (d: unknown, v = "1.21.11") => validateDesign(d, { version: v, namespace: NS });
const codes = (r: ReturnType<typeof validateDesign>) => r.errors.map((e) => e.code);
const wcodes = (r: ReturnType<typeof validateDesign>) => r.warnings.map((e) => e.code);
const gun = (actions: unknown[], ab: Record<string, unknown> = {}, trigger: unknown = { type: "right_click" }) => ({ schemaVersion: 1, id: "gun", base: "minecraft:iron_horse_armor", name: { text: "Gun" }, abilities: [{ id: "fire", name: "Fire", trigger, actions, cooldownTicks: 4, ...ab }] });
const compile = (d: unknown[], v = "1.21.11"): CompileOk => { const r = compileDesigns(d, { version: v, namespace: NS, pluginName: "NxArmory" }); if (!r.ok) throw new Error(JSON.stringify(r.errors)); return r; };

describe("weapons: the spec", () => {
  it("the five fixtures are valid on every buildable version (+ 26.2)", () => {
    for (const v of ["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.2"]) {
      const r = validateDesigns(ALL(), { version: v, namespace: NS });
      assert.ok(r.ok, `${v}: ${JSON.stringify(r.results.flatMap((x) => x.errors))}`);
    }
  });
  it("static budgets: a ray is an action, a hit an entity, tracer / beam / blast particles counted", () => {
    const b = (n: string, ab: string) => { const r = V(load(n)); assert.ok(r.ok); const { ability: _a, ...x } = r.budgets.find((y) => y.ability === ab)!; return x; };
    assert.deepEqual(b("tap_pistol", "shoot"), { actions: 1 + 1 + 1, entities: 1, tasks: 0, particles: WEAPON_LIMITS.tracerPoints, projectiles: 0, nodes: 2, depth: 1 });
    assert.deepEqual(b("scatter_gun", "blast"), { actions: 1 + 4 + 4, entities: 4, tasks: 0, particles: 4 * WEAPON_LIMITS.tracerPoints + 4 * 2, projectiles: 0, nodes: 2, depth: 2 });
    assert.deepEqual(b("blast_rod", "detonate"), { actions: 1 + 8, entities: 8, tasks: 0, particles: WEAPON_LIMITS.blastParticles, projectiles: 0, nodes: 1, depth: 1 });
    assert.deepEqual(b("ion_beam", "beam"), { actions: 1 + 10, entities: 10, tasks: 1, particles: 10 * WEAPON_LIMITS.beamPoints, projectiles: 0, nodes: 1, depth: 1 });
    assert.equal(beamPulses(40, 4), 10); assert.equal(beamPulses(100, 2), WEAPON_LIMITS.beamPulses); assert.equal(beamPulses(10, 20), 1);
  });
  it("no lag bomb: too many rays / hits / particles per activation are refused (the runtime Budget enforces the same)", () => {
    const six = Array(6).fill({ type: "hitscan", range: 64, damage: 1, pellets: 12, spread: 5 });
    assert.ok(codes(V(gun(six))).includes("budget_actions"), "6 x 12 pellets = 72 rays + 6 > 64");
    assert.ok(codes(V(gun([{ type: "beam", range: 8, damage: 1, durationTicks: 100, intervalTicks: 2 }]))).includes("budget_entities"), "50 pulses could hit 50 times > 32");
    assert.ok(codes(V(gun([{ type: "hitscan", range: 64, damage: 1, pellets: 12, spread: 5, tracer: "crit" }, { type: "hitscan", range: 64, damage: 1, pellets: 12, spread: 5, tracer: "crit" }]))).includes("budget_particles"), "2 x 12 x 24 tracer points > 512");
    assert.ok(V(gun([{ type: "hitscan", range: 64, damage: 1, pellets: 12, spread: 5 }])).ok);
  });
  it("full-auto is not possible server-side: a click weapon needs cooldownTicks >= 4 (or charges)", () => {
    const shot = [{ type: "hitscan", range: 16, damage: 2 }];
    assert.ok(codes(V(gun(shot, { cooldownTicks: undefined }))).includes("weapon_cooldown"));
    assert.ok(codes(V(gun(shot, { cooldownTicks: 3 }))).includes("weapon_cooldown"));
    assert.match(V(gun(shot, { cooldownTicks: 0 })).errors.find((e) => e.code === "weapon_cooldown")!.message, /every 4 ticks.*Faster full-auto is not possible server-side/);
    assert.ok(V(gun(shot, { cooldownTicks: 4 })).ok);
    assert.ok(V(gun(shot, { cooldownTicks: undefined, charges: { max: 6, regenTicks: 20 } })).ok, "charges also bound it");
    assert.ok(V(gun(shot, { cooldownTicks: undefined }, { type: "held_interval", periodTicks: 10 })).ok, "held_interval is >= 10 ticks anyway");
    assert.equal(WEAPON_LIMITS.minClickCooldown, 4);
  });
  it("no weapon inside a loop (a query or a hitscan's per-target actions)", () => {
    assert.ok(codes(V(gun([{ type: "query_nearby", radius: 5, max: 4, actions: [{ type: "hitscan", range: 8, damage: 1 }] }]))).includes("weapon_in_loop"));
    assert.ok(codes(V(gun([{ type: "hitscan", range: 8, damage: 1, actions: [{ type: "area_blast", radius: 2, damage: 1, at: "target" }] }]))).includes("weapon_in_loop"));
    assert.ok(codes(V(gun([{ type: "hitscan", range: 8, damage: 1, actions: [{ type: "query_nearby", radius: 2, max: 2, actions: [{ type: "damage", amount: 1 }] }] }]))).includes("nested_query"));
    assert.ok(V(gun([{ type: "delayed", delayTicks: 10, actions: [{ type: "area_blast", radius: 3, damage: 2, at: "self" }] }])).ok, "a delayed blast is fine");
    // per-target actions see the hit entity as the target
    assert.ok(V(gun([{ type: "hitscan", range: 8, damage: 1, actions: [{ type: "knockback", strength: 1 }, { type: "potion_effect", effect: "slowness", durationTicks: 40, target: "target" }] }])).ok);
  });
  it("schema caps and semantic warnings", () => {
    assert.ok(codes(V(gun([{ type: "hitscan", range: 65, damage: 1 }]))).includes("schema"));
    assert.ok(codes(V(gun([{ type: "hitscan", range: 8, damage: 1, pellets: 13 }]))).includes("schema"));
    assert.ok(codes(V(gun([{ type: "area_blast", radius: 9, damage: 1 }]))).includes("schema"));
    assert.ok(codes(V(gun([{ type: "area_blast", radius: 3, damage: 1, breakBlocks: true }]))).includes("schema"), "there is no block damage option");
    assert.ok(codes(V(gun([{ type: "hitscan", range: 8, damage: 1, tracer: "dust" }]))).includes("schema"), "data particles are not in the curated list");
    assert.ok(wcodes(V(gun([{ type: "hitscan", range: 8, damage: 1, spread: 5 }]))).includes("spread_one_pellet"));
    assert.ok(wcodes(V(gun([{ type: "hitscan", range: 8, damage: 1, pellets: 3 }]))).includes("pellets_no_spread"));

    assert.ok(wcodes(V(gun([{ type: "hitscan", range: 8, damage: 1, pellets: 3 }]))).includes("pellets_no_spread"));
    assert.ok(wcodes(V(gun([{ type: "beam", range: 8, damage: 1, durationTicks: 10, intervalTicks: 20 }]))).includes("beam_one_pulse"));
    assert.ok(wcodes(V(gun([{ type: "area_blast", radius: 3, damage: 1 }]))).includes("point_is_self"), "right_click without targetRange: the blast is on the player");
    assert.ok(codes(V(gun([{ type: "area_blast", radius: 3, damage: 1, at: "target" }]))).includes("no_target"));
    assert.ok(V(gun([{ type: "area_blast", radius: 3, damage: 1, at: "target" }], {}, { type: "right_click", targetRange: 16 })).ok);
  });
});

describe("weapons: the compiler and the component", () => {
  it("Weapons.java is added only when a design uses a weapon; other mods are untouched", () => {
    const r = compile(ALL());
    const w = r.files.find((f) => f.path.endsWith("/designer/Weapons.java"));
    assert.ok(w); assert.equal(w!.role, "component");
    assert.ok(!w!.content.includes("__PKG__"));
    assert.match(w!.content, /^package dev\.nxeon\.plugins\.nxarmory\.designer;/);
    const plain = compileDesigns([JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-designer/void_reaper.json"), "utf8"))], { version: "1.21.11", namespace: "nx_r7design", pluginName: "VoidArsenal" });
    assert.ok(plain.ok && !plain.files.some((f) => f.path.endsWith("Weapons.java")));
    assert.ok(plain.ok && plain.libraryHash === libraryHash(), "no weapons: the library hash is unchanged");
    assert.notEqual(r.libraryHash, libraryHash(), "with weapons the recorded library hash covers Weapons.java");
    assert.ok(!COMPONENTS.some((c) => c.id === WEAPONS_META.id), "not part of every mod");
    assert.ok(usesWeapons(load("ion_beam")) && !usesWeapons(JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-designer/storm_staff.json"), "utf8"))));
  });
  it("generated abilities call the component with config parameters; only weapon abilities import it", () => {
    const r = compile(ALL());
    const src = (cls: string) => r.files.find((f) => f.path.endsWith(`/abilities/${cls}.java`))!.content;
    const tap = src("TapPistolShoot");
    assert.match(tap, /import dev\.nxeon\.plugins\.nxarmory\.designer\.Weapons;/);
    assert.match(tap, /Weapons\.hitscan\(d, a, p_a0_range, p_a0_damage, p_a0_pellets, p_a0_spread, true, true, Particle\.CRIT\);/);
    const sc = src("ScatterGunBlast");
    assert.match(sc, /for \(LivingEntity t1 : Weapons\.hitscan\(d, a, p_a0_range, p_a0_damage, p_a0_pellets, p_a0_spread, true, true, Particle\.SMOKE\)\) \{/);
    assert.match(sc, /Activation a1 = a\.withTarget\(t1\);/);
    assert.match(sc, /d\.effects\(\)\.particles\(a1, d\.effects\(\)\.target\(a1\), Particle\.DAMAGE_INDICATOR, p_a0_n0_count/);
    assert.match(src("IonBeamBeam"), /Weapons\.beam\(d, a, p_a0_range, p_a0_damage, p_a0_duration_ticks, p_a0_interval_ticks, true, true, Particle\.END_ROD\);/);
    assert.match(src("BlastRodDetonate"), /Weapons\.areaBlast\(d, a, d\.effects\(\)\.target\(a\), p_a0_radius, p_a0_damage, p_a0_player_scale, p_a0_max, 0\.0, true, Particle\.EXPLOSION\);/);
    assert.match(src("RocketLauncherBoom"), /Weapons\.areaBlast\(d, a, d\.effects\(\)\.point\(a\), p_a0_radius, p_a0_damage, p_a0_player_scale, p_a0_max, p_a0_knockback, true, Particle\.EXPLOSION\);/);
    assert.doesNotMatch(src("RocketLauncherFire"), /Weapons/, "the projectile ability does not import Weapons");
  });
  it("every number is a clamped config.yml setting; the README says what full-auto cannot do", () => {
    const r = compile(ALL());
    const cfg = r.files.find((f) => f.path.endsWith("config.yml"))!.content;
    for (const line of ["# Shoot: shot range (blocks) (1.0 to 64.0)", "range: 32.0", "# Blast: pellets per shot (1 to 12)", "pellets: 4", "# Ion beam: ticks between pulses (2 to 20)", "interval_ticks: 4", "# Detonate: share of the damage players take (0-1) (0.0 to 1.0)", "player_scale: 0.5", "# Boom: blast knockback strength (0.0 to 3.0)"]) assert.ok(cfg.includes(line), line);
    assert.ok(r.params.some((p) => p.path === "items.blast_rod.abilities.detonate.a0.max" && p.value === 8 && p.max === 16));
    assert.match(r.readme, /every 4 ticks \(5 times a second\).*true full-auto needs a client mod/);
    assert.match(r.readme, /never break blocks/);
  });
  it("the component Java: verified API only, no block changes, no timers, no explosions, caps from WEAPON_LIMITS", () => {
    for (const s of ["World.rayTrace", ".rayTrace(eye, dir, range, FluidCollisionMode.NEVER, true, RAY_SIZE, e -> foe(e, p, players))", "setNoDamageTicks(0)", "rayTraceBlocks(center, to, len, FluidCollisionMode.NEVER, true)", "getCrossProduct", "d.tasks().later(interval"]) assert.ok(WEAPONS_JAVA.includes(s) || s === "World.rayTrace", s);
    for (const bad of ["createExplosion", "setType(", "breakNaturally", "runTaskTimer", "Thread", "reflect", "Bukkit.dispatchCommand", "getLoadedChunks", "getEntities()", "async"]) assert.ok(!WEAPONS_JAVA.includes(bad), `forbidden: ${bad}`);
    assert.match(WEAPONS_JAVA, new RegExp(`TRACER_POINTS = ${WEAPON_LIMITS.tracerPoints};`));
    assert.match(WEAPONS_JAVA, new RegExp(`LIVE_BEAMS = ${WEAPON_LIMITS.liveBeams};`));
    assert.match(WEAPONS_JAVA, new RegExp(`BEAM_PULSES = ${WEAPON_LIMITS.beamPulses};`));
    assert.match(WEAPONS_JAVA, /MAX_PELLETS = 12;/); assert.equal(CAPS.pellets[1], 12);
    assert.match(WEAPONS_JAVA, /BLAST_MAX = 16;/); assert.equal(CAPS.blastMax[1], 16);
    assert.match(WEAPONS_JAVA, /if \(!a\.budget\(\)\.action\(\)\) break;/, "every ray spends an action");
    assert.match(WEAPONS_JAVA, /d\.enter\(p\)/, "later beam pulses take the re-entry guard");
    assert.match(WEAPONS_JAVA, /Full-auto beyond vanilla's 4-tick right-click repeat is not possible server-side/);
  });
});

describe("weapons: the reference simulator", () => {
  const world = (designs: ItemDesign[], hand: string, mobs: { id: string; at: Vec; kind?: SimEntity["kind"]; h?: number }[]) => {
    const s = new DesignSimulator(designs, { namespace: NS });
    s.add({ id: "you", type: "minecraft:player", kind: "player", pos: [0, 64, 0], health: 20, maxHealth: 20, world: "world", alive: true, mainHand: hand, inventory: designs.map((d) => d.id) });
    for (const m of mobs) s.add({ id: m.id, type: m.kind === "player" ? "minecraft:player" : "minecraft:pig", kind: m.kind ?? "animal", pos: m.at, health: 10, maxHealth: 10, world: "world", alive: true, height: m.h ?? 0.9 });
    return s;
  };
  const eyeLevel = 64 + EYE_HEIGHT - 0.6; // a floating pig's feet so the eye ray crosses its box
  it("pellet directions: one pellet flies straight; the pattern stays inside the cone and is fixed", () => {
    assert.deepEqual(pelletDir([0, 0, 1], 0, 1, 10), [0, 0, 1]);
    for (let i = 0; i < 12; i++) {
      const d = pelletDir([0, 0, 1], i, 12, 6);
      const ang = Math.acos(d[2]) * 180 / Math.PI;
      assert.ok(ang <= 6 + 1e-9 && ang > 0, `${i}: ${ang}`);
      assert.deepEqual(d, pelletDir([0, 0, 1], i, 12, 6));
    }
    assert.ok(Math.abs(Math.hypot(...pelletDir([0, 1, 0], 3, 5, 10)) - 1) < 1e-12, "straight up still works");
    assert.ok(Math.abs(rayHitsBox([0, 65, 0], [0, 0, 1], 10, [0, 64.6, 4], 0.9)! - (4 - 0.3 - WEAPON_LIMITS.raySize)) < 1e-9);
    assert.equal(rayHitsBox([0, 65, 0], [0, 0, 1], 3, [0, 64.6, 4], 0.9), null, "beyond range");
  });
  it("hitscan: the first entity on the ray takes the shot, a mob behind it does not", () => {
    const s = world([load("tap_pistol")], "tap_pistol", [{ id: "near", at: [0, eyeLevel, 4] }, { id: "far", at: [0, eyeLevel, 8] }]);
    s.event({ tick: 1, type: "right_click", player: "you", look: { target: "far", point: [0, eyeLevel, 8] } });
    assert.deepEqual(s.of("damage").map((l) => [l.subject, l.detail?.amount]), [["near", 4]]);
    assert.equal(s.entities.get("far")!.health, 10);
  });
  it("hitscan: a block (the look point without an entity) stops the ray", () => {
    const s = world([load("tap_pistol")], "tap_pistol", [{ id: "behind_wall", at: [0, eyeLevel, 8] }]);
    s.event({ tick: 1, type: "right_click", player: "you", look: { point: [0, 64 + EYE_HEIGHT, 5] } });
    assert.equal(s.of("damage").length, 0);
    assert.deepEqual(s.of("hitscan")[0].detail?.hits, []);
  });
  it("shotgun: pellets are SUMMED per target and dealt once (one damage event per target)", () => {
    const s = world([load("scatter_gun")], "scatter_gun", [{ id: "pig", at: [0, eyeLevel, 4] }]);
    s.event({ tick: 1, type: "right_click", player: "you", look: { target: "pig", point: [0, eyeLevel, 4] } });
    assert.deepEqual(s.of("damage").map((l) => [l.subject, l.detail?.amount]), [["pig", 4]], "4 pellets x 1 damage, one hit");
    assert.equal(s.entities.get("pig")!.health, 6);
    assert.equal(s.of("particles").length, 1, "the per-target action ran once for the one target");
    // 4 ticks later (cooldown) the second shot lands too: the invulnerability reset is part of the component
    s.event({ tick: 6, type: "right_click", player: "you", look: { target: "pig", point: [0, eyeLevel, 4] } });
    assert.equal(s.entities.get("pig")!.health, 2);
    assert.equal(s.of("hitscan")[1].detail?.reset, true);
  });
  it("shotgun spread: wide pellets can miss a small target; the result is deterministic", () => {
    const wide = { ...load("scatter_gun"), abilities: [{ ...load("scatter_gun").abilities[0], actions: [{ type: "hitscan" as const, range: 16, damage: 1, pellets: 8, spread: 15 }] }] };
    const run = () => { const s = world([wide], "scatter_gun", [{ id: "pig", at: [0, eyeLevel, 6] }]); s.event({ tick: 1, type: "right_click", player: "you", look: { target: "pig", point: [0, eyeLevel, 6] } }); return s.entities.get("pig")!.health; };
    const h = run();
    assert.ok(h > 2 && h < 10, `some pellets miss at 6 blocks with 15 degrees: health ${h}`);
    assert.equal(run(), h);
  });
  it("beam: pulses every interval, first entity each pulse, ends when the item leaves the hand", () => {
    const s = world([load("ion_beam")], "ion_beam", [{ id: "pig", at: [0, eyeLevel, 6] }]);
    s.event({ tick: 1, type: "right_click", player: "you", look: { target: "pig", point: [0, eyeLevel, 6] } });
    s.event({ tick: 60, type: "advance" });
    assert.equal(s.of("damage").length, 10, "40 ticks / 4 = 10 pulses");
    assert.equal(s.entities.get("pig")!.health, 5);
    const t = world([load("ion_beam")], "ion_beam", [{ id: "pig", at: [0, eyeLevel, 6] }]);
    t.event({ tick: 1, type: "right_click", player: "you", look: { target: "pig", point: [0, eyeLevel, 6] } });
    t.event({ tick: 10, type: "hold", player: "you", mainHand: null });
    t.event({ tick: 60, type: "advance" });
    assert.equal(t.of("damage").length, 3, "pulses at 1, 5, 9; the item is put away at 10");
    assert.ok(t.of("beam_end").length === 1);
  });
  it("area blast: linear falloff from the centre, players scaled, never the user", () => {
    const rod = load("blast_rod");
    const s = world([rod], "blast_rod", [{ id: "centre", at: [0, 64, 6], h: 0.9 }, { id: "side", at: [2, 64, 6], h: 0.9 }, { id: "ally", at: [0, 64, 8.5], kind: "player", h: 1.8 }, { id: "far", at: [0, 64, 12], h: 0.9 }]);
    s.event({ tick: 1, type: "right_click", player: "you", look: { target: "centre", point: [0, 64.45, 6] } });
    const dmg = Object.fromEntries(s.of("damage").map((l) => [l.subject, l.detail?.amount]));
    assert.equal(dmg.centre, 6, "full damage at the centre");
    assert.equal(dmg.side, 3, "half way to the edge: half damage");
    assert.ok(dmg.ally > 0 && dmg.ally < 6 * 0.5, `a player takes playerScale of it: ${dmg.ally}`);
    assert.equal(dmg.far, undefined, "outside the radius");
    assert.equal(dmg.you, undefined, "never the user");
  });
  it("a rocket: projectile_hit -> area_blast at the impact point", () => {
    const s = world([load("rocket_launcher")], "rocket_launcher", [{ id: "pig", at: [10, 64, 0] }]);
    s.event({ tick: 1, type: "sneak_start", player: "you" });
    s.event({ tick: 2, type: "right_click", player: "you" });
    s.event({ tick: 12, type: "projectile_hit", player: "you", tag: "rocket", item: "rocket_launcher", point: [10, 64.45, 0] });
    assert.ok(s.of("launch").length === 1 && s.of("area_blast").length === 1);
    assert.equal(s.of("damage")[0].subject, "pig");
    assert.ok(s.of("push_from").length === 1, "knockback with the same falloff");
  });
});

describe("weapons: studio, prompt, routing, perf audit, service bundle", () => {
  it("the studio palette inserts valid weapon actions (with the cooldown a click weapon needs)", () => {
    for (const k of ["hitscan", "beam", "area_blast"]) {
      const files = [gun([{ type: "play_sound", sound: "minecraft:ui.button.click" }], {}, { type: "right_click", targetRange: 16 })] as unknown as Parameters<typeof insertAction>[0];
      const r = insertAction(files, "gun", "fire", "", ACTION_TEMPLATES[k]({ marks: [] }));
      assert.ok(r.ok);
      const v = V(r.ok ? r.files[0] : null);
      assert.ok(v.ok, `${k}: ${JSON.stringify(v.errors)}`);
    }
    const h = ACTION_TEMPLATES.hitscan({ marks: [] });
    assert.deepEqual(childLists(h).map((c) => c.key), ["actions"], "a hitscan can hold per-target actions");
    const nested = insertAction([gun([h]) as unknown as Parameters<typeof insertAction>[0][number]], "gun", "fire", "a0", { type: "knockback", strength: 1 });
    assert.ok(nested.ok && nested.path === "a0.n0");
    assert.ok(nested.ok && V(nested.files[0]).ok);
  });
  it("the build prompt documents the weapons and says full-auto is impossible in a plugin", () => {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const P = require(path.join(ROOT, "services/modbuilder/prompts.js"));
    assert.match(P.DESIGN_SECTION, /hitscan \{"range":1-64/);
    assert.match(P.DESIGN_SECTION, /beam \{"range":1-32/);
    assert.match(P.DESIGN_SECTION, /area_blast \{"radius":1-8/);
    assert.match(P.DESIGN_SECTION, /true full-auto is NOT possible in a plugin/);
    assert.match(P.DESIGN_SECTION, /"cooldownTicks" >= 4/);
  });
  it("gun / shotgun / laser requests route to the item designer", () => {
    for (const t of ["a shotgun that fires 8 pellets on right-click", "a laser rifle that shoots a beam", "a rocket launcher whose rockets blast mobs in a radius"]) assert.ok(matchDesignerWords(t).length > 0, t);
  });
  it("the perf audit lists the weapon caps (they read the real constants)", () => {
    const rows = perfCapAudit().filter((r) => r.emitter === "item designer (weapons)");
    assert.ok(rows.length >= 5);
    assert.ok(rows.every((r) => r.status === "ok" || r.status === "added-2026-10-12"));
    assert.ok(rows.some((r) => r.cap.includes("live beams") && r.value === WEAPON_LIMITS.liveBeams));
    assert.ok(rows.some((r) => r.cap.includes("click cooldown") && r.value === WEAPON_LIMITS.minClickCooldown));
    assert.equal(BUDGET.actions, 64);
  });
  it("TS == the generated service bundle on the weapon fixtures", () => {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const DZ = require(path.join(ROOT, "services/modbuilder/designer-spec.js"));
    for (const v of ["1.21.1", "1.21.11", "26.2"]) {
      for (const d of [...ALL(), gun([{ type: "hitscan", range: 8, damage: 1 }], { cooldownTicks: 0 })]) {
        const a = validateDesign(d, { version: v, namespace: NS }), b = DZ.validateDesign(d, { version: v, namespace: NS });
        assert.deepEqual(b.errors.map((e: { code: string }) => e.code), a.errors.map((e) => e.code), `${v} ${d.id}`);
      }
      assert.equal(DZ.compileDesigns(ALL(), { version: v, namespace: NS, pluginName: "NxArmory" }).hash, compile(ALL(), v).hash, v);
    }
  });
});

