// Cyrus designer TECHNIQUE components (feature/cyrus-mc-techniques, 2026-10-12, BF technique catalogue #2): the break_block
// trigger + vein_break (vein miner / tree capitator). Pure: the switch (CYRUS_MC_TECHNIQUES / MB_MC_TECHNIQUES, OFF by
// default), the spec (caps, filters, deny list, placement rules), static budgets, the compiler (Veins.java + BREAK_BLOCK
// only in mods that use it, every other mod byte-identical), the Java text rules (breaks as the player, loaded chunks only,
// no timer), the reference simulator (BFS order, caps, protection, item put away), studio, prompt, routing, perf rows, and
// the TS == generated service bundle. Real javac + strict scan + Test Flight playtest: test/cyrus-designer-techniques-real.ts.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { CAPS, VEIN_LIMITS, techniquesOn, validateDesign, validateDesigns, type ItemDesign } from "../lib/cyrus/designer/spec";
import { compileDesigns, triggerSource, usesVeins, type CompileOk } from "../lib/cyrus/designer/compile";
import { COMPONENTS, libraryHash } from "../lib/cyrus/designer/components";
import { TRIGGER_JAVA } from "../lib/cyrus/designer/components/java";
import { VEINS_JAVA, VEINS_META } from "../lib/cyrus/designer/components/veins";
import { DesignSimulator, isLogId, isOreId, veinFamily, type Vec } from "../lib/cyrus/designer/simulate";
import { ACTION_TEMPLATES, insertAction } from "../lib/cyrus/designer/studio/edit";
import { itemButtons, simulateItem } from "../lib/cyrus/designer/studio/sim";
import { matchDesignerWords } from "../lib/cyrus/designer/route";
import { perfCapAudit } from "../lib/cyrus/safety/perf-caps";

const ROOT = path.join(__dirname, "..");
const FX = path.join(__dirname, "fixtures/cyrus-designer-techniques");
const NS = "nx_r7techni";
const NAMES = ["vein_pickaxe", "timber_axe", "sneak_drill"];
const load = (n: string): ItemDesign => JSON.parse(fs.readFileSync(path.join(FX, `${n}.json`), "utf8"));
const ALL = () => NAMES.map(load);
const V = (d: unknown, v = "1.21.11", techniques = true) => validateDesign(d, { version: v, namespace: NS, techniques });
const codes = (r: ReturnType<typeof validateDesign>) => r.errors.map((e) => e.code);
const wcodes = (r: ReturnType<typeof validateDesign>) => r.warnings.map((e) => e.code);
const tool = (actions: unknown[], trigger: unknown = { type: "break_block", blocks: ["ores"] }, ab: Record<string, unknown> = {}) => ({ schemaVersion: 1, id: "tool", base: "minecraft:iron_pickaxe", name: { text: "Tool" }, abilities: [{ id: "go", name: "Go", trigger, actions, ...ab }] });
const VEIN = { type: "vein_break", maxBlocks: 8 };
const compile = (d: unknown[], v = "1.21.11"): CompileOk => { const r = compileDesigns(d, { version: v, namespace: NS, pluginName: "NxTools", techniques: true }); if (!r.ok) throw new Error(JSON.stringify(r.errors)); return r; };
const withEnv = <T>(k: string, val: string | undefined, f: () => T): T => { const prev = process.env[k]; if (val === undefined) delete process.env[k]; else process.env[k] = val; try { return f(); } finally { if (prev === undefined) delete process.env[k]; else process.env[k] = prev; } };

describe("techniques: the switch (OFF by default, fails closed)", () => {
  it("techniquesOn reads CYRUS_MC_TECHNIQUES (portal) or MB_MC_TECHNIQUES (service); nothing set = off", () => {
    assert.equal(techniquesOn({}), false);
    assert.equal(techniquesOn({ CYRUS_MC_TECHNIQUES: "1" }), true);
    assert.equal(techniquesOn({ MB_MC_TECHNIQUES: "1" }), true);
    assert.equal(techniquesOn({ CYRUS_MC_TECHNIQUES: "true" }), false, "only the exact value 1");
  });
  it("while off, break_block and vein_break are refused (technique_off), with the switch named", () => {
    const r = withEnv("CYRUS_MC_TECHNIQUES", undefined, () => withEnv("MB_MC_TECHNIQUES", undefined, () => validateDesign(load("vein_pickaxe"), { version: "1.21.11", namespace: NS })));
    assert.ok(!r.ok);
    assert.deepEqual([...new Set(codes(r))], ["technique_off"]);
    assert.match(r.errors[0].message, /CYRUS_MC_TECHNIQUES/);
    assert.ok(withEnv("MB_MC_TECHNIQUES", "1", () => validateDesign(load("vein_pickaxe"), { version: "1.21.11", namespace: NS })).ok, "the service switch turns it on");
    assert.ok(!V(load("vein_pickaxe"), "1.21.11", false).ok, "an explicit techniques:false wins over the environment");
  });
  it("existing designs are unaffected by the switch either way", () => {
    const void_reaper = JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-designer/void_reaper.json"), "utf8"));
    assert.ok(V(void_reaper, "1.21.11", false).ok && V(void_reaper, "1.21.11", true).ok);
  });
});

describe("techniques: the vein spec", () => {
  it("the fixtures are valid on every buildable version (+ 26.2)", () => {
    for (const v of ["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.2"]) {
      const r = validateDesigns(ALL(), { version: v, namespace: NS, techniques: true });
      assert.ok(r.ok, `${v}: ${JSON.stringify(r.results.flatMap((x) => x.errors))}`);
    }
  });
  it("static budget: every block is an action, the step chain is one task", () => {
    const r = V(load("timber_axe")); assert.ok(r.ok);
    const b = r.budgets[0];
    assert.equal(b.actions, 1 + 32); assert.equal(b.tasks, 1); assert.equal(b.entities, 0);
    assert.ok(codes(V(tool([{ type: "vein_break", maxBlocks: 48 }, ...Array(16).fill({ type: "actionbar", text: "x" })].slice(0, 16)))).includes("budget_actions"), "48 blocks + 16 actions > 64");
    assert.ok(V(tool([{ type: "vein_break", maxBlocks: 48 }])).ok);
  });
  it("placement and filter rules", () => {
    assert.ok(codes(V(tool([VEIN], { type: "right_click" }))).includes("vein_trigger"), "only break_block");
    assert.ok(codes(V(tool([VEIN], { type: "break_block" }))).includes("vein_unfiltered"), "a vein needs a block filter");
    assert.ok(V(tool([{ type: "actionbar", text: "you broke a block" }], { type: "break_block" })).ok, "an unfiltered break_block without a vein is fine");
    assert.ok(codes(V(tool([{ type: "delayed", delayTicks: 5, actions: [VEIN] }]))).includes("vein_in_delayed"));
    assert.ok(codes(V(tool([{ type: "query_nearby", radius: 4, max: 2, actions: [VEIN] }]))).includes("vein_in_loop"));
    assert.ok(codes(V(tool([VEIN, VEIN]))).includes("vein_twice"));
    assert.ok(codes(V(tool([{ type: "branch", if: [{ type: "sneaking" }], then: [VEIN], else: [VEIN] }]))).includes("vein_twice"));
    assert.ok(V(tool([{ type: "branch", if: [{ type: "sneaking" }], then: [VEIN] }])).ok, "inside a branch is fine");
    for (const bad of ["minecraft:chest", "minecraft:spawner", "minecraft:bedrock", "minecraft:red_bed", "minecraft:oak_door", "minecraft:oak_sign", "minecraft:shulker_box", "minecraft:barrier"]) assert.ok(codes(V(tool([VEIN], { type: "break_block", types: [bad] }))).includes("vein_denied"), bad);
    assert.ok(codes(V(tool([VEIN], { type: "break_block", types: ["minecraft:not_a_block"] }))).includes("unknown_vanilla_id"));
    assert.ok(codes(V(tool([VEIN], { type: "break_block", blocks: ["dirt"] }))).includes("schema"), "groups are ores / logs only");
    assert.ok(wcodes(V(tool([{ type: "vein_break", maxBlocks: 4, perTick: 8 }]))).includes("vein_per_tick"));
  });
  it("hard caps (the schema refuses just outside, the runtime Java clamps to the same)", () => {
    for (const [k, lo, hi] of [["maxBlocks", 0, 49], ["perTick", 0, 17], ["radius", 0.5, 12.5]] as const) {
      const a = (x: number) => tool([{ type: "vein_break", maxBlocks: 8, [k]: x }]);
      assert.ok(codes(V(a(lo))).includes("schema"), `${k}=${lo}`); assert.ok(codes(V(a(hi))).includes("schema"), `${k}=${hi}`);
    }
    assert.deepEqual([CAPS.veinBlocks, CAPS.veinPerTick, CAPS.veinRadius], [[1, 48], [1, 16], [1, 12]]);
  });
});

describe("techniques: the compiler and the component", () => {
  it("Veins.java + BREAK_BLOCK only in mods that use them; every other mod is byte-identical", () => {
    const r = compile(ALL());
    const v = r.files.find((f) => f.path.endsWith("/designer/Veins.java"));
    assert.ok(v && v.role === "component" && !v.content.includes("__PKG__"));
    const trig = r.files.find((f) => f.path.endsWith("/designer/Trigger.java"))!.content;
    assert.match(trig, /ITEM_CONSUME, CHARGE_RELEASE, BREAK_BLOCK\n/);
    const plain = compileDesigns([JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-designer/void_reaper.json"), "utf8"))], { version: "1.21.11", namespace: "nx_r7design", pluginName: "VoidArsenal" });
    assert.ok(plain.ok);
    assert.ok(!plain.files.some((f) => f.path.endsWith("Veins.java")));
    assert.ok(plain.files.find((f) => f.path.endsWith("/designer/Trigger.java"))!.content.endsWith(TRIGGER_JAVA.replace(/__PKG__/g, plain.pkg).slice(-60)));
    assert.doesNotMatch(plain.files.find((f) => f.path.endsWith("/designer/Trigger.java"))!.content, /BREAK_BLOCK/);
    assert.equal(plain.libraryHash, libraryHash());
    assert.notEqual(r.libraryHash, libraryHash());
    assert.ok(!COMPONENTS.some((c) => c.id === VEINS_META.id));
    assert.equal(triggerSource(false), TRIGGER_JAVA);
    assert.ok(usesVeins(load("timber_axe")) && !usesVeins(JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-designer/storm_staff.json"), "utf8"))));
  });
  it("the ability filters in check(), calls the component with config parameters; the main class registers the listener", () => {
    const r = compile(ALL());
    const src = (cls: string) => r.files.find((f) => f.path.endsWith(`/abilities/${cls}.java`))!.content;
    const pick = src("VeinPickaxeVein");
    assert.match(pick, /Trigger\.BREAK_BLOCK\);/);
    assert.match(pick, /if \(!Veins\.matches\(a\.point\(\), 1, null\)\) return false;/);
    assert.match(pick, /Veins\.vein\(d, a, p_a0_max_blocks, p_a0_per_tick, p_a0_radius, true, false\);/);
    assert.match(src("TimberAxeFell"), /Veins\.matches\(a\.point\(\), 2, null\)/);
    assert.match(src("TimberAxeFell"), /Veins\.vein\(d, a, p_a0_max_blocks, p_a0_per_tick, p_a0_radius, true, true\);/);
    const drill = src("SneakDrillDrill");
    assert.match(drill, /private static final Set<Material> BREAK_TYPES = Set\.of\(Material\.STONE, Material\.DEEPSLATE\);/);
    assert.match(drill, /Veins\.matches\(a\.point\(\), 0, BREAK_TYPES\)/);
    assert.match(drill, /a\.player\(\)\.isSneaking\(\)/);
    assert.match(drill, /, false, true\);/, "diagonal off, exact");
    const main = r.files.find((f) => f.path.endsWith("/NxTools.java"))!.content;
    assert.match(main, /veins = new Veins\(designer\);\n\s+veins\.start\(\);/);
    assert.match(main, /if \(veins != null\) veins\.stop\(\);/);
    const cfg = r.files.find((f) => f.path.endsWith("config.yml"))!.content;
    for (const line of ["# Vein Mine: most extra blocks one break takes with it (1 to 48)", "max_blocks: 16", "# Fell: blocks broken per tick (1 to 16)", "per_tick: 8", "# Drill: vein reach from the first block (blocks) (1.0 to 12.0)"]) assert.ok(cfg.includes(line), line);
    assert.match(r.readme, /Break a block with it/);
    assert.match(r.readme, /broken as you, a few per tick, only where the world is loaded.*protection plugins can stop any of them/);
  });
  it("the component Java: breaks AS the player, never loads a chunk, no timer, caps from the spec", () => {
    for (const s of ["p.breakBlock(b)", "isChunkLoaded(wx >> 4, wz >> 4)", "EventPriority.MONITOR, ignoreCancelled = true", "if (d.busy(p)) return;", "d.enter(p)", "d.tasks().later(1,", "Tag.LOGS.isTagged(m)", "Tag.IRON_ORES", "HandlerList.unregisterAll(this)"]) assert.ok(VEINS_JAVA.includes(s), s);
    for (const bad of ["breakNaturally", "setType(", "getChunkAt(", "loadChunk", "getChunkAtAsync", "runTaskTimer", "Thread", "reflect", "dispatchCommand", "getLoadedChunks", "async", "createExplosion"]) assert.ok(!VEINS_JAVA.includes(bad), `forbidden: ${bad}`);
    // every getBlockAt is right after a loaded-chunk check
    for (const m of VEINS_JAVA.matchAll(/getBlockAt\(/g)) assert.match(VEINS_JAVA.slice(Math.max(0, m.index! - 200), m.index!), /isChunkLoaded\(/);
    assert.match(VEINS_JAVA, new RegExp(`MAX_BLOCKS = ${CAPS.veinBlocks[1]};`));
    assert.match(VEINS_JAVA, new RegExp(`MAX_PER_TICK = ${CAPS.veinPerTick[1]};`));
    assert.match(VEINS_JAVA, new RegExp(`LIVE_VEINS = ${VEIN_LIMITS.liveVeins};`));
    assert.match(VEINS_JAVA, /if \(!a\.budget\(\)\.action\(\)\) \{ r\.queue\.clear\(\); break; \}/, "every block spends an action");
  });
});

describe("techniques: the reference simulator (vein twin)", () => {
  const world = (d: ItemDesign, blocks: [Vec, string][]) => {
    const s = new DesignSimulator([d], { namespace: NS });
    s.add({ id: "you", type: "minecraft:player", kind: "player", pos: [0, 64, 0], health: 20, maxHealth: 20, world: "world", alive: true, mainHand: d.id, inventory: [d.id] });
    for (const [p, t] of blocks) s.setBlock(p, t);
    return s;
  };
  const column = (x: number, z: number, y0: number, n: number, t = "oak_log"): [Vec, string][] => Array.from({ length: n }, (_, i) => [[x, y0 + i, z] as Vec, t]);
  it("families: an ore and its deepslate twin are one vein; logs are their own species with match same", () => {
    assert.equal(veinFamily("iron_ore", false), veinFamily("deepslate_iron_ore", false));
    assert.notEqual(veinFamily("iron_ore", true), veinFamily("deepslate_iron_ore", true));
    assert.equal(veinFamily("nether_gold_ore", false), "#gold_ores");
    assert.ok(isOreId("ancient_debris") && isOreId("nether_quartz_ore") && !isOreId("stone"));
    assert.ok(isLogId("oak_log") && isLogId("stripped_birch_log") && isLogId("crimson_stem") && !isLogId("oak_planks"));
  });
  it("a tree falls: perTick per tick, the next step one tick later, the first log by vanilla", () => {
    const s = world(load("timber_axe"), column(2, 2, 64, 20));
    s.event({ tick: 1, type: "break_block", player: "you", at: [2, 64, 2] });
    s.event({ tick: 10, type: "advance" });
    const steps = s.of("vein_step").map((l) => (l.detail!.broke as string[]).length);
    assert.deepEqual(steps, [8, 8, 3], "19 more logs, 8 per tick");
    assert.deepEqual(s.of("vein_step").map((l) => l.tick), [2, 3, 4]);
    assert.equal([...s.blocks.values()].filter((t) => t === "oak_log").length, 0);
    assert.equal(s.of("vein_end")[0].detail!.broken, 19);
  });
  it("caps: maxBlocks and radius bound a huge vein", () => {
    const big: [Vec, string][] = []; for (let x = -15; x <= 15; x++) for (let z = -15; z <= 15; z++) big.push([[x, 60, z], "coal_ore"]);
    const s = world(load("vein_pickaxe"), big);
    s.event({ tick: 1, type: "break_block", player: "you", at: [0, 60, 0] });
    s.event({ tick: 40, type: "advance" });
    assert.equal(s.of("vein_end")[0].detail!.broken, 16, "maxBlocks 16");
    const gone = big.filter(([p]) => s.blockAt(p) === "air").map(([p]) => Math.hypot(p[0], p[2]));
    assert.ok(Math.max(...gone) <= 6 + 1e-9, "radius 6");
  });
  it("protection: a protected block stays and the vein does not spread through it; a cancelled first break fires nothing", () => {
    const d = { ...load("timber_axe"), abilities: [{ ...load("timber_axe").abilities[0], actions: [{ type: "vein_break" as const, maxBlocks: 32, perTick: 8, radius: 10, diagonal: false, match: "same" as const }] }] };
    const s = world(d, column(2, 2, 64, 10));
    s.protectedBlocks.add("2,67,2");
    s.event({ tick: 1, type: "break_block", player: "you", at: [2, 64, 2] });
    s.event({ tick: 10, type: "advance" });
    assert.equal(s.blockAt([2, 67, 2]), "oak_log");
    assert.equal(s.blockAt([2, 68, 2]), "oak_log", "above the protected log is unreachable without diagonals");
    assert.equal(s.of("vein_end")[0].detail!.broken, 2);
    assert.deepEqual(s.of("vein_step")[0].detail!.refused, ["2,67,2"]);
    const t = world(load("timber_axe"), column(2, 2, 64, 5));
    t.protectedBlocks.add("2,64,2");
    t.event({ tick: 1, type: "break_block", player: "you", at: [2, 64, 2] });
    assert.equal(t.of("fired").length, 0); assert.equal(t.of("break_cancelled").length, 1);
  });
  it("unloaded chunks are never looked at; the vein stops when the tool is put away", () => {
    const row: [Vec, string][] = Array.from({ length: 12 }, (_, i) => [[10 + i, 64, 0] as Vec, "oak_log"]);
    const s = world({ ...load("timber_axe"), abilities: [{ ...load("timber_axe").abilities[0], actions: [{ type: "vein_break", maxBlocks: 32, perTick: 1, radius: 12, match: "same" }] }] }, row);
    s.loadedChunks = new Set(["0,0"]); // x 0..15 loaded, 16+ not
    s.event({ tick: 1, type: "break_block", player: "you", at: [10, 64, 0] });
    s.event({ tick: 20, type: "advance" });
    assert.equal(s.of("vein_end")[0].detail!.broken, 5, "x 11..15 only");
    assert.equal(s.blockAt([16, 64, 0]), "oak_log");
    const t = world({ ...load("timber_axe"), abilities: [{ ...load("timber_axe").abilities[0], actions: [{ type: "vein_break", maxBlocks: 32, perTick: 1, radius: 12, match: "same" }] }] }, column(2, 2, 64, 10));
    t.event({ tick: 1, type: "break_block", player: "you", at: [2, 64, 2] });
    t.event({ tick: 3, type: "hold", player: "you", mainHand: null });
    t.event({ tick: 20, type: "advance" });
    assert.equal(t.of("vein_end")[0].detail!.why, "stopped");
    assert.equal(t.of("vein_end")[0].detail!.broken, 1, "one step ran before the axe was put away");
  });
  it("the filter: a break_block ability ignores blocks outside its groups / types; own breaks never re-trigger", () => {
    const s = world(load("vein_pickaxe"), [[[0, 60, 0], "stone"], [[1, 60, 0], "stone"]]);
    s.event({ tick: 1, type: "break_block", player: "you", at: [0, 60, 0] });
    assert.equal(s.of("fired").length, 0); assert.equal(s.of("blocked")[0].detail!.by, "block filter");
    const t = world(load("vein_pickaxe"), [[[0, 60, 0], "iron_ore"], [[1, 60, 0], "deepslate_iron_ore"], [[2, 60, 0], "iron_ore"]]);
    t.event({ tick: 1, type: "break_block", player: "you", at: [0, 60, 0] });
    t.event({ tick: 10, type: "advance" });
    assert.equal(t.of("fired").length, 1, "the vein's own breaks do not fire the ability again");
    assert.equal(t.of("vein_end")[0].detail!.broken, 2, "the deepslate twin joins the vein (match family)");
  });
});

describe("techniques: studio, prompt, routing, perf audit, service bundle", () => {
  it("the studio palette inserts a valid vein_break; the simulator offers 'Break a block' and runs the sample vein", () => {
    const files = [tool([{ type: "play_sound", sound: "minecraft:ui.button.click" }])] as unknown as Parameters<typeof insertAction>[0];
    const r = insertAction(files, "tool", "go", "", ACTION_TEMPLATES.vein_break({ marks: [] }));
    assert.ok(r.ok && V(r.files[0]).ok);
    assert.ok(itemButtons(load("vein_pickaxe")).some((b) => b.step.k === "break"));
    const sim = simulateItem([load("vein_pickaxe")] as never, "vein_pickaxe", [{ k: "break" }, { k: "wait", ticks: 20 }], NS);
    assert.ok(sim.log.some((l) => /vein ends · 5 blocks/.test(l.text)), JSON.stringify(sim.log));
    const tim = simulateItem([load("timber_axe")] as never, "timber_axe", [{ k: "break" }, { k: "wait", ticks: 20 }], NS);
    assert.ok(tim.log.some((l) => /vein ends · 6 blocks/.test(l.text)), "5 more logs of the trunk + the diagonal branch");
  });
  it("the build prompt carries the vein section only while MB_MC_TECHNIQUES=1", () => {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const P = require(path.join(ROOT, "services/modbuilder/prompts.js"));
    assert.match(P.TECHNIQUES_SECTION, /vein_break \{"maxBlocks":1-48,"perTick"\?:1-16/);
    assert.match(P.TECHNIQUES_SECTION, /\{"type":"break_block","blocks"\?:\["ores","logs"\]/);
    assert.doesNotMatch(P.DESIGN_SECTION, /vein_break/);
    const off = withEnv("MB_MC_TECHNIQUES", undefined, () => P.systemPrompt("1.21.11", { design: true }));
    const on = withEnv("MB_MC_TECHNIQUES", "1", () => P.systemPrompt("1.21.11", { design: true }));
    assert.ok(!off.includes("vein_break") && on.includes(P.TECHNIQUES_SECTION));
    assert.equal(P.TECHNIQUES_PROMPT_VERSION, "mb-tech-2026-10-12.1");
  });
  it("vein / tree words route to the designer only while the switch is on", () => {
    const t = "a vein miner pickaxe that breaks the whole ore vein";
    assert.deepEqual(withEnv("CYRUS_MC_TECHNIQUES", undefined, () => withEnv("MB_MC_TECHNIQUES", undefined, () => matchDesignerWords(t))), []);
    assert.ok(withEnv("CYRUS_MC_TECHNIQUES", "1", () => matchDesignerWords(t)).length > 0);
    assert.ok(withEnv("CYRUS_MC_TECHNIQUES", "1", () => matchDesignerWords("a tree capitator axe")).length > 0);
  });
  it("the perf audit lists the vein caps (they read the real constants)", () => {
    const rows = perfCapAudit().filter((r) => r.emitter === "item designer (veins)");
    assert.ok(rows.length >= 5);
    assert.ok(rows.some((r) => r.cap.startsWith("blocks per vein") && r.value === CAPS.veinBlocks[1]));
    assert.ok(rows.some((r) => r.cap.startsWith("live veins") && r.value === VEIN_LIMITS.liveVeins));
  });
  it("TS == the generated service bundle on the technique fixtures", () => {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const DZ = require(path.join(ROOT, "services/modbuilder/designer-spec.js"));
    for (const v of ["1.21.1", "1.21.11", "26.2"]) {
      for (const d of [...ALL(), tool([VEIN], { type: "break_block" })]) {
        for (const techniques of [true, false]) {
          const a = validateDesign(d, { version: v, namespace: NS, techniques }), b = DZ.validateDesign(d, { version: v, namespace: NS, techniques });
          assert.deepEqual(b.errors.map((e: { code: string }) => e.code), a.errors.map((e) => e.code), `${v} ${d.id} ${techniques}`);
        }
      }
      assert.equal(DZ.compileDesigns(ALL(), { version: v, namespace: NS, pluginName: "NxTools", techniques: true }).hash, compile(ALL(), v).hash, v);
    }
  });
});

toolu_017DSJ4M3en3FLxisHjd49Wy.content:
// Cyrus designer TECHNIQUE components (feature/cyrus-mc-techniques, 2026-10-12, BF technique catalogue #2): the break_block
// trigger + vein_break (vein miner / tree capitator). Pure: the switch (CYRUS_MC_TECHNIQUES / MB_MC_TECHNIQUES, OFF by
// default), the spec (caps, filters, deny list, placement rules), static budgets, the compiler (Veins.java + BREAK_BLOCK
// only in mods that use it, every other mod byte-identical), the Java text rules (breaks as the player, loaded chunks only,
// no timer), the reference simulator (BFS order, caps, protection, item put away), studio, prompt, routing, perf rows, and
// the TS == generated service bundle. Real javac + strict scan + Test Flight playtest: test/cyrus-designer-techniques-real.ts.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { CAPS, VEIN_LIMITS, techniquesOn, validateDesign, validateDesigns, type ItemDesign } from "../lib/cyrus/designer/spec";
import { compileDesigns, triggerSource, usesVeins, type CompileOk } from "../lib/cyrus/designer/compile";
import { COMPONENTS, libraryHash } from "../lib/cyrus/designer/components";
import { TRIGGER_JAVA } from "../lib/cyrus/designer/components/java";
import { VEINS_JAVA, VEINS_META } from "../lib/cyrus/designer/components/veins";
import { DesignSimulator, isLogId, isOreId, veinFamily, type Vec } from "../lib/cyrus/designer/simulate";
import { ACTION_TEMPLATES, insertAction } from "../lib/cyrus/designer/studio/edit";
import { itemButtons, simulateItem } from "../lib/cyrus/designer/studio/sim";
import { matchDesignerWords } from "../lib/cyrus/designer/route";
import { perfCapAudit } from "../lib/cyrus/safety/perf-caps";

const ROOT = path.join(__dirname, "..");
const FX = path.join(__dirname, "fixtures/cyrus-designer-techniques");
const NS = "nx_r7techni";
const NAMES = ["vein_pickaxe", "timber_axe", "sneak_drill"];
const load = (n: string): ItemDesign => JSON.parse(fs.readFileSync(path.join(FX, `${n}.json`), "utf8"));
const ALL = () => NAMES.map(load);
const V = (d: unknown, v = "1.21.11", techniques = true) => validateDesign(d, { version: v, namespace: NS, techniques });
const codes = (r: ReturnType<typeof validateDesign>) => r.errors.map((e) => e.code);
const wcodes = (r: ReturnType<typeof validateDesign>) => r.warnings.map((e) => e.code);
const tool = (actions: unknown[], trigger: unknown = { type: "break_block", blocks: ["ores"] }, ab: Record<string, unknown> = {}) => ({ schemaVersion: 1, id: "tool", base: "minecraft:iron_pickaxe", name: { text: "Tool" }, abilities: [{ id: "go", name: "Go", trigger, actions, ...ab }] });
const VEIN = { type: "vein_break", maxBlocks: 8 };
const compile = (d: unknown[], v = "1.21.11"): CompileOk => { const r = compileDesigns(d, { version: v, namespace: NS, pluginName: "NxTools", techniques: true }); if (!r.ok) throw new Error(JSON.stringify(r.errors)); return r; };
const withEnv = <T>(k: string, val: string | undefined, f: () => T): T => { const prev = process.env[k]; if (val === undefined) delete process.env[k]; else process.env[k] = val; try { return f(); } finally { if (prev === undefined) delete process.env[k]; else process.env[k] = prev; } };

describe("techniques: the switch (OFF by default, fails closed)", () => {
  it("techniquesOn reads CYRUS_MC_TECHNIQUES (portal) or MB_MC_TECHNIQUES (service); nothing set = off", () => {
    assert.equal(techniquesOn({}), false);
    assert.equal(techniquesOn({ CYRUS_MC_TECHNIQUES: "1" }), true);
    assert.equal(techniquesOn({ MB_MC_TECHNIQUES: "1" }), true);
    assert.equal(techniquesOn({ CYRUS_MC_TECHNIQUES: "true" }), false, "only the exact value 1");
  });
  it("while off, break_block and vein_break are refused (technique_off), with the switch named", () => {
    const r = withEnv("CYRUS_MC_TECHNIQUES", undefined, () => withEnv("MB_MC_TECHNIQUES", undefined, () => validateDesign(load("vein_pickaxe"), { version: "1.21.11", namespace: NS })));
    assert.ok(!r.ok);
    assert.deepEqual([...new Set(codes(r))], ["technique_off"]);
    assert.match(r.errors[0].message, /CYRUS_MC_TECHNIQUES/);
    assert.ok(withEnv("MB_MC_TECHNIQUES", "1", () => validateDesign(load("vein_pickaxe"), { version: "1.21.11", namespace: NS })).ok, "the service switch turns it on");
    assert.ok(!V(load("vein_pickaxe"), "1.21.11", false).ok, "an explicit techniques:false wins over the environment");
  });
  it("existing designs are unaffected by the switch either way", () => {
    const void_reaper = JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-designer/void_reaper.json"), "utf8"));
    assert.ok(V(void_reaper, "1.21.11", false).ok && V(void_reaper, "1.21.11", true).ok);
  });
});

describe("techniques: the vein spec", () => {
  it("the fixtures are valid on every buildable version (+ 26.2)", () => {
    for (const v of ["1.21.1", "1.21.4", "1.21.8", "1.21.11", "26.2"]) {
      const r = validateDesigns(ALL(), { version: v, namespace: NS, techniques: true });
      assert.ok(r.ok, `${v}: ${JSON.stringify(r.results.flatMap((x) => x.errors))}`);
    }
  });
  it("static budget: every block is an action, the step chain is one task", () => {
    const r = V(load("timber_axe")); assert.ok(r.ok);
    const b = r.budgets[0];
    assert.equal(b.actions, 1 + 32); assert.equal(b.tasks, 1); assert.equal(b.entities, 0);
    assert.ok(codes(V(tool([{ type: "vein_break", maxBlocks: 48 }, ...Array(16).fill({ type: "actionbar", text: "x" })].slice(0, 16)))).includes("budget_actions"), "48 blocks + 16 actions > 64");
    assert.ok(V(tool([{ type: "vein_break", maxBlocks: 48 }])).ok);
  });
  it("placement and filter rules", () => {
    assert.ok(codes(V(tool([VEIN], { type: "right_click" }))).includes("vein_trigger"), "only break_block");
    assert.ok(codes(V(tool([VEIN], { type: "break_block" }))).includes("vein_unfiltered"), "a vein needs a block filter");
    assert.ok(V(tool([{ type: "actionbar", text: "you broke a block" }], { type: "break_block" })).ok, "an unfiltered break_block without a vein is fine");
    assert.ok(codes(V(tool([{ type: "delayed", delayTicks: 5, actions: [VEIN] }]))).includes("vein_in_delayed"));
    assert.ok(codes(V(tool([{ type: "query_nearby", radius: 4, max: 2, actions: [VEIN] }]))).includes("vein_in_loop"));
    assert.ok(codes(V(tool([VEIN, VEIN]))).includes("vein_twice"));
    assert.ok(codes(V(tool([{ type: "branch", if: [{ type: "sneaking" }], then: [VEIN], else: [VEIN] }]))).includes("vein_twice"));
    assert.ok(V(tool([{ type: "branch", if: [{ type: "sneaking" }], then: [VEIN] }])).ok, "inside a branch is fine");
    for (const bad of ["minecraft:chest", "minecraft:spawner", "minecraft:bedrock", "minecraft:red_bed", "minecraft:oak_door", "minecraft:oak_sign", "minecraft:shulker_box", "minecraft:barrier"]) assert.ok(codes(V(tool([VEIN], { type: "break_block", types: [bad] }))).includes("vein_denied"), bad);
    assert.ok(codes(V(tool([VEIN], { type: "break_block", types: ["minecraft:not_a_block"] }))).includes("unknown_vanilla_id"));
    assert.ok(codes(V(tool([VEIN], { type: "break_block", blocks: ["dirt"] }))).includes("schema"), "groups are ores / logs only");
    assert.ok(wcodes(V(tool([{ type: "vein_break", maxBlocks: 4, perTick: 8 }]))).includes("vein_per_tick"));
  });
  it("hard caps (the schema refuses just outside, the runtime Java clamps to the same)", () => {
    for (const [k, lo, hi] of [["maxBlocks", 0, 49], ["perTick", 0, 17], ["radius", 0.5, 12.5]] as const) {
      const a = (x: number) => tool([{ type: "vein_break", maxBlocks: 8, [k]: x }]);
      assert.ok(codes(V(a(lo))).includes("schema"), `${k}=${lo}`); assert.ok(codes(V(a(hi))).includes("schema"), `${k}=${hi}`);
    }
    assert.deepEqual([CAPS.veinBlocks, CAPS.veinPerTick, CAPS.veinRadius], [[1, 48], [1, 16], [1, 12]]);
  });
});

describe("techniques: the compiler and the component", () => {
  it("Veins.java + BREAK_BLOCK only in mods that use them; every other mod is byte-identical", () => {
    const r = compile(ALL());
    const v = r.files.find((f) => f.path.endsWith("/designer/Veins.java"));
    assert.ok(v && v.role === "component" && !v.content.includes("__PKG__"));
    const trig = r.files.find((f) => f.path.endsWith("/designer/Trigger.java"))!.content;
    assert.match(trig, /ITEM_CONSUME, CHARGE_RELEASE, BREAK_BLOCK\n/);
    const plain = compileDesigns([JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-designer/void_reaper.json"), "utf8"))], { version: "1.21.11", namespace: "nx_r7design", pluginName: "VoidArsenal" });
    assert.ok(plain.ok);
    assert.ok(!plain.files.some((f) => f.path.endsWith("Veins.java")));
    assert.ok(plain.files.find((f) => f.path.endsWith("/designer/Trigger.java"))!.content.endsWith(TRIGGER_JAVA.replace(/__PKG__/g, plain.pkg).slice(-60)));
    assert.doesNotMatch(plain.files.find((f) => f.path.endsWith("/designer/Trigger.java"))!.content, /BREAK_BLOCK/);
    assert.equal(plain.libraryHash, libraryHash());
    assert.notEqual(r.libraryHash, libraryHash());
    assert.ok(!COMPONENTS.some((c) => c.id === VEINS_META.id));
    assert.equal(triggerSource(false), TRIGGER_JAVA);
    assert.ok(usesVeins(load("timber_axe")) && !usesVeins(JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-designer/storm_staff.json"), "utf8"))));
  });
  it("the ability filters in check(), calls the component with config parameters; the main class registers the listener", () => {
    const r = compile(ALL());
    const src = (cls: string) => r.files.find((f) => f.path.endsWith(`/abilities/${cls}.java`))!.content;
    const pick = src("VeinPickaxeVein");
    assert.match(pick, /Trigger\.BREAK_BLOCK\);/);
    assert.match(pick, /if \(!Veins\.matches\(a\.point\(\), 1, null\)\) return false;/);
    assert.match(pick, /Veins\.vein\(d, a, p_a0_max_blocks, p_a0_per_tick, p_a0_radius, true, false\);/);
    assert.match(src("TimberAxeFell"), /Veins\.matches\(a\.point\(\), 2, null\)/);
    assert.match(src("TimberAxeFell"), /Veins\.vein\(d, a, p_a0_max_blocks, p_a0_per_tick, p_a0_radius, true, true\);/);
    const drill = src("SneakDrillDrill");
    assert.match(drill, /private static final Set<Material> BREAK_TYPES = Set\.of\(Material\.STONE, Material\.DEEPSLATE\);/);
    assert.match(drill, /Veins\.matches\(a\.point\(\), 0, BREAK_TYPES\)/);
    assert.match(drill, /a\.player\(\)\.isSneaking\(\)/);
    assert.match(drill, /, false, true\);/, "diagonal off, exact");
    const main = r.files.find((f) => f.path.endsWith("/NxTools.java"))!.content;
    assert.match(main, /veins = new Veins\(designer\);\n\s+veins\.start\(\);/);
    assert.match(main, /if \(veins != null\) veins\.stop\(\);/);
    const cfg = r.files.find((f) => f.path.endsWith("config.yml"))!.content;
    for (const line of ["# Vein Mine: most extra blocks one break takes with it (1 to 48)", "max_blocks: 16", "# Fell: blocks broken per tick (1 to 16)", "per_tick: 8", "# Drill: vein reach from the first block (blocks) (1.0 to 12.0)"]) assert.ok(cfg.includes(line), line);
    assert.match(r.readme, /Break a block with it/);
    assert.match(r.readme, /broken as you, a few per tick, only where the world is loaded.*protection plugins can stop any of them/);
  });
  it("the component Java: breaks AS the player, never loads a chunk, no timer, caps from the spec", () => {
    for (const s of ["p.breakBlock(b)", "isChunkLoaded(wx >> 4, wz >> 4)", "EventPriority.MONITOR, ignoreCancelled = true", "if (d.busy(p)) return;", "d.enter(p)", "d.tasks().later(1,", "Tag.LOGS.isTagged(m)", "Tag.IRON_ORES", "HandlerList.unregisterAll(this)"]) assert.ok(VEINS_JAVA.includes(s), s);
    for (const bad of ["breakNaturally", "setType(", "getChunkAt(", "loadChunk", "getChunkAtAsync", "runTaskTimer", "Thread", "reflect", "dispatchCommand", "getLoadedChunks", "async", "createExplosion"]) assert.ok(!VEINS_JAVA.includes(bad), `forbidden: ${bad}`);
    // every getBlockAt is right after a loaded-chunk check
    for (const m of VEINS_JAVA.matchAll(/getBlockAt\(/g)) assert.match(VEINS_JAVA.slice(Math.max(0, m.index! - 200), m.index!), /isChunkLoaded\(/);
    assert.match(VEINS_JAVA, new RegExp(`MAX_BLOCKS = ${CAPS.veinBlocks[1]};`));
    assert.match(VEINS_JAVA, new RegExp(`MAX_PER_TICK = ${CAPS.veinPerTick[1]};`));
    assert.match(VEINS_JAVA, new RegExp(`LIVE_VEINS = ${VEIN_LIMITS.liveVeins};`));
    assert.match(VEINS_JAVA, /if \(!a\.budget\(\)\.action\(\)\) \{ r\.queue\.clear\(\); break; \}/, "every block spends an action");
  });
});

describe("techniques: the reference simulator (vein twin)", () => {
  const world = (d: ItemDesign, blocks: [Vec, string][]) => {
    const s = new DesignSimulator([d], { namespace: NS });
    s.add({ id: "you", type: "minecraft:player", kind: "player", pos: [0, 64, 0], health: 20, maxHealth: 20, world: "world", alive: true, mainHand: d.id, inventory: [d.id] });
    for (const [p, t] of blocks) s.setBlock(p, t);
    return s;
  };
  const column = (x: number, z: number, y0: number, n: number, t = "oak_log"): [Vec, string][] => Array.from({ length: n }, (_, i) => [[x, y0 + i, z] as Vec, t]);
  it("families: an ore and its deepslate twin are one vein; logs are their own species with match same", () => {
    assert.equal(veinFamily("iron_ore", false), veinFamily("deepslate_iron_ore", false));
    assert.notEqual(veinFamily("iron_ore", true), veinFamily("deepslate_iron_ore", true));
    assert.equal(veinFamily("nether_gold_ore", false), "#gold_ores");
    assert.ok(isOreId("ancient_debris") && isOreId("nether_quartz_ore") && !isOreId("stone"));
    assert.ok(isLogId("oak_log") && isLogId("stripped_birch_log") && isLogId("crimson_stem") && !isLogId("oak_planks"));
  });
  it("a tree falls: perTick per tick, the next step one tick later, the first log by vanilla", () => {
    const s = world(load("timber_axe"), column(2, 2, 64, 20));
    s.event({ tick: 1, type: "break_block", player: "you", at: [2, 64, 2] });
    s.event({ tick: 10, type: "advance" });
    const steps = s.of("vein_step").map((l) => (l.detail!.broke as string[]).length);
    assert.deepEqual(steps, [8, 8, 3], "19 more logs, 8 per tick");
    assert.deepEqual(s.of("vein_step").map((l) => l.tick), [2, 3, 4]);
    assert.equal([...s.blocks.values()].filter((t) => t === "oak_log").length, 0);
    assert.equal(s.of("vein_end")[0].detail!.broken, 19);
  });
  it("caps: maxBlocks and radius bound a huge vein", () => {
    const big: [Vec, string][] = []; for (let x = -15; x <= 15; x++) for (let z = -15; z <= 15; z++) big.push([[x, 60, z], "coal_ore"]);
    const s = world(load("vein_pickaxe"), big);
    s.event({ tick: 1, type: "break_block", player: "you", at: [0, 60, 0] });
    s.event({ tick: 40, type: "advance" });
    assert.equal(s.of("vein_end")[0].detail!.broken, 16, "maxBlocks 16");
    const gone = big.filter(([p]) => s.blockAt(p) === "air").map(([p]) => Math.hypot(p[0], p[2]));
    assert.ok(Math.max(...gone) <= 6 + 1e-9, "radius 6");
  });
  it("protection: a protected block stays and the vein does not spread through it; a cancelled first break fires nothing", () => {
    const d = { ...load("timber_axe"), abilities: [{ ...load("timber_axe").abilities[0], actions: [{ type: "vein_break" as const, maxBlocks: 32, perTick: 8, radius: 10, diagonal: false, match: "same" as const }] }] };
    const s = world(d, column(2, 2, 64, 10));
    s.protectedBlocks.add("2,67,2");
    s.event({ tick: 1, type: "break_block", player: "you", at: [2, 64, 2] });
    s.event({ tick: 10, type: "advance" });
    assert.equal(s.blockAt([2, 67, 2]), "oak_log");
    assert.equal(s.blockAt([2, 68, 2]), "oak_log", "above the protected log is unreachable without diagonals");
    assert.equal(s.of("vein_end")[0].detail!.broken, 2);
    assert.deepEqual(s.of("vein_step")[0].detail!.refused, ["2,67,2"]);
    const t = world(load("timber_axe"), column(2, 2, 64, 5));
    t.protectedBlocks.add("2,64,2");
    t.event({ tick: 1, type: "break_block", player: "you", at: [2, 64, 2] });
    assert.equal(t.of("fired").length, 0); assert.equal(t.of("break_cancelled").length, 1);
  });
  it("unloaded chunks are never looked at; the vein stops when the tool is put away", () => {
    const row: [Vec, string][] = Array.from({ length: 12 }, (_, i) => [[10 + i, 64, 0] as Vec, "oak_log"]);
    const s = world({ ...load("timber_axe"), abilities: [{ ...load("timber_axe").abilities[0], actions: [{ type: "vein_break", maxBlocks: 32, perTick: 1, radius: 12, match: "same" }] }] }, row);
    s.loadedChunks = new Set(["0,0"]); // x 0..15 loaded, 16+ not
    s.event({ tick: 1, type: "break_block", player: "you", at: [10, 64, 0] });
    s.event({ tick: 20, type: "advance" });
    assert.equal(s.of("vein_end")[0].detail!.broken, 5, "x 11..15 only");
    assert.equal(s.blockAt([16, 64, 0]), "oak_log");
    const t = world({ ...load("timber_axe"), abilities: [{ ...load("timber_axe").abilities[0], actions: [{ type: "vein_break", maxBlocks: 32, perTick: 1, radius: 12, match: "same" }] }] }, column(2, 2, 64, 10));
    t.event({ tick: 1, type: "break_block", player: "you", at: [2, 64, 2] });
    t.event({ tick: 3, type: "hold", player: "you", mainHand: null });
    t.event({ tick: 20, type: "advance" });
    assert.equal(t.of("vein_end")[0].detail!.why, "stopped");
    assert.equal(t.of("vein_end")[0].detail!.broken, 1, "one step ran before the axe was put away");
  });
  it("the filter: a break_block ability ignores blocks outside its groups / types; own breaks never re-trigger", () => {
    const s = world(load("vein_pickaxe"), [[[0, 60, 0], "stone"], [[1, 60, 0], "stone"]]);
    s.event({ tick: 1, type: "break_block", player: "you", at: [0, 60, 0] });
    assert.equal(s.of("fired").length, 0); assert.equal(s.of("blocked")[0].detail!.by, "block filter");
    const t = world(load("vein_pickaxe"), [[[0, 60, 0], "iron_ore"], [[1, 60, 0], "deepslate_iron_ore"], [[2, 60, 0], "iron_ore"]]);
    t.event({ tick: 1, type: "break_block", player: "you", at: [0, 60, 0] });
    t.event({ tick: 10, type: "advance" });
    assert.equal(t.of("fired").length, 1, "the vein's own breaks do not fire the ability again");
    assert.equal(t.of("vein_end")[0].detail!.broken, 2, "the deepslate twin joins the vein (match family)");
  });
});

describe("techniques: studio, prompt, routing, perf audit, service bundle", () => {
  it("the studio palette inserts a valid vein_break; the simulator offers 'Break a block' and runs the sample vein", () => {
    const files = [tool([{ type: "play_sound", sound: "minecraft:ui.button.click" }])] as unknown as Parameters<typeof insertAction>[0];
    const r = insertAction(files, "tool", "go", "", ACTION_TEMPLATES.vein_break({ marks: [] }));
    assert.ok(r.ok && V(r.files[0]).ok);
    assert.ok(itemButtons(load("vein_pickaxe")).some((b) => b.step.k === "break"));
    const sim = simulateItem([load("vein_pickaxe")] as never, "vein_pickaxe", [{ k: "break" }, { k: "wait", ticks: 20 }], NS);
    assert.ok(sim.log.some((l) => /vein ends · 5 blocks/.test(l.text)), JSON.stringify(sim.log));
    const tim = simulateItem([load("timber_axe")] as never, "timber_axe", [{ k: "break" }, { k: "wait", ticks: 20 }], NS);
    assert.ok(tim.log.some((l) => /vein ends · 6 blocks/.test(l.text)), "5 more logs of the trunk + the diagonal branch");
  });
  it("the build prompt carries the vein section only while MB_MC_TECHNIQUES=1", () => {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const P = require(path.join(ROOT, "services/modbuilder/prompts.js"));
    assert.match(P.TECHNIQUES_SECTION, /vein_break \{"maxBlocks":1-48,"perTick"\?:1-16/);
    assert.match(P.TECHNIQUES_SECTION, /\{"type":"break_block","blocks"\?:\["ores","logs"\]/);
    assert.doesNotMatch(P.DESIGN_SECTION, /vein_break/);
    const off = withEnv("MB_MC_TECHNIQUES", undefined, () => P.systemPrompt("1.21.11", { design: true }));
    const on = withEnv("MB_MC_TECHNIQUES", "1", () => P.systemPrompt("1.21.11", { design: true }));
    assert.ok(!off.includes("vein_break") && on.includes(P.TECHNIQUES_SECTION));
    assert.equal(P.TECHNIQUES_PROMPT_VERSION, "mb-tech-2026-10-12.1");
  });
  it("vein / tree words route to the designer only while the switch is on", () => {
    const t = "a vein miner pickaxe that breaks the whole ore vein";
    assert.deepEqual(withEnv("CYRUS_MC_TECHNIQUES", undefined, () => withEnv("MB_MC_TECHNIQUES", undefined, () => matchDesignerWords(t))), []);
    assert.ok(withEnv("CYRUS_MC_TECHNIQUES", "1", () => matchDesignerWords(t)).length > 0);
    assert.ok(withEnv("CYRUS_MC_TECHNIQUES", "1", () => matchDesignerWords("a tree capitator axe")).length > 0);
  });
  it("the perf audit lists the vein caps (they read the real constants)", () => {
    const rows = perfCapAudit().filter((r) => r.emitter === "item designer (veins)");
    assert.ok(rows.length >= 5);
    assert.ok(rows.some((r) => r.cap.startsWith("blocks per vein") && r.value === CAPS.veinBlocks[1]));
    assert.ok(rows.some((r) => r.cap.startsWith("live veins") && r.value === VEIN_LIMITS.liveVeins));
  });
  it("TS == the generated service bundle on the technique fixtures", () => {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const DZ = require(path.join(ROOT, "services/modbuilder/designer-spec.js"));
    for (const v of ["1.21.1", "1.21.11", "26.2"]) {
      for (const d of [...ALL(), tool([VEIN], { type: "break_block" })]) {
        for (const techniques of [true, false]) {
          const a = validateDesign(d, { version: v, namespace: NS, techniques }), b = DZ.validateDesign(d, { version: v, namespace: NS, techniques });
          assert.deepEqual(b.errors.map((e: { code: string }) => e.code), a.errors.map((e) => e.code), `${v} ${d.id} ${techniques}`);
        }
      }
      assert.equal(DZ.compileDesigns(ALL(), { version: v, namespace: NS, pluginName: "NxTools", techniques: true }).hash, compile(ALL(), v).hash, v);
    }
  });
});

