function build(r: CompileOk, lane: (typeof LANES)[number]) {
  const dir = path.join(RUN, lane.version);
  for (const f of r.files) { const abs = path.join(dir, "ws", f.path); mkdirSync(path.dirname(abs), { recursive: true }); writeFileSync(abs, f.content); }
  const classes = path.join(dir, "classes");
  mkdirSync(classes, { recursive: true });
  const sources = walk(path.join(dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).sort();
  const cp = readFileSync(lane.cp, "utf8").replace(/\n/g, "").trim();
  let out = "";
  try { out = execFileSync(`${lane.jdk}/bin/javac`, ["-J-Xmx768m", "--release", lane.release, "-proc:none", "-encoding", "UTF-8", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...sources], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }); }
  catch (e) { const x = e as { stdout?: string; stderr?: string }; return { ok: false as const, error: `${x.stderr ?? ""}${x.stdout ?? ""}`.slice(0, 6000) }; }
  for (const f of ["plugin.yml", "config.yml"]) writeFileSync(path.join(classes, f), readFileSync(path.join(dir, "ws/src/main/resources", f)));
  const entries = walk(classes).map((f) => path.relative(classes, f)).sort();
  const jarPath = path.join(dir, `${PLUGIN}-${lane.version}.jar`);
  execFileSync(`${lane.jdk}/bin/jar`, ["--create", "--file", jarPath, "--date", "2026-01-01T00:00:00Z", ...entries.flatMap((e) => ["-C", classes, e])]);
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const S = require(path.join(ROOT, "services/modbuilder/scan.js"));
  const oldPath = process.env.PATH;
  process.env.PATH = `${lane.jdk}/bin:${oldPath}`;
  let findings: { severity: string; rule: string; where: string }[] = [];
  try {
    findings = [...S.scanBytecode(classes, { profile: "strict" }), ...S.scanSource(sources.map((abs) => ({ abs, rel: path.relative(path.join(dir, "ws"), abs) })), { profile: "strict" })];
  } finally { process.env.PATH = oldPath; }
  return { ok: true as const, jarPath, jarSha256: sha(readFileSync(jarPath)), sources: sources.length, javacWarnings: (out.match(/warning: [^\n]*/g) ?? []).slice(0, 10), scanBlocks: findings.filter((f) => f.severity === "block").map((f) => `${f.rule}@${f.where}`), scanWarns: findings.filter((f) => f.severity === "warn").map((f) => `${f.rule}@${f.where}`) };
}

