// REAL runs of the designer TECHNIQUE components ON node-2 (not part of the unit suite). Branch feature/cyrus-mc-techniques.
//   scripts/devhost run --lock --max 1500 -- npx tsx test/cyrus-designer-techniques-real.ts [--out <json>]
// 1. javac --release 21 against the resolved Paper classpath of 1.21.1 / 1.21.4 / 1.21.8 / 1.21.11 and --release 25
//    against 26.2 (the technique fixtures compiled into one mod, NxTools), -Xlint, strict safety scan (bytecode + source).
// 2. Test Flight on Paper 1.21.11 with the pinned Mineflayer bot (survival) and a tiny test-only protection plugin
//    (NxProtect: cancels BlockBreakEvent inside a box, like a claim plugin). The bot DIGS real blocks; block states and
//    the tool's damage are read back over RCON. The checks prove the mechanics:
//    T-1 vein: one dug iron ore takes its 4 connected neighbours (incl. a deepslate twin, diagonals) and leaves the
//        adjacent coal ore; the tool took 5 damage (one per block: vanilla wear through Player#breakBlock); drops exist.
//    T-2 protection: a protected ore in the middle of a chain stays, the ores behind it stay (no spreading through a
//        refused block), NxProtect counted exactly 1 cancel, and the refused block cost the tool nothing (damage 3).
//    T-3 tree: an 8-log oak column falls from its bottom log (radius 10, match same).
//    T-4 control: a VANILLA iron pickaxe digs one of two touching ores; the other stays (the harness can fail).
// No AI model, no real Minecraft client; flat test world.
import { execFileSync, spawn } from "node:child_process";
import { createHash } from "node:crypto";
import { mkdirSync, readFileSync, readdirSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { compileDesigns, type CompileOk } from "../lib/cyrus/designer/compile";
import { runTestFlight, type Remote } from "../lib/cyrus/testflight/client";
import { describe as describeSummary } from "../lib/cyrus/testflight/summary";
import type { PlaytestPlan, PlaytestStep } from "../lib/cyrus/playtest/plan";

const ROOT = path.resolve(__dirname, "..");
const T = "/tank/nxeon-build/tmp";
const TF = `${T}/testflight`;
const RUN = `${T}/cyrus-techniques/run-${Date.now().toString(36)}`;
const NS = "nx_r7techni";
const PLUGIN = "NxTools";
const CMD = "nxtools";
const LANES = [
  { version: "1.21.1", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.1.txt` },
  { version: "1.21.4", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.4.txt` },
  { version: "1.21.8", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.8.txt` },
  { version: "1.21.11", jdk: `${TF}/jdk/21`, release: "21", cp: `${TF}/classpath/1.21.11.txt` },
  { version: "26.2", jdk: `${TF}/jdk/25`, release: "25", cp: `${T}/r0-26x/classpath/26.2.txt` },
];
const FLY = "1.21.11";
const FIXTURES = ["vein_pickaxe", "timber_axe", "sneak_drill"];
const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
const sha = (b: Buffer | string) => createHash("sha256").update(b).digest("hex");
const arg = (k: string) => { const i = process.argv.indexOf(k); return i > 0 ? process.argv[i + 1] : undefined; };
const designs = () => FIXTURES.map((n) => JSON.parse(readFileSync(path.join(ROOT, "test/fixtures/cyrus-designer-techniques", `${n}.json`), "utf8")));
function walk(dir: string, out: string[] = []): string[] {
  for (const e of readdirSync(dir, { withFileTypes: true })) { const p = path.join(dir, e.name); if (e.isDirectory()) walk(p, out); else out.push(p); }
  return out;
}
const localRemote: Remote = {
  exec: (command, opts = {}) => new Promise((resolve) => {
    const child = spawn("bash", ["-c", command], { stdio: ["pipe", "pipe", "pipe"] });
    let stdout = "", stderr = "";
    child.stdout.on("data", (d) => (stdout += d)); child.stderr.on("data", (d) => (stderr += d));
    const t = setTimeout(() => child.kill("SIGKILL"), opts.timeoutMs ?? 120000);
    child.on("close", (code) => { clearTimeout(t); resolve({ code, stdout, stderr }); });
    child.stdin.on("error", () => {}); child.stdin.end(opts.input ?? undefined);
  }),
};
async function fly(spec: Parameters<typeof runTestFlight>[0], label: string) {
  for (let attempt = 1, wait = 15000; attempt <= 12; attempt++, wait = Math.min(wait * 2, 120000)) {
    const r = await runTestFlight(spec, { remote: localRemote });
    if (r.report.status !== "busy") return r;
    console.log(`${label}: node-2 busy (another flight), retry ${attempt} in ${wait / 1000}s`);
    await sleep(wait);
  }
  throw new Error(`${label}: node-2 stayed busy`);
}

type Lane = (typeof LANES)[number];
function javac(dir: string, files: { path: string; content: string }[], lane: Lane, name: string, scan: boolean) {
  for (const f of files) { const abs = path.join(dir, "ws", f.path); mkdirSync(path.dirname(abs), { recursive: true }); writeFileSync(abs, f.content); }
  const classes = path.join(dir, "classes");
  mkdirSync(classes, { recursive: true });
  const sources = walk(path.join(dir, "ws/src/main/java")).filter((f) => f.endsWith(".java")).sort();
  const cp = readFileSync(lane.cp, "utf8").replace(/\n/g, "").trim();
  let out = "";
  try { out = execFileSync(`${lane.jdk}/bin/javac`, ["-J-Xmx768m", "--release", lane.release, "-proc:none", "-encoding", "UTF-8", "-Xlint:deprecation,removal", "-cp", cp, "-d", classes, ...sources], { encoding: "utf8", stdio: ["ignore", "pipe", "pipe"] }); }
  catch (e) { const x = e as { stdout?: string; stderr?: string }; return { ok: false as const, error: `${x.stderr ?? ""}${x.stdout ?? ""}`.slice(0, 6000) }; }
  for (const f of readdirSync(path.join(dir, "ws/src/main/resources"))) writeFileSync(path.join(classes, f), readFileSync(path.join(dir, "ws/src/main/resources", f)));
  const entries = walk(classes).map((f) => path.relative(classes, f)).sort();
  const jarPath = path.join(dir, `${name}-${lane.version}.jar`);
  execFileSync(`${lane.jdk}/bin/jar`, ["--create", "--file", jarPath, "--date", "2026-01-01T00:00:00Z", ...entries.flatMap((e) => ["-C", classes, e])]);
  let findings: { severity: string; rule: string; where: string }[] = [];
  if (scan) {
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const S = require(path.join(ROOT, "services/modbuilder/scan.js"));
    const oldPath = process.env.PATH;
    process.env.PATH = `${lane.jdk}/bin:${oldPath}`;
    try { findings = [...S.scanBytecode(classes, { profile: "strict" }), ...S.scanSource(sources.map((abs) => ({ abs, rel: path.relative(path.join(dir, "ws"), abs) })), { profile: "strict" })]; }
    finally { process.env.PATH = oldPath; }
  }
  return { ok: true as const, jarPath, jarSha256: sha(readFileSync(jarPath)), sources: sources.length, javacWarnings: (out.match(/warning: [^\n]*/g) ?? []).slice(0, 10), scanBlocks: findings.filter((f) => f.severity === "block").map((f) => `${f.rule}@${f.where}`), scanWarns: findings.filter((f) => f.severity === "warn").map((f) => `${f.rule}@${f.where}`) };
}

// Test-only protection plugin (stands in for WorldGuard / GriefPrevention): cancels BlockBreakEvent inside a box at LOWEST.
const PROTECT_JAVA = `package dev.nxeon.tf.protect;

import org.bukkit.block.Block;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.block.BlockBreakEvent;
import org.bukkit.plugin.java.JavaPlugin;

public final class NxProtect extends JavaPlugin implements Listener {
    private int[] box;
    private int cancelled;

    @Override
    public void onEnable() { getServer().getPluginManager().registerEvents(this, this); }

    @EventHandler(priority = EventPriority.LOWEST)
    public void onBreak(BlockBreakEvent e) {
        if (box == null) return;
        Block b = e.getBlock();
        if (b.getX() >= box[0] && b.getX() <= box[3] && b.getY() >= box[1] && b.getY() <= box[4] && b.getZ() >= box[2] && b.getZ() <= box[5]) { e.setCancelled(true); cancelled++; }
    }

    @Override
    public boolean onCommand(CommandSender s, Command c, String label, String[] a) {
        if (a.length == 6) {
            int[] n = new int[6];
            try { for (int i = 0; i < 6; i++) n[i] = Integer.parseInt(a[i]); } catch (NumberFormatException ex) { s.sendMessage("NxProtect: numbers please"); return true; }
            box = n; cancelled = 0; s.sendMessage("NxProtect box set"); return true;
        }
        if (a.length == 1 && a[0].equals("off")) { box = null; s.sendMessage("NxProtect off"); return true; }
        s.sendMessage("NxProtect cancelled " + cancelled);
        return true;
    }
}
`;
const PROTECT_YML = "name: NxProtect\nversion: 1.0.0\nmain: dev.nxeon.tf.protect.NxProtect\napi-version: '1.21'\ncommands:\n  nxprotect:\n    description: test-only protection box\n";

const srv = (command: string, expect?: string[]): PlaytestStep => ({ kind: "server", command, ...(expect ? { expect } : {}) });
const isBlock = (x: number, y: number, z: number, id: string) => srv(`execute if block ${x} ${y} ${z} minecraft:${id}`, ["Test passed"]);
const toolDamage = (mat: string, n: number) => srv(`execute if items entity {bot} weapon.mainhand minecraft:${mat}[minecraft:damage=${n}]`, ["Test passed"]);
const give = (item: string, mat: string): PlaytestStep[] => [srv(`${CMD} give ${item} {bot}`, [`Gave 1 x ${item} to`]), { kind: "hold", item: `minecraft:${mat}` }];
const PLAN: PlaytestPlan = {
  schema: 1, totalSec: 170,
  scenarios: [
    { id: "T-1", title: "vein: one dug ore takes its connected family (diagonal, deepslate twin), not the coal next to it; one damage per block", steps: [
      { kind: "join" }, ...give("vein_pickaxe", "iron_pickaxe"), srv("tp {bot} 2.5 -60 0.5 0 0"),
      srv("setblock 2 -60 2 minecraft:iron_ore"), srv("setblock 3 -60 2 minecraft:iron_ore"), srv("setblock 4 -60 2 minecraft:iron_ore"), srv("setblock 4 -59 2 minecraft:iron_ore"),
      srv("setblock 5 -59 3 minecraft:deepslate_iron_ore"), srv("setblock 3 -60 3 minecraft:coal_ore"), srv("kill @e[type=item]"), { kind: "wait", ms: 500 },
      { kind: "dig", x: 2, y: -60, z: 2 }, { kind: "wait", ms: 1500 },
      isBlock(3, -60, 2, "air"), isBlock(4, -60, 2, "air"), isBlock(4, -59, 2, "air"), isBlock(5, -59, 3, "air"), isBlock(3, -60, 3, "coal_ore"),
      toolDamage("iron_pickaxe", 5), srv("kill @e[type=item]", ["Killed"]),
    ] },
    { id: "T-2", title: "protection: a cancelled block stays, the vein does not spread through it, and it costs no wear", steps: [
      ...give("vein_pickaxe", "iron_pickaxe"), srv("tp {bot} 2.5 -60 3.5 0 0"),
      srv("fill 2 -60 5 7 -60 5 minecraft:iron_ore"), srv("nxprotect 5 -60 5 5 -60 5", ["box set"]), { kind: "wait", ms: 300 },
      { kind: "dig", x: 2, y: -60, z: 5 }, { kind: "wait", ms: 1500 },
      isBlock(3, -60, 5, "air"), isBlock(4, -60, 5, "air"), isBlock(5, -60, 5, "iron_ore"), isBlock(6, -60, 5, "iron_ore"), isBlock(7, -60, 5, "iron_ore"),
      srv("nxprotect", ["NxProtect cancelled 1"]), toolDamage("iron_pickaxe", 3), srv("nxprotect off", ["off"]),
    ] },
    { id: "T-3", title: "tree: an 8-log oak falls from its bottom log", steps: [
      ...give("timber_axe", "iron_axe"), srv("tp {bot} 2.5 -60 7.5 0 0"),
      srv("fill 2 -60 9 2 -53 9 minecraft:oak_log"), { kind: "wait", ms: 300 },
      { kind: "dig", x: 2, y: -60, z: 9 }, { kind: "wait", ms: 2000 },
      isBlock(2, -59, 9, "air"), isBlock(2, -56, 9, "air"), isBlock(2, -53, 9, "air"), toolDamage("iron_axe", 8),
    ] },
    { id: "T-4", title: "control: a vanilla pickaxe breaks only the block it digs", steps: [
      srv("give {bot} minecraft:iron_pickaxe"), { kind: "hold", item: "minecraft:iron_pickaxe" }, srv("tp {bot} 2.5 -60 9.5 0 0"),
      srv("setblock 2 -60 11 minecraft:iron_ore"), srv("setblock 3 -60 11 minecraft:iron_ore"), { kind: "wait", ms: 300 },
      { kind: "dig", x: 2, y: -60, z: 11 }, { kind: "wait", ms: 1000 },
      isBlock(2, -60, 11, "air"), isBlock(3, -60, 11, "iron_ore"),
    ] },
  ],
};

(async () => {
  mkdirSync(RUN, { recursive: true });
  const res: Record<string, unknown> = { at: new Date().toISOString(), host: "node-2", realClient: false, aiModel: "none (fixture designs)", switch: "techniques: true (CYRUS_MC_TECHNIQUES)", lanes: [] as unknown[] };
  let flyJar: { path: string; sha: string } | null = null;
  for (const lane of LANES) {
    const c = compileDesigns(designs(), { version: lane.version, namespace: NS, pluginName: PLUGIN, techniques: true });
    if (!c.ok) { (res.lanes as unknown[]).push({ version: lane.version, compile: c.errors }); console.log(`${lane.version}: compile refused ${JSON.stringify(c.errors).slice(0, 300)}`); continue; }
    const b = javac(path.join(RUN, lane.version), (c as CompileOk).files, lane, PLUGIN, true);
    (res.lanes as unknown[]).push({ version: lane.version, jdk: lane.release, files: c.files.length, hash: c.hash, ...b });
    console.log(`${lane.version}: javac ${b.ok ? `ok (${b.sources} sources, ${b.javacWarnings.length} warnings), scan blocks ${b.scanBlocks.length}, warns ${b.scanWarns.length}` : `FAILED\n${b.error}`}`);
    if (b.ok && lane.version === FLY) flyJar = { path: b.jarPath, sha: b.jarSha256 };
  }
  const helper = javac(path.join(RUN, "nxprotect"), [{ path: "src/main/java/dev/nxeon/tf/protect/NxProtect.java", content: PROTECT_JAVA }, { path: "src/main/resources/plugin.yml", content: PROTECT_YML }], LANES[3], "NxProtect", false);
  if (!helper.ok) console.log(`NxProtect helper: javac FAILED\n${helper.error}`);
  if (flyJar && helper.ok) {
    const r = await fly({
      version: FLY, plugins: [{ localPath: flyJar.path, sha256: flyJar.sha }, { localPath: helper.jarPath, sha256: helper.jarSha256 }], playtest: PLAN, timeouts: { totalSec: 600 },
      rcon: [
        { id: "plugins", command: "plugins", expect: [PLUGIN, "NxProtect"] },
        { id: "list", command: `${CMD} list`, expect: ["vein_pickaxe: identity=ok material=iron_pickaxe abilities=1", "timber_axe: identity=ok material=iron_axe abilities=1"], expectNot: ["MISSING", "Exception"] },
        { id: "params", command: `${CMD} params vein_pickaxe`, expect: ["items.vein_pickaxe.abilities.vein.a0.max_blocks=16", "items.vein_pickaxe.abilities.vein.a0.per_tick=4"] },
      ],
    }, `flight ${FLY}`);
    const pt = r.report.playtest as { scenarios?: { id: string; status: string; steps: { kind: string; status: string; evidence: string[] }[] }[] } | undefined;
    res.flight = { overall: r.summary.overall, line: describeSummary(r.summary), checks: Object.fromEntries(r.report.checks.map((x) => [x.id, x.status])), rcon: r.report.checks.find((x) => x.id === "rcon_checks")?.evidence ?? [], log: r.report.checks.find((x) => x.id === "startup_log_clean")?.evidence ?? [],
      scenarios: (pt?.scenarios ?? []).map((s) => ({ id: s.id, status: s.status, steps: s.steps.map((x) => ({ kind: x.kind, status: x.status, evidence: x.evidence.slice(0, 3) })) })), runId: r.report.runId, engine: r.report.engine ? { runner: r.report.engine.runner, paper: r.report.engine.paper.build } : null };
    console.log(describeSummary(r.summary));
    for (const s of (res.flight as { scenarios: { id: string; status: string; steps: { kind: string; status: string; evidence: string[] }[] }[] }).scenarios) {
      console.log(`  ${s.id} ${s.status}`);
      for (const st of s.steps) if (st.kind === "dig" || st.status !== "pass") console.log(`    ${st.kind} ${st.status}: ${st.evidence.join(" / ").slice(0, 300)}`);
    }
  }
  const o = arg("--out");
  if (o) { mkdirSync(path.dirname(o), { recursive: true }); writeFileSync(o, JSON.stringify(res, null, 1)); console.log(`wrote ${o}`); }
  rmSync(RUN, { recursive: true, force: true });
})().catch((e) => { console.error(e); rmSync(RUN, { recursive: true, force: true }); process.exit(1); });

