import java.util.ArrayList;
import java.util.Comparator;
import java.util.List;
import java.util.Set;
import org.bukkit.FluidCollisionMode;
import org.bukkit.Location;
import org.bukkit.entity.ArmorStand;
import org.bukkit.entity.Entity;
import org.bukkit.entity.LivingEntity;
import org.bukkit.entity.Player;
import org.bukkit.util.RayTraceResult;

/** Component designer-targets v1: target selection with caps (ray trace for click triggers, bounded nearby queries). */
public final class Targets {
    private Targets() {}

    /** First living entity (not the player, not an armor stand) or block along the look direction within range. */
    public static RayTraceResult look(Player p, double range) {
        Location eye = p.getEyeLocation();
        return p.getWorld().rayTrace(eye, eye.getDirection(), range, FluidCollisionMode.NEVER, true, 0.3,
            e -> e != p && e instanceof LivingEntity && !(e instanceof ArmorStand) && e.isValid());
    }

    public static Entity lookEntity(RayTraceResult r) { return r == null ? null : r.getHitEntity(); }

    public static Location lookPoint(Player p, RayTraceResult r, double range) {
        if (r != null) return r.getHitPosition().toLocation(p.getWorld());
        Location eye = p.getEyeLocation();
        return eye.add(eye.getDirection().normalize().multiply(range));
    }

    /** Living entities within radius (sphere) of center, never the player itself, players only when asked; nearest first, at most max. */
    public static List<LivingEntity> nearby(Player p, Location center, double radius, int max, int kinds, Set<String> types, boolean includePlayers) {
        List<LivingEntity> out = new ArrayList<>();
        if (center == null || center.getWorld() == null) return out;
        double r2 = radius * radius;
        boolean filtered = kinds != 0 || (types != null && !types.isEmpty());
        for (LivingEntity e : center.getWorld().getNearbyLivingEntities(center, radius)) {
            if (e == p || !e.isValid() || e.isDead() || e instanceof ArmorStand) continue;
            if (e instanceof Player && !includePlayers) continue;
            if (filtered && !Checks.targetIs(e, kinds, types)) continue;
            if (e.getLocation().distanceSquared(center) > r2) continue;
            out.add(e);
        }
        out.sort(Comparator.comparingDouble((LivingEntity e) -> e.getLocation().distanceSquared(center)).thenComparing(Entity::getUniqueId));
        return out.size() > max ? new ArrayList<>(out.subList(0, Math.max(0, max))) : out;
    }
}
