// Cyrus designer TECHNIQUE component (feature/cyrus-mc-techniques, 2026-10-12, BF technique catalogue #3): capture_mob,
// "pick up a mob into an item" (Click Villagers / Villager in a Bucket style) with Paper's EntitySnapshot. FIXED Java,
// added to a mod ONLY when a design uses capture_mob (every other mod byte-identical). Behind CYRUS_MC_TECHNIQUES /
// MB_MC_TECHNIQUES (spec.ts, OFF by default).
// Paper API, javap-checked on 1.21.1 / 1.21.4 / 1.21.8 / 1.21.11 (sheets/api-facts.verified.json: Entity.createSnapshot,
// EntitySnapshot, EntityFactory, Bukkit.getEntityFactory, Boss, Entity.teleportAsync row for getPassengers / isEmpty;
// the rest by javac in test/cyrus-designer-techniques-real.ts): Entity#createSnapshot (may be null), EntitySnapshot#
// getAsString / getEntityType / createEntity(Location), Bukkit#getEntityFactory().createEntitySnapshot(String) (throws
// IllegalArgumentException), org.bukkit.entity.Boss / Mob / Tameable, Entity#getPassengers / isInsideVehicle,
// LivingEntity#isLeashed, ItemMeta PersistentDataContainer, YamlConfiguration, java.security.MessageDigest.
//
// Dupe / forgery proof: the item carries the snapshot string and a random token; the server keeps token -> SHA-256 of
// the snapshot in plugins/<mod>/captures.yml. Release needs a live token whose hash matches the item's data and then
// forgets the token, so a copied item releases at most once and an edited one never. A release that cannot spawn keeps
// everything (nothing is lost). Caps: MAX_CHARS per snapshot, LIVE plugin-wide captures, one mob per item, stack of 1.
import { CAPTURE_LIMITS } from "../spec";

export const CAPTURES_JAVA = String.raw`package __PKG__.designer;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.ArrayList;
import java.util.HexFormat;
import java.util.List;
import java.util.Set;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import net.kyori.adventure.text.format.TextDecoration;
import org.bukkit.Bukkit;
import org.bukkit.Location;
import org.bukkit.NamespacedKey;
import org.bukkit.block.Block;
import org.bukkit.block.BlockFace;
import org.bukkit.configuration.file.YamlConfiguration;
import org.bukkit.entity.Boss;
import org.bukkit.entity.Entity;
import org.bukkit.entity.EntitySnapshot;
import org.bukkit.entity.EntityType;
import org.bukkit.entity.Mob;
import org.bukkit.entity.Player;
import org.bukkit.entity.Tameable;
import org.bukkit.inventory.ItemStack;
import org.bukkit.inventory.meta.ItemMeta;
import org.bukkit.persistence.PersistentDataContainer;
import org.bukkit.persistence.PersistentDataType;

/**
 * Component designer-captures v1: capture_mob. An empty design item captures the activation's target mob into itself
 * (EntitySnapshot as a string in its PersistentDataContainer); a full one releases it at the aim point. Never takes a
 * player or anything that is not a Mob, a boss, an elder guardian or warden, a mob with passengers or in a vehicle, a
 * leashed mob, or a pet tamed by someone else. A server-side token registry makes duplicated and edited items useless.
 */
public final class Captures {
    public static final int MAX_CHARS = ${CAPTURE_LIMITS.maxChars};
    public static final int LIVE = ${CAPTURE_LIMITS.liveCaptures};
    private static YamlConfiguration registry;
    private static File file;

    private Captures() {}

    private static YamlConfiguration registry(Designer d) {
        if (registry == null) {
            file = new File(d.plugin().getDataFolder(), "captures.yml");
            registry = YamlConfiguration.loadConfiguration(file);
        }
        return registry;
    }

    private static void save(Designer d) {
        try { registry.save(file); } catch (IOException e) { d.plugin().getLogger().warning("captures.yml: " + e.getMessage()); }
    }

    private static String hash(String data) {
        try { return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(data.getBytes(StandardCharsets.UTF_8))); }
        catch (NoSuchAlgorithmException e) { return ""; }
    }

    private static String pretty(EntityType t) { String k = t.getKey().getKey().replace('_', ' '); return k.isEmpty() ? k : Character.toUpperCase(k.charAt(0)) + k.substring(1); }

    private static void say(Player p, String text, NamedTextColor color) { p.sendActionBar(Component.text(text, color)); }

    /** Why this entity may not be captured (null = it may). */
    private static String denied(Entity e, Player p, int kinds, Set<String> types, boolean named) {
        if (!(e instanceof Mob m) || !e.isValid() || e.isDead()) return "only mobs can be caught";
        EntityType t = e.getType();
        if (e instanceof Boss || t == EntityType.ELDER_GUARDIAN || t == EntityType.WARDEN || t == EntityType.GIANT) return "this one is too powerful to catch";
        if (!e.getPassengers().isEmpty() || e.isInsideVehicle()) return "it is riding or being ridden";
        if (m.isLeashed()) return "unleash it first";
        if (e instanceof Tameable tm && tm.isTamed() && !p.getUniqueId().equals(tm.getOwnerUniqueId())) return "someone else's pet";
        if (!named && e.customName() != null) return "it has a name";
        if ((kinds != 0 || (types != null && !types.isEmpty())) && !Checks.targetIs(e, kinds, types)) return "this item cannot hold that mob";
        return null;
    }

    /** Capture (empty item + target mob) or release (full item, at the aim point). Returns true when it did either. */
    public static boolean toggle(Designer d, Activation a, int kinds, Set<String> types, boolean named) {
        Player p = a.player();
        ItemStack hand = p.getInventory().getItemInMainHand();
        if (!d.identity().is(hand, a.ability().itemId())) return false;
        if (hand.getAmount() != 1) { say(p, "Hold just one to catch or release", NamedTextColor.GRAY); return false; }
        ItemMeta meta = hand.getItemMeta();
        if (meta == null) return false;
        NamespacedKey dataKey = new NamespacedKey(d.namespace(), "capture");
        NamespacedKey tokenKey = new NamespacedKey(d.namespace(), "capture_token");
        NamespacedKey lineKey = new NamespacedKey(d.namespace(), "capture_line");
        PersistentDataContainer pdc = meta.getPersistentDataContainer();
        String data = pdc.get(dataKey, PersistentDataType.STRING);
        YamlConfiguration reg = registry(d);
        if (data == null) {
            Entity e = a.target();
            if (e == null) return false;
            String why = denied(e, p, kinds, types, named);
            if (why != null) { say(p, "Cannot catch: " + why, NamedTextColor.RED); return false; }
            if (reg.getKeys(false).size() >= LIVE) { say(p, "Too many caught mobs on this server", NamedTextColor.RED); return false; }
            if (!a.budget().entity()) return false;
            EntitySnapshot snap = e.createSnapshot();
            String s = snap == null ? null : snap.getAsString();
            if (s == null || s.isEmpty() || s.length() > MAX_CHARS) { say(p, "Cannot catch: too much data", NamedTextColor.RED); return false; }
            String token = UUID.randomUUID().toString();
            pdc.set(dataKey, PersistentDataType.STRING, s);
            pdc.set(tokenKey, PersistentDataType.STRING, token);
            List<Component> lore = meta.hasLore() && meta.lore() != null ? new ArrayList<>(meta.lore()) : new ArrayList<>();
            pdc.set(lineKey, PersistentDataType.INTEGER, lore.size());
            lore.add(Component.text("Holds: " + pretty(e.getType()), NamedTextColor.GRAY).decoration(TextDecoration.ITALIC, false));
            meta.lore(lore);
            hand.setItemMeta(meta);
