#!/usr/bin/env node
"use strict";
// Golden corpus harness (bundle mc-coverage). Runs the build service's own deterministic checks over the hand-written
// reference plugins in golden/plugins/<id>/ for every buildable Minecraft version, exactly like a generated build:
//   plugin.yml checks (as server.js validate) -> precheck (rules/failure-rules.json) -> javac --release 21 -proc:none
//   -Xlint:deprecation,removal against the version's real Paper API classpath -> warning rules -> strict bytecode +
//   source scan (scan.js) -> reproducible jar. A golden plugin must pass with ZERO compiler warnings and zero scan
//   findings on every version it declares; anything else is a finding to fix in the sheets / rules / autofix.
// Runs on the build host (node-2) via `scripts/devhost run --lock -- node services/modbuilder/golden/harness.js ...`.
//
//   node harness.js --cp-dir /tank/nxeon-build/tmp/mc-coverage/cp --jdk /tank/nxeon-build/tmp/testflight/jdk/21 \
//        --out /tank/nxeon-build/tmp/testflight/mc-coverage [--versions 1.21.1,1.21.4] [--only mc-homes,mc-kits]
// Writes <out>/compile.json and <out>/<version>/<id>.jar (+ <out>/<version>/flight-spec.json for Test Flight).
const fs = require("fs");
const os = require("os");
const path = require("path");
const crypto = require("crypto");
const { execFileSync, spawnSync } = require("child_process");

const ROOT = path.resolve(__dirname, "..");
const argv = process.argv.slice(2);
const opt = (n, d) => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] ? argv[i + 1] : d; };
const VERSIONS = opt("versions", "1.21.1,1.21.4,1.21.8,1.21.11").split(",");
const ONLY = opt("only", "") ? new Set(opt("only").split(",")) : null;
const CP_DIR = opt("cp-dir", "/tank/nxeon-build/tmp/mc-coverage/cp");
const JDK = opt("jdk", "/tank/nxeon-build/tmp/testflight/jdk/21");
const OUT = opt("out", "/tank/nxeon-build/tmp/testflight/mc-coverage");
process.env.PATH = `${JDK}/bin:${process.env.PATH}`; // scan.js runs `javap` from PATH
process.env.MB_CP_DIR = CP_DIR;

const { precheck, warningCheck, librariesProblem } = require(path.join(ROOT, "precheck.js"));
const { scanBytecode, scanSource } = require(path.join(ROOT, "scan.js"));

const vt = (v) => v.split(".").map(Number);
const ge = (a, b) => { const x = vt(a), y = vt(b); for (let i = 0; i < Math.max(x.length, y.length); i++) { const d = (x[i] || 0) - (y[i] || 0); if (d) return d > 0; } return true; };
const sha256 = (b) => crypto.createHash("sha256").update(b).digest("hex");

function walk(dir, rel = "") {
  const out = [];
  if (!fs.existsSync(path.join(dir, rel))) return out;
  for (const e of fs.readdirSync(path.join(dir, rel)).sort()) {
    const r = rel ? `${rel}/${e}` : e;
    if (fs.statSync(path.join(dir, r)).isDirectory()) out.push(...walk(dir, r));
    else out.push({ rel: r, abs: path.join(dir, r) });
  }
  return out;
}

/** The subset of server.js validate() that applies to hand-written sources (no YAML library on the build host checkout). */
function validateYml(text, javaFiles) {
  const problems = [];
  const top = (k) => { const m = text.match(new RegExp(`^${k}:\\s*['"]?([^'"\\n]*)['"]?\\s*$`, "m")); return m ? m[1].trim() : null; };
  if (!/^[A-Za-z0-9_]{1,40}$/.test(top("name") || "")) problems.push("plugin.yml name must be 1-40 letters, digits or underscores.");
  if (!top("version")) problems.push("plugin.yml needs a version.");
  if (top("api-version") !== "@API@") problems.push("golden plugin.yml must use api-version: '@API@' (the harness pins it per version, like the build service).");
  if (/^libraries:/m.test(text)) problems.push(librariesProblem({ libraries: [] }));
  const main = top("main") || "";
  if (!javaFiles.some((f) => f.rel === main.replace(/\./g, "/") + ".java")) problems.push(`plugin.yml main ${main} has no source file.`);
  const cmds = new Set();
  const sec = text.match(/^commands:\n((?:[ \t].*\n?|\n)*)/m);
