name: GoldenAfk
version: 1.0.0
main: dev.nxeon.golden.afk.Afk
api-version: '@API@'
description: Golden reference - AFK detection
author: Nxeon Mod Builder
commands:
  afk:
    description: Toggle AFK
    usage: /afk
    permission: goldenafk.use
permissions:
  goldenafk.use:
    description: Use /afk
    default: true
  goldenafk.exempt:
    description: Never kicked
    default: op
{
 "archetype": "afk",
 "rcon": [
  {
   "command": "afk",
   "expect": [
    "GoldenAfk: 0 AFK, after 5 min."
   ]
  }
 ]
}
package dev.nxeon.golden.afk;

import java.util.Map;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerMoveEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;

/** Golden AFK: marks players AFK after N minutes without changing block, optional kick; /afk toggles. */
public class Afk extends JavaPlugin implements Listener {
    private final Map<UUID, Long> lastActive = new ConcurrentHashMap<>();
    private final Map<UUID, Boolean> afk = new ConcurrentHashMap<>();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        getCommand("afk").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        getServer().getScheduler().runTaskTimer(this, this::tick, 200L, 200L);
    }

    private void tick() {
        long now = System.currentTimeMillis();
        long afterMs = getConfig().getLong("afk-after-minutes", 5) * 60000, kickMs = getConfig().getLong("kick-after-minutes", 0) * 60000;
        for (Player p : getServer().getOnlinePlayers()) {
            long idle = now - lastActive.computeIfAbsent(p.getUniqueId(), k -> now);
            if (idle >= afterMs && afk.putIfAbsent(p.getUniqueId(), true) == null) getServer().broadcast(Component.text(p.getName() + " is now AFK.", NamedTextColor.GRAY));
            if (kickMs > 0 && idle >= kickMs && !p.hasPermission("goldenafk.exempt")) p.kick(Component.text("Kicked for being AFK."));
        }
    }

    @EventHandler(ignoreCancelled = true)
    public void onMove(PlayerMoveEvent e) {
        if (!e.hasChangedBlock()) return; // head turns alone do not count as activity
        lastActive.put(e.getPlayer().getUniqueId(), System.currentTimeMillis());
        if (afk.remove(e.getPlayer().getUniqueId()) != null) getServer().broadcast(Component.text(e.getPlayer().getName() + " is back.", NamedTextColor.GRAY));
    }

    @EventHandler
    public void onQuit(PlayerQuitEvent e) { lastActive.remove(e.getPlayer().getUniqueId()); afk.remove(e.getPlayer().getUniqueId()); }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (!(sender instanceof Player p)) { sender.sendMessage(Component.text("GoldenAfk: " + afk.size() + " AFK, after " + getConfig().getLong("afk-after-minutes", 5) + " min.", NamedTextColor.GRAY)); return true; }
        if (afk.remove(p.getUniqueId()) == null) { afk.put(p.getUniqueId(), true); getServer().broadcast(Component.text(p.getName() + " is now AFK.", NamedTextColor.GRAY)); }
        else lastActive.put(p.getUniqueId(), System.currentTimeMillis());
        return true;
    }
}

