package dev.nxeon.golden.combattag;

import java.util.HashMap;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Entity;
import org.bukkit.entity.Player;
import org.bukkit.entity.Projectile;
import org.bukkit.event.EventHandler;
import org.bukkit.event.EventPriority;
import org.bukkit.event.Listener;
import org.bukkit.event.entity.EntityDamageByEntityEvent;
import org.bukkit.event.entity.PlayerDeathEvent;
import org.bukkit.event.player.PlayerCommandPreprocessEvent;
import org.bukkit.event.player.PlayerKickEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;
import org.bukkit.scheduler.BukkitTask;

/**
 * Golden combat tag: a player who deals or takes damage from another player (or a mob, with pve on) is "in combat" for N
 * seconds. Attribution uses the damage source's CAUSING entity (the archer of an arrow, the thrower of a potion, the
 * player who lit the TNT), with the projectile shooter as a fallback, so ranged hits count. While tagged, the listed
 * commands are refused; logging out kills the player once (items drop as on any death); kicks never count. State is
 * one entry per online player and is cleared on quit, death and disable: nothing grows.
 */
public class CombatTag extends JavaPlugin implements Listener {
    private final Map<UUID, Long> until = new HashMap<>();
    private final Map<UUID, String> with = new HashMap<>();
    private final Set<UUID> kicked = new HashSet<>();
    private BukkitTask timer;
    private long seconds;
    private boolean pve;
    private boolean punish;
    private Set<String> blocked = Set.of();

    @Override
    public void onEnable() {
        saveDefaultConfig();
        load();
        getCommand("combattag").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
        timer = getServer().getScheduler().runTaskTimer(this, this::tick, 20L, 20L);
    }

    @Override
    public void onDisable() {
        if (timer != null) timer.cancel();
        until.clear();
        with.clear();
        kicked.clear();
    }

    private void load() {
        reloadConfig();
        seconds = Math.max(3, Math.min(120, getConfig().getLong("seconds", 15)));
        pve = getConfig().getBoolean("pve", false);
        punish = getConfig().getBoolean("punish-logout", true);
        Set<String> b = new HashSet<>();
        for (String s : getConfig().getStringList("blocked-commands")) b.add(s.toLowerCase(Locale.ROOT).replace("/", ""));
        blocked = b;
    }

    private long now() { return getServer().getCurrentTick(); }

    private boolean tagged(Player p) { Long u = until.get(p.getUniqueId()); return u != null && u > now(); }

    private long left(Player p) { Long u = until.get(p.getUniqueId()); return u == null ? 0 : Math.max(0, (u - now() + 19) / 20); }

    private static String nameOf(Entity e) {
        if (e instanceof Player p) return p.getName();
        String k = e.getType().getKey().getKey().replace('_', ' ');
        return k.isEmpty() ? k : Character.toUpperCase(k.charAt(0)) + k.substring(1);
    }

    private void tag(Player p, String other) {
        if (p.hasPermission("goldencombattag.bypass")) return;
        boolean fresh = !tagged(p);
        until.put(p.getUniqueId(), now() + seconds * 20);
        with.put(p.getUniqueId(), other);
        if (fresh) p.sendMessage(Component.text("You are in combat with " + other + ": do not log out for " + seconds + " seconds.", NamedTextColor.RED));
    }

    /** Who is responsible for this damage: the causing entity of the damage source, else the projectile's shooter, else the damager. */
    private static Entity responsible(EntityDamageByEntityEvent e) {
        Entity cause = e.getDamageSource().getCausingEntity();
        if (cause != null) return cause;
        if (e.getDamager() instanceof Projectile pr && pr.getShooter() instanceof Entity shooter) return shooter;
        return e.getDamager();
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onDamage(EntityDamageByEntityEvent e) {
        if (!(e.getEntity() instanceof Player victim)) return;
        Entity by = responsible(e);
        if (by == null || by == victim) return;
        boolean pvp = by instanceof Player;
        if (!pvp && !pve) return;
        tag(victim, nameOf(by));
        if (by instanceof Player attacker) tag(attacker, victim.getName());
    }

    @EventHandler(priority = EventPriority.LOW, ignoreCancelled = true)
    public void onCommand(PlayerCommandPreprocessEvent e) {
        Player p = e.getPlayer();
        if (!tagged(p)) return;
        String msg = e.getMessage();
        String root = (msg.startsWith("/") ? msg.substring(1) : msg).split(" ", 2)[0].toLowerCase(Locale.ROOT);
        int colon = root.indexOf(':');
        if (colon >= 0) root = root.substring(colon + 1);
        if (!blocked.contains(root)) return;
        e.setCancelled(true);
        p.sendMessage(Component.text("You can't use /" + root + " in combat (" + left(p) + "s left).", NamedTextColor.RED));
    }

    @EventHandler(priority = EventPriority.MONITOR, ignoreCancelled = true)
    public void onKick(PlayerKickEvent e) { kicked.add(e.getPlayer().getUniqueId()); }

    @EventHandler
    public void onQuit(PlayerQuitEvent e) {
        Player p = e.getPlayer();
        UUID id = p.getUniqueId();
        boolean wasKicked = kicked.remove(id);
        if (tagged(p) && punish && !wasKicked && !p.isDead()) {
            getServer().broadcast(Component.text(p.getName() + " logged out in combat.", NamedTextColor.RED));
            until.remove(id);
            p.setHealth(0.0);
        }
        until.remove(id);
        with.remove(id);
    }

    @EventHandler
    public void onDeath(PlayerDeathEvent e) {
        until.remove(e.getPlayer().getUniqueId());
        with.remove(e.getPlayer().getUniqueId());
    }

    private void tick() {
        if (until.isEmpty()) return;
        long t = now();
        for (Player p : getServer().getOnlinePlayers()) {
            Long u = until.get(p.getUniqueId());
            if (u == null) continue;
            if (u <= t) { until.remove(p.getUniqueId()); with.remove(p.getUniqueId()); p.sendMessage(Component.text("You are no longer in combat.", NamedTextColor.GREEN)); }
            else p.sendActionBar(Component.text("In combat with " + with.getOrDefault(p.getUniqueId(), "?") + ": " + left(p) + "s", NamedTextColor.RED));
        }
    }

    @Override
    public boolean onCommand(CommandSender sender, Command command, String label, String[] args) {
        if (args.length == 1 && args[0].equalsIgnoreCase("reload")) { load(); sender.sendMessage(Component.text("GoldenCombatTag: reloaded (" + seconds + " s, pve " + pve + ").", NamedTextColor.GRAY)); return true; }
        if (args.length == 2 && args[0].equalsIgnoreCase("status")) {
            Player p = getServer().getPlayerExact(args[1]);
            if (p == null) { sender.sendMessage(Component.text("GoldenCombatTag: " + args[1] + " is not online.", NamedTextColor.GRAY)); return true; }
            sender.sendMessage(Component.text("GoldenCombatTag: " + p.getName() + (tagged(p) ? " is in combat with " + with.get(p.getUniqueId()) + " (" + left(p) + "s)." : " is not in combat."), NamedTextColor.GRAY));
            return true;
        }
        sender.sendMessage(Component.text("Usage: /combattag status <player> | reload", NamedTextColor.GRAY));
        return true;
    }
}
