package dev.nxeon.golden.playerfx;

import java.util.HashMap;
import java.util.HashSet;
import java.util.Locale;
import java.util.Map;
import java.util.Set;
import java.util.UUID;
import net.kyori.adventure.text.Component;
import net.kyori.adventure.text.format.NamedTextColor;
import org.bukkit.Bukkit;
import org.bukkit.WeatherType;
import org.bukkit.WorldBorder;
import org.bukkit.command.Command;
import org.bukkit.command.CommandSender;
import org.bukkit.entity.Entity;
import org.bukkit.entity.Player;
import org.bukkit.event.EventHandler;
import org.bukkit.event.Listener;
import org.bukkit.event.player.PlayerChangedWorldEvent;
import org.bukkit.event.player.PlayerJoinEvent;
import org.bukkit.event.player.PlayerQuitEvent;
import org.bukkit.plugin.java.JavaPlugin;
import com.destroystokyo.paper.event.player.PlayerPostRespawnEvent;

/**
 * Golden per-player effects: a world border, a fixed time of day, a weather and hidden entities that only ONE player
 * sees (nothing changes in the world). The effects live in a desired-state map and reconcile() re-applies them after a
 * join, a world change and a respawn, because the server sends the world's own border / time / entities to the client
 * then. onDisable resets every effect, so a reload or removal leaves no player stuck with them. Hidden entities are
 * found by scoreboard tag within 48 blocks (at most 32 per apply).
 */
public class PlayerFx extends JavaPlugin implements Listener {
    private static final class Fx { Double border; double cx, cz; Long time; WeatherType weather; final Set<String> hide = new HashSet<>(); }
    private final Map<UUID, Fx> want = new HashMap<>();
    private final Map<UUID, Set<UUID>> hidden = new HashMap<>();
    private boolean reconcile = true;

    @Override
    public void onEnable() {
        getCommand("pfx").setExecutor(this);
        getServer().getPluginManager().registerEvents(this, this);
    }

    @Override
    public void onDisable() {
        for (Player p : getServer().getOnlinePlayers()) reset(p);
        want.clear();
        hidden.clear();
    }

    private void reset(Player p) {
        p.setWorldBorder(null);
        p.resetPlayerTime();
        p.resetPlayerWeather();
        Set<UUID> h = hidden.remove(p.getUniqueId());
        if (h != null) for (UUID id : h) { Entity e = Bukkit.getEntity(id); if (e != null) p.showEntity(this, e); }
    }

    /** Make what this player sees match the desired state. */
    private void apply(Player p) {
        Fx f = want.get(p.getUniqueId());
        if (f == null) { reset(p); return; }
        if (f.border != null) { WorldBorder b = Bukkit.createWorldBorder(); b.setCenter(f.cx, f.cz); b.setSize(f.border); b.setWarningDistance(0); p.setWorldBorder(b); } else p.setWorldBorder(null);
        if (f.time != null) p.setPlayerTime(f.time, false); else p.resetPlayerTime();
        if (f.weather != null) p.setPlayerWeather(f.weather); else p.resetPlayerWeather();
