export const ITEM_STATES_FLAG = "CYRUS_ITEM_STATES";
export const itemStatesOn = (env: Record<string, string | undefined> = process.env) => env[ITEM_STATES_FLAG] === "1";

export const STATE_WORDS = /\b(bows?|crossbows?|longbows?|guns?|pistols?|rifles?|revolvers?|blasters?|shotguns?|snipers?|smgs?|aim(?:s|ed|ing)?|scoped?|reload(?:s|ed|ing)?|pull(?:s|ed|ing)? back|draw(?:s|n|ing)? back|pull stages?|charging look|glows? while|looks? different|item frames?|on (?:the |your |their )?head|when dropped|first[- ]person|third[- ]person|held (?:look|pose))\b/i;

export type ItemStatesRouteInput = { text: string; explicit?: unknown; existing?: boolean; mcVersion: string; on: boolean; textureAllowed: boolean };
export type ItemStatesDecision = { route: boolean; matched: string[] };

const explicitStates = (raw: unknown) => (Array.isArray(raw) ? raw.includes("itemmodel") : !!raw && typeof raw === "object" && (raw as Record<string, unknown>).itemmodel === true);

export function matchStateWords(text: string): string[] {
  const m = STATE_WORDS.exec(text ?? "");
  return m ? [`state:${m[0].toLowerCase()}`] : [];
}

export function decideItemStatesRoute(i: ItemStatesRouteInput): ItemStatesDecision {
  const none: ItemStatesDecision = { route: false, matched: [] };
  if (!i.on || !i.textureAllowed || !itemModelVersionOk(i.mcVersion).ok) return none;
  const matched = matchStateWords(i.text);
  if (!matched.length && !explicitStates(i.explicit) && !i.existing) return none;
  return { route: true, matched };
}

/** Does a stored build result carry item model state specs (ModBuild.result.assets.itemModels, written by the asset sync)? */
export function hasItemModels(result: unknown): boolean {
  const a = (result as { assets?: { itemModels?: unknown[] } } | null)?.assets;
  return Array.isArray(a?.itemModels) && a!.itemModels!.length > 0;
}

