    const { humanoid, leggings } = armorLayers(s);
    out.push({ path: `assets/${ns}/equipment/${s.id}.json`, text: JSON.stringify({ layers: { humanoid: [{ texture: `${ns}:${s.id}` }], humanoid_leggings: [{ texture: `${ns}:${s.id}` }] } }, null, 1) + "\n" });
    out.push({ path: `assets/${ns}/textures/entity/equipment/humanoid/${s.id}.png`, data: encodePngWH(humanoid) });
    out.push({ path: `assets/${ns}/textures/entity/equipment/humanoid_leggings/${s.id}.png`, data: encodePngWH(leggings) });
    for (const piece of ARMOR_PIECES) {
      const id = `${s.id}_${piece}`;
      out.push({ path: `assets/${ns}/textures/item/${id}.png`, data: encodePngWH(armorIcon(s, piece)) });
      out.push({ path: `assets/${ns}/models/item/${id}.json`, text: JSON.stringify({ parent: "minecraft:item/generated", textures: { layer0: `${ns}:item/${id}` } }, null, 1) + "\n" });
      out.push({ path: `assets/${ns}/items/${id}.json`, text: JSON.stringify({ model: { type: "minecraft:model", model: `${ns}:item/${id}` } }, null, 1) + "\n" });
    }
  }
