// Cyrus armor + custom-block LANES (feature/cyrus-mc-techniques, 2026-10-12, BF technique catalogue #6): wires the two
// generators the mc-coverage bundle built and flew but never connected to AI builds (lib/cyrus/equipment/armor.ts and
// lib/cyrus/blocks/noteblock.ts) into the build request -> build service -> resource pack path. Each lane has its OWN
// switch, OFF by default and failing closed: CYRUS_ARMOR_LANE / CYRUS_NOTEBLOCK_LANE (portal router). Off, nothing is
// decided, the build request and the pack stay byte-identical.
//
// Contract with the build model (services/modbuilder prompts ARMOR_SECTION / BLOCKS_SECTION): it writes ONE spec file,
// assets/armor.json (ArmorSpec v1) or assets/blocks.json (NoteBlockSpec v1); the service validates it like code and
// GENERATES the support class (ArmorSets / CustomBlocks, in the plugin main class's package) that the model's main class
// instantiates; the portal re-validates and emits the pack files (equipment assets + worn textures + icons; the
// note_block blockstate + block models). How either LOOKS needs a real client: never claimed here (docs: real-client
// test list). Custom blocks need the server setting block-updates.disable-noteblock-updates: true (paper-global.yml,
// restart), reported with the build, not applied by Cyrus (owner decision).
import { checkArmorSpec, armorJava, armorPackFiles, ARMOR_LIMITS, type ArmorSpec, type ArmorFile } from "./armor";
import { checkNoteBlockSpec, noteBlockJava, noteBlockPackFiles, NOTEBLOCK_INSTRUMENTS_121, NOTEBLOCK_INSTRUMENTS_262, NOTEBLOCK_LIMITS, type Allocated } from "../blocks/noteblock";
import { getVersion } from "../versions/registry";

export const ARMOR_LANE_FLAG = "CYRUS_ARMOR_LANE";
export const BLOCKS_LANE_FLAG = "CYRUS_NOTEBLOCK_LANE";
const envOf = () => (typeof process !== "undefined" && process.env ? process.env : {});
export const armorLaneOn = (env: Record<string, string | undefined> = envOf()) => env[ARMOR_LANE_FLAG] === "1";
export const blocksLaneOn = (env: Record<string, string | undefined> = envOf()) => env[BLOCKS_LANE_FLAG] === "1";

export const ARMOR_FILE = "assets/armor.json";
export const BLOCKS_FILE = "assets/blocks.json";
export const LANE_MAX_BYTES = 32 * 1024;
export const ARMOR_CLASS = "ArmorSets";
export const BLOCKS_CLASS = "CustomBlocks";
export const NOTEBLOCK_SERVER_SETTING = { file: "config/paper-global.yml", key: "block-updates.disable-noteblock-updates", value: true } as const;

/** Requests about wearable armor sets with their own look / custom placeable blocks. */
export const ARMOR_WORDS = /\b(armou?r sets?|custom armou?r|armou?r (?:pieces?|that looks?|with (?:a|its) own look)|(?:helmets?|chestplates?|leggings|boots) (?:that|which) (?:look|glow)s?|worn (?:look|armou?r))\b/i;
export const BLOCK_WORDS = /\b(custom blocks?|new blocks?|(?:decorative|placeable) blocks?|blocks? with (?:its|their|a) own (?:texture|look)|(?:ore|crystal|gem) blocks?)\b/i;

export type LaneRouteInput = { text: string; explicit?: unknown; existing?: boolean; on: boolean; textureAllowed: boolean; mcVersion: string };
export type LaneDecision = { route: boolean; matched: string[]; notes: string[] };
const explicitKind = (raw: unknown, k: string) => (Array.isArray(raw) ? raw.includes(k) : !!raw && typeof raw === "object" && (raw as Record<string, unknown>)[k] === true);

/** Armor lane: on top of an allowed texture route (the pack carries the worn looks). Off -> decides nothing. */
export function decideArmorRoute(i: LaneRouteInput): LaneDecision {
  const none: LaneDecision = { route: false, matched: [], notes: [] };
  if (!i.on || !i.textureAllowed || !getVersion(i.mcVersion)) return none;
  const m = ARMOR_WORDS.exec(i.text ?? "");
  if (!m && !explicitKind(i.explicit, "armor") && !i.existing) return none;
  const modern = itemModelsOf(i.mcVersion);
  return { route: true, matched: m ? [`armor:${m[0].toLowerCase()}`] : [], notes: modern ? [] : [`On Minecraft ${i.mcVersion} armor cannot have its own worn look (that needs 1.21.4+): the sets are dyed leather in their base colour.`] };
}

/** Custom-block lane: needs the texture route (the faces are this mod's textures). Off -> decides nothing. */
export function decideBlocksRoute(i: LaneRouteInput): LaneDecision {
  const none: LaneDecision = { route: false, matched: [], notes: [] };
  if (!i.on || !i.textureAllowed || !getVersion(i.mcVersion)) return none;
  const m = BLOCK_WORDS.exec(i.text ?? "");
  if (!m && !explicitKind(i.explicit, "blocks") && !i.existing) return none;
  return { route: true, matched: m ? [`blocks:${m[0].toLowerCase()}`] : [], notes: [`Custom blocks need the server setting ${NOTEBLOCK_SERVER_SETTING.key}: true in ${NOTEBLOCK_SERVER_SETTING.file} (then a restart), or vanilla block updates can turn them back into note blocks.`] };
}

/** 1.21.4+ (item model definitions + equippable): the registry capability. */
export const itemModelsOf = (v: string) => !!getVersion(v)?.capabilities.includes("itemModelDefinitions");
export const instrumentsOf = (v: string): readonly string[] => (/^26\./.test(v) ? NOTEBLOCK_INSTRUMENTS_262 : NOTEBLOCK_INSTRUMENTS_121);

export type LaneJava = { path: string; content: string };
