cat > scripts/cyrus/build-equipment-artifacts.ts <<'EOF'
// Generated file of the Cyrus armor + custom-block lanes (committed, so the build service needs no esbuild or zod at
// runtime; test/cyrus-equipment-lane.test.ts rebuilds it in memory and fails when it is stale):
//   services/modbuilder/equipment-spec.js   the build service's validators + Java generators, from lib/cyrus/equipment/lane.ts
//   npx tsx scripts/cyrus/build-equipment-artifacts.ts [--check] [--out-dir DIR]
import { readFileSync, writeFileSync } from "node:fs";
import path from "node:path";

const ROOT = path.join(__dirname, "../..");

export async function equipmentArtifacts(): Promise<Record<string, string>> {
  const esbuild = await import("esbuild");
  const r = await esbuild.build({
    entryPoints: [path.join(ROOT, "lib/cyrus/equipment/service-entry.ts")], bundle: true, platform: "node", format: "cjs", target: "node20", write: false,
    minify: true, keepNames: true, legalComments: "none", banner: { js: `"use strict";\n// GENERATED by scripts/cyrus/build-equipment-artifacts.ts from lib/cyrus/equipment + lib/cyrus/blocks (+ zod and the version registry). Do not edit.` },
  });
  return { "services/modbuilder/equipment-spec.js": r.outputFiles[0].text };
}

if (require.main === module) {
  equipmentArtifacts().then((files) => {
    let stale = 0;
    const oi = process.argv.indexOf("--out-dir");
    for (const [rel, text] of Object.entries(files)) {
      const abs = oi > 0 ? path.join(process.argv[oi + 1], rel) : path.join(ROOT, rel);
      if (process.argv.includes("--check")) {
        let cur = ""; try { cur = readFileSync(abs, "utf8"); } catch { /* missing */ }
        if (cur !== text) { stale++; console.error(`stale: ${rel}`); }
      } else { writeFileSync(abs, text); console.log(`wrote ${rel} (${Buffer.byteLength(text)} bytes)`); }
    }
    if (stale) { console.error("run: npx tsx scripts/cyrus/build-equipment-artifacts.ts"); process.exit(1); }
  }).catch((e) => { console.error(e); process.exit(1); });
}
EOF
cat > services/modbuilder/equipment.js <<'EOF'
"use strict";
// Cyrus armor + custom-block lanes in the build service (feature/cyrus-mc-techniques, BF technique catalogue #6). When the
// portal routes a build to them (assets.armor / assets.blocks; portal switches CYRUS_ARMOR_LANE / CYRUS_NOTEBLOCK_LANE,
// both OFF by default), the model writes ONE spec: assets/armor.json (ArmorSpec v1) / assets/blocks.json (NoteBlockSpec
// v1). This module checks it like code with the validator GENERATED from lib/cyrus/equipment/lane.ts (./equipment-spec.js)
// and writes the support class (ArmorSets.java / CustomBlocks.java) next to the plugin's main class, replacing any copy the
// model wrote. The portal re-validates and emits the pack files (the service never builds the pack). Plain Node.
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");
const EQ = require("./equipment-spec");

/** The package of plugin.yml's main class (the support classes go next to it). */
function mainPackage(ws) {
  let yml = "";
  try { yml = fs.readFileSync(path.join(ws, "src/main/resources/plugin.yml"), "utf8"); } catch { return null; }
  const m = yml.match(/^main:\s*['"]?([A-Za-z_][\w.]*)['"]?\s*$/m);
  if (!m || !m[1].includes(".")) return null;
  return m[1].slice(0, m[1].lastIndexOf("."));
}
function readSpec(ws, rel) {
  const abs = path.join(ws, rel);
  if (!fs.existsSync(abs)) return { present: false };
  const st = fs.statSync(abs);
  if (st.size > EQ.LANE_MAX_BYTES) return { present: true, problems: [`${rel} is larger than ${EQ.LANE_MAX_BYTES / 1024} KB`] };
  const bytes = fs.readFileSync(abs);
  try { return { present: true, json: JSON.parse(bytes.toString("utf8")), sha256: crypto.createHash("sha256").update(bytes).digest("hex") }; }
  catch (e) { return { present: true, problems: [`${rel} is not valid JSON: ${String(e.message).slice(0, 160)}`] }; }
}
const textureNamesOf = (ws) => { try { return fs.readdirSync(path.join(ws, "assets/textures")).filter((n) => /^[a-z][a-z0-9_]{1,31}\.json$/.test(n)).map((n) => n.slice(0, -5)).sort(); } catch { return []; } };

/**
 * Check (and, when valid and `write`, generate the support classes for) the lane specs of a workspace.
 * Returns { problems (HARD, go back to the model), armor?: {spec, sha256, java, notes}, blocks?: {...}, missing: [...] }.
 */
function laneRound(ws, { armor, blocks, namespace, mcVersion, write, textures }) {
  const out = { problems: [], missing: [], notes: [] };
  if (!armor && !blocks) return out;
  const pkg = mainPackage(ws);
  const lanes = [...(armor ? [["armor", EQ.ARMOR_FILE]] : []), ...(blocks ? [["blocks", EQ.BLOCKS_FILE]] : [])];
  for (const [kind, rel] of lanes) {
    const s = readSpec(ws, rel);
    if (!s.present) { out.missing.push(kind); continue; }
    if (s.problems) { out.problems.push(...s.problems); continue; }
    if (!pkg) { out.problems.push(`${rel}: plugin.yml has no main class yet, so ${kind === "armor" ? EQ.ARMOR_CLASS : EQ.BLOCKS_CLASS} has no package to go in`); continue; }
    const r = kind === "armor" ? EQ.armorLane(s.json, { namespace, mcVersion, pkg }) : EQ.blocksLane(s.json, { namespace, mcVersion, pkg, textures: textures || textureNamesOf(ws) });
    if (!r.ok) { out.problems.push(...r.errors.slice(0, 8)); continue; }
    if (write) { const abs = path.join(ws, r.java.path); fs.mkdirSync(path.dirname(abs), { recursive: true }); fs.writeFileSync(abs, r.java.content); }
    out.notes.push(...r.notes);
    out[kind] = { path: rel, sha256: s.sha256, spec: kind === "armor" ? r.spec : s.json, java: r.java.path, ...(kind === "blocks" ? { home: r.home, states: r.blocks.map((b) => ({ id: b.id, ...b.state })) } : {}) };
  }
  return out;
}

module.exports = { EQ, mainPackage, laneRound, textureNamesOf };
EOF
