export function buildPack(opts: { namespace: string; description: string; mcVersion: string; textures: unknown[]; sounds?: PackSoundEvent[]; allowPreview?: boolean; itemModels?: unknown[]; fonts?: PackFontFile[]; /** PROPOSED handgun grip fix (./display.ts gripOnFist); off = byte-identical packs */ handgunGripFix?: boolean; /** 1.21.1 only: the legacy manifest ({items:[{texture,base,cmd}]}, lib/cyrus/itemmodel/legacy.ts); ignored on 1.21.4+ */ legacyModels?: unknown; /** clock for the game-derived retention check (tests) */ now?: number }): { ok: true; pack: BuiltPack } | { ok: false; error: string } {
  if (!/^[a-z][a-z0-9_]{1,30}$/.test(opts.namespace)) return { ok: false, error: "namespace must be lowercase letters, digits and underscores" };
  const sounds = opts.sounds ?? [];
  const fonts = opts.fonts ?? [];
  if (opts.textures.length > 24) return { ok: false, error: "a pack holds at most 24 textures" };
  if (opts.textures.length === 0 && sounds.length === 0 && fonts.length === 0) return { ok: false, error: "a pack needs at least one texture, sound or HUD font" };
  if (fonts.length > 64) return { ok: false, error: "a pack holds at most 64 HUD font files" };
  for (const f of fonts) {
    const ok = new RegExp(`^assets/${opts.namespace}/(font/[a-z0-9_]{1,32}\\.json|textures/font/[a-z0-9_]{1,32}/[a-z0-9_]{1,65}\\.png)$`).test(f.path);
    if (!ok) return { ok: false, error: `HUD font file ${f.path} is outside this mod's font folders` };
    if (f.data.length > 64 * 1024) return { ok: false, error: `HUD font file ${f.path} is larger than 64 KB` };
    if (f.path.endsWith(".png") && f.data.subarray(1, 4).toString("latin1") !== "PNG") return { ok: false, error: `HUD font file ${f.path} is not a PNG` };
  }
  if (sounds.length > 24) return { ok: false, error: "a pack holds at most 24 sound events" };
  const seen = new Set<string>();
  for (const e of sounds) {
    if (!SET_RE.test(e.set) || !EVENT_RE.test(e.event)) return { ok: false, error: `bad sound key ${e.set}.${e.event}` };
    if (seen.has(`${e.set}.${e.event}`)) return { ok: false, error: `duplicate sound event ${e.set}.${e.event}` };
    seen.add(`${e.set}.${e.event}`);
    if (!e.files.length || e.files.length > 4) return { ok: false, error: `sound ${e.set}.${e.event} needs 1-4 files` };
    if (typeof e.subtitle !== "string" || e.subtitle.trim().length < 3) return { ok: false, error: `sound ${e.set}.${e.event} has no subtitle` };
    for (const f of e.files) if (f.data.subarray(0, 4).toString("latin1") !== "OggS") return { ok: false, error: `sound ${e.set}.${e.event} file ${f.index} is not Ogg` };
  }
  // Each texture is a DSL spec (what builds return) or a Texture Studio doc (spec + sparse paint layer,
  // lib/cyrus/studios/paint.ts): the pack ships the COMPOSITE pixels.
  const specs: { name: string; raster: () => Raster }[] = [];
  // R42 delta-only: a texture painted on a game file ships only when it is still live and CHANGED (lib/cyrus/gameassets/delta.ts)
  const leftOut: { name: string; reason: string }[] = [];
  for (const [i, t] of opts.textures.entries()) {
    const isDoc = !!t && typeof t === "object" && (t as { v?: unknown }).v === 1 && "paint" in (t as object);
    let entry: { name: string; raster: () => Raster };
    if (isDoc) {
      const d = checkDoc(t); if (!d.ok) return { ok: false, error: `texture ${i + 1}: ${d.error}` };
      if (d.doc.base) { const r = renderDoc(d.doc), dd = deltaTexture(d.doc.base, r, opts.now); if (!dd.ship) { leftOut.push({ name: d.doc.name, reason: dd.reason }); continue; } entry = { name: d.doc.name, raster: () => r }; }
      else entry = { name: d.doc.name, raster: () => renderDoc(d.doc) };
    }
    else { const c = checkSpec(t); if (!c.ok) return { ok: false, error: `texture ${i + 1}: ${c.error}` }; const spec: TextureSpec = c.spec; entry = { name: spec.name, raster: () => render(spec) }; }
    if (specs.some((s) => s.name === entry.name)) return { ok: false, error: `duplicate texture name ${entry.name}` };
    specs.push(entry);
  }
  const ver = getVersion(opts.mcVersion);
  if (ver && ver.status === "preview" && !opts.allowPreview) return { ok: false, error: `${opts.mcVersion} is a preview version: its resource packs are not verified in a real client yet` };
  const legacy = opts.textures.length > 0 && isLegacyVersion(ver);
  const pf = resourcePackFormat(opts.mcVersion, { needsItemModels: opts.textures.length > 0 && !legacy });
  if (!pf.ok) return { ok: false, error: pf.error };
  const ims = opts.itemModels ?? [];
  const covered = new Set<string>();
  if (ims.length) {
    const v = validateItemModels(ims, { textures: specs.map((x) => x.name), version: legacy ? undefined : opts.mcVersion });
    if (!v.ok) {
      const bad = v.errors[0] ?? v.results.flatMap((r, i) => (r.ok ? [] : r.errors.map((e) => ({ ...e, path: `item model ${i + 1}: ${e.path}` }))))[0];
      return { ok: false, error: `item model states: ${bad ? `${bad.path}: ${bad.message}` : "invalid"}` };
    }
    for (const r of v.results) if (r.ok) for (const t of r.needs.textures) covered.add(t);
    if (legacy) for (const r of v.results) if (r.ok) { const bad = legacyStateIssues(r.spec, opts.mcVersion); if (bad.length) return { ok: false, error: `item model states: ${bad[0].path}: ${bad[0].message}` }; }
  }
  const fmt = pf.format.major;
  // legacy (1.21.1): every texture that is not only a state texture needs a carrier + number
  let bindings: LegacyBinding[] = [];
  if (legacy) {
    const stateOnly = new Set<string>();
    for (const raw of ims) for (const st of ((raw as { states?: { texture: string }[] }).states ?? [])) stateOnly.add(st.texture);
    for (const raw of ims) stateOnly.delete((raw as { name: string }).name);
    const lc = checkLegacyManifest(opts.legacyModels ?? { items: [] }, { namespace: opts.namespace, textures: specs.map((x) => x.name), required: specs.map((x) => x.name).filter((n) => !stateOnly.has(n)) });
    if (!lc.ok) return { ok: false, error: `Minecraft ${opts.mcVersion} legacy item looks: ${lc.errors[0]}` };
    bindings = lc.bindings;
  }
  // item model definitions need format 46+ (1.21.4); a sound-only pack also works on older versions (sounds.json is stable since 1.13).
  // The legacy pack (1.21.1) reads `overrides`, which 1.21.4 dropped: it declares 34..45 and has no 1.21.9+ min/max_format keys.
  const minF = opts.textures.length ? 46 : Math.min(46, fmt);
  const mcmeta = legacy
    ? { pack: { pack_format: fmt, supported_formats: { min_inclusive: LEGACY_PACK_RANGE.min, max_inclusive: LEGACY_PACK_RANGE.max }, description: opts.description.slice(0, 100) } }
    : { pack: { pack_format: fmt, supported_formats: { min_inclusive: minF, max_inclusive: 999 }, min_format: minF, max_format: 999, description: opts.description.slice(0, 100) } };
  const files: { path: string; data: Buffer }[] = [
    { path: "pack.mcmeta", data: Buffer.from(JSON.stringify(mcmeta, null, 2)) },
  ];
  const ns = opts.namespace;
  const rasters = new Map<string, Raster>();
  for (const s of specs) {
    const raster = s.raster();
    rasters.set(s.name, raster);
    files.push({ path: `assets/${ns}/textures/item/${s.name}.png`, data: encodePng(raster) });
    if (covered.has(s.name)) continue; // its look comes from an item model spec (below)
    // explicit display block (lib/cyrus/textures/display.ts): the hand transforms the studio's "In hand" preview shows
    files.push({ path: `assets/${ns}/models/item/${s.name}.json`, data: Buffer.from(JSON.stringify({ parent: "minecraft:item/handheld", textures: { layer0: `${ns}:item/${s.name}` }, display: displayFor(s.name, raster, { gripFix: opts.handgunGripFix === true }) }, null, 2)) });
    if (!legacy) files.push({ path: `assets/${ns}/items/${s.name}.json`, data: Buffer.from(JSON.stringify({ model: { type: "minecraft:model", model: `${ns}:item/${s.name}` } }, null, 2)) });
  }
  const itemModels: NonNullable<BuiltPack["itemModels"]> = [];
  for (const raw of ims) {
    const name = (raw as { name: string }).name;
    const e = emitItemModel(raw, { namespace: ns, version: opts.mcVersion, textures: specs.map((x) => x.name), idle: rasters.get(name), gripFix: opts.handgunGripFix === true, legacy });
    if (!e.ok) return { ok: false, error: `item model ${name}: ${e.errors[0]?.message ?? "invalid"}` };
    for (const f of e.item.files) files.push({ path: f.path, data: Buffer.from(f.text) });
    itemModels.push({ name: e.item.name, model: e.item.model, states: e.item.states, needs: e.item.needs });
  }
  const packSounds: BuiltPack["sounds"] = [];
  if (sounds.length) {
    const json: Record<string, unknown> = {};
    const lang: Record<string, string> = {};
    for (const e of [...sounds].sort((a, b) => (`${a.set}.${a.event}` < `${b.set}.${b.event}` ? -1 : 1))) {
      const key = `${e.set}.${e.event}`, sub = `subtitles.${ns}.${key}`;
      const list = [...e.files].sort((a, b) => a.index - b.index);
      for (const f of list) files.push({ path: `assets/${ns}/sounds/${e.set}/${e.event}_${f.index}.ogg`, data: f.data });
      json[key] = { subtitle: sub, sounds: list.map((f) => ({ name: `${ns}:${e.set}/${e.event}_${f.index}`, weight: f.weight })) };
      lang[sub] = e.subtitle.trim().slice(0, 60);
      packSounds.push({ key: `${ns}:${key}`, subtitleKey: sub, files: list.length });
    }
    files.push({ path: `assets/${ns}/sounds.json`, data: Buffer.from(JSON.stringify(json, null, 2)) });
    files.push({ path: `assets/${ns}/lang/en_us.json`, data: Buffer.from(JSON.stringify(lang, null, 2)) });
  }
  if (legacy) {
    const entries: LegacyEntry[] = bindings.map((b) => {
      const raw = ims.find((x) => (x as { name: string }).name === b.texture) as { states?: { id: string; when: { type: string; from?: number } }[] } | undefined;
      const damage = (raw?.states ?? []).filter((st) => st.when.type === "damage").map((st) => ({ from: st.when.from!, model: `${ns}:item/${b.texture}/${st.id}` }));
      return { binding: b, model: `${ns}:item/${b.texture}`, ...(damage.length ? { damage } : {}) };
    });
    for (const f of carrierModelFiles(entries)) files.push({ path: f.path, data: Buffer.from(f.text) });
  }
  for (const f of fonts) files.push({ path: f.path, data: f.data });
  const z = zip(files);
  return { ok: true, pack: { packFormat: fmt, packClientVerified: pf.clientVerified, zip: z, sha1: createHash("sha1").update(z).digest("hex"), bytes: z.length, files: files.map((f) => f.path).sort(), textures: specs.map((s) => ({ name: s.name, model: `${ns}:${s.name}` })), sounds: packSounds, ...(ims.length ? { itemModels } : {}), ...(fonts.length ? { fonts: fonts.map((f) => f.path).sort() } : {}), ...(legacy ? { legacy: { emitter: LEGACY_EMITTER_VERSION, bindings, carriers: [...new Set(bindings.map((b) => b.base))].sort() } } : {}), ...(leftOut.length ? { leftOut } : {}) } };
}

