// Cyrus armor + custom-block LANES (feature/cyrus-mc-techniques, 2026-10-12, BF technique catalogue #6): the two generators
// the mc-coverage bundle built and flew (lib/cyrus/equipment/armor.ts, lib/cyrus/blocks/noteblock.ts) wired into the
// build request -> build service -> pack path behind CYRUS_ARMOR_LANE / CYRUS_NOTEBLOCK_LANE (both OFF). Pure: the router,
// the request (off = byte-identical), the service module on a temp workspace, the generated bundle (current, == TS), the
// service request parser, the prompt sections, the pack emission (byte-identical without lanes), and the Dockerfile.
// The service pipeline itself (fake CLI): test/modbuilder-pipeline.test.ts "armor + custom-block lanes".
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { ARMOR_LANE_FLAG, BLOCKS_LANE_FLAG, armorLane, armorLaneOn, blocksLane, blocksLaneOn, decideArmorRoute, decideBlocksRoute, hasLaneSpec, NOTEBLOCK_SERVER_SETTING } from "../lib/cyrus/equipment/lane";
import { resolveBuildAssets } from "../lib/cyrus/assets/request";
import { buildPack } from "../lib/cyrus/textures/pack";

const ROOT = path.join(__dirname, "..");
const SVC = path.join(ROOT, "services/modbuilder");
const NS = "nx_ab12cd34";
const ARMOR = { version: 1, sets: [{ id: "ember", displayName: "Ember", palette: { base: "#c2461e", light: "#f2a03c", dark: "#4a1608" }, style: "plate", armor: { helmet: 3, chestplate: 7, leggings: 6, boots: 3 }, setBonus: { effect: "fire_resistance", amplifier: 0 } }] };
const RUBY = JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-textures/ruby_sword.json"), "utf8"));
const BLOCKS = { version: 1, blocks: [{ id: "ruby_block", displayName: "Ruby Block", texture: RUBY.name }] };

describe("lanes: switches + router", () => {
  it("both switches are OFF by default and fail closed", () => {
    assert.equal(armorLaneOn({}), false); assert.equal(blocksLaneOn({}), false);
    assert.equal(armorLaneOn({ [ARMOR_LANE_FLAG]: "1" }), true); assert.equal(blocksLaneOn({ [BLOCKS_LANE_FLAG]: "1" }), true);
    assert.equal(armorLaneOn({ [ARMOR_LANE_FLAG]: "yes" }), false);
  });
  it("routes armor / block requests only when on and textures are allowed; explicit and existing route too", () => {
    const A = (text: string, o: Partial<Parameters<typeof decideArmorRoute>[0]> = {}) => decideArmorRoute({ text, on: true, textureAllowed: true, mcVersion: "1.21.11", ...o });
    assert.deepEqual(A("an Ember armor set that looks orange"), { route: true, matched: ["armor:armor set"], notes: [] });
    assert.equal(A("an Ember armor set", { on: false }).route, false);
    assert.equal(A("an Ember armor set", { textureAllowed: false }).route, false);
    assert.equal(A("a frost sword").route, false);
    assert.equal(A("make it red", { existing: true }).route, true);
    assert.equal(A("x", { explicit: { armor: true } }).route, true);
    assert.match(A("custom armor", { mcVersion: "1.21.1" }).notes[0], /dyed leather/);
    const B = (text: string, o: Partial<Parameters<typeof decideBlocksRoute>[0]> = {}) => decideBlocksRoute({ text, on: true, textureAllowed: true, mcVersion: "1.21.11", ...o });
    assert.equal(B("a custom block made of ruby").route, true);
    assert.match(B("custom blocks").notes[0], new RegExp(NOTEBLOCK_SERVER_SETTING.key.replace(/\./g, "\\.")));
    assert.equal(B("custom blocks", { on: false }).route, false);
    assert.equal(hasLaneSpec({ assets: { armor: { spec: {} } } }, "armor"), true); assert.equal(hasLaneSpec({ assets: {} }, "blocks"), false);
  });
  it("build request: rides on the texture gate; switches off = byte-identical service object", async () => {
    const deps = { tierOf: async () => "all", projectForRootBuild: async () => ({ id: "cp00000000000000000001", namespace: NS }), createProject: async () => ({ id: "cpx", namespace: NS }) };
    const text = "an Ember armor set with a custom texture and a custom block made of ruby";
    const off = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text, mcVersion: "1.21.11" }, { ...deps, armorLaneOn: () => false, blocksLaneOn: () => false });
    assert.deepEqual(off.service, { texture: true, sound: false, namespace: NS });
    assert.equal(off.meta!.armor, undefined);
    const on = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text, mcVersion: "1.21.11" }, { ...deps, armorLaneOn: () => true, blocksLaneOn: () => true });
    assert.deepEqual(on.service, { texture: true, sound: false, namespace: NS, armor: true, blocks: true });
    assert.ok(on.meta!.notices.some((n) => /disable-noteblock-updates/.test(n)));
    const free = await resolveBuildAssets({ userId: "u", rootBuildId: "b", change: false, text, mcVersion: "1.21.11" }, { ...deps, tierOf: async () => "saka", armorLaneOn: () => true, blocksLaneOn: () => true });
    assert.equal(free.service?.armor, undefined, "no texture plan, no lanes");
  });
});

describe("lanes: the service module (temp workspace) + generated bundle", () => {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const EQS = require(path.join(SVC, "equipment.js"));
  const ws = (files: Record<string, string>) => { const d = fs.mkdtempSync(path.join(os.tmpdir(), "cyrus-lanes-")); for (const [rel, t] of Object.entries(files)) { fs.mkdirSync(path.dirname(path.join(d, rel)), { recursive: true }); fs.writeFileSync(path.join(d, rel), t); } return d; };
  const YML = "name: Ember\nversion: 1.0.0\nmain: dev.nxeon.plugins.ember.Ember\napi-version: '1.21.11'\n";
  it("valid specs generate ArmorSets / CustomBlocks next to the main class (replacing the model's copy)", () => {
    const d = ws({ "src/main/resources/plugin.yml": YML, "assets/armor.json": JSON.stringify(ARMOR), "assets/blocks.json": JSON.stringify(BLOCKS), [`assets/textures/${RUBY.name}.json`]: JSON.stringify(RUBY), "src/main/java/dev/nxeon/plugins/ember/ArmorSets.java": "class ArmorSets {}" });
    const r = EQS.laneRound(d, { armor: true, blocks: true, namespace: NS, mcVersion: "1.21.11", write: true });
    assert.deepEqual(r.problems, []);
    const java = fs.readFileSync(path.join(d, "src/main/java/dev/nxeon/plugins/ember/ArmorSets.java"), "utf8");
    assert.match(java, /^package dev\.nxeon\.plugins\.ember;/);
    assert.match(java, /public final class ArmorSets implements Listener/);
    assert.equal(java, armorLane(ARMOR, { namespace: NS, mcVersion: "1.21.11", pkg: "dev.nxeon.plugins.ember" }).ok && (armorLane(ARMOR, { namespace: NS, mcVersion: "1.21.11", pkg: "dev.nxeon.plugins.ember" }) as { java: { content: string } }).java.content);
    assert.ok(fs.existsSync(path.join(d, "src/main/java/dev/nxeon/plugins/ember/CustomBlocks.java")));
    assert.equal(r.blocks.states[0].id, "ruby_block");
    assert.ok(r.notes.some((n: string) => /disable-noteblock-updates/.test(n)));
  });
  it("problems: bad spec, unknown texture, no main class, too large; missing = nothing", () => {
    assert.ok(EQS.laneRound(ws({ "src/main/resources/plugin.yml": YML, "assets/armor.json": JSON.stringify({ ...ARMOR, version: 9 }) }), { armor: true, namespace: NS, mcVersion: "1.21.11" }).problems[0].startsWith("assets/armor.json: version"));
    assert.match(EQS.laneRound(ws({ "src/main/resources/plugin.yml": YML, "assets/blocks.json": JSON.stringify(BLOCKS) }), { blocks: true, namespace: NS, mcVersion: "1.21.11" }).problems[0], /ruby_sword/);
    assert.match(EQS.laneRound(ws({ "assets/armor.json": JSON.stringify(ARMOR) }), { armor: true, namespace: NS, mcVersion: "1.21.11" }).problems[0], /no main class/);
    assert.match(EQS.laneRound(ws({ "src/main/resources/plugin.yml": YML, "assets/armor.json": "x".repeat(40000) }), { armor: true, namespace: NS, mcVersion: "1.21.11" }).problems[0], /larger than/);
    assert.deepEqual(EQS.laneRound(ws({ "src/main/resources/plugin.yml": YML }), { armor: true, namespace: NS, mcVersion: "1.21.11" }).missing, ["armor"]);
    const legacy = blocksLane(BLOCKS, { namespace: NS, mcVersion: "1.21.1", pkg: "a.b", textures: [RUBY.name] });
    assert.ok(legacy.ok);
    assert.match(armorLane(ARMOR, { namespace: NS, mcVersion: "1.21.1", pkg: "a.b" }).ok ? (armorLane(ARMOR, { namespace: NS, mcVersion: "1.21.1", pkg: "a.b" }) as { notes: string[] }).notes[0] : "", /dyed leather/);
    assert.ok(!armorLane(ARMOR, { namespace: NS, mcVersion: "1.21.11", pkg: "Bad.Pkg" }).ok);
  });
  it("services/modbuilder/equipment-spec.js is current and agrees with the TypeScript", async () => {
    const { equipmentArtifacts } = await import("../scripts/cyrus/build-equipment-artifacts");
    for (const [rel, text] of Object.entries(await equipmentArtifacts())) assert.equal(fs.readFileSync(path.join(ROOT, rel), "utf8"), text, `${rel} is stale: run scripts/cyrus/build-equipment-artifacts.ts`);
    // eslint-disable-next-line @typescript-eslint/no-require-imports
    const EQ = require(path.join(SVC, "equipment-spec.js"));
    for (const v of ["1.21.1", "1.21.11"]) {
      assert.deepEqual(EQ.armorLane(ARMOR, { namespace: NS, mcVersion: v, pkg: "p.q" }), armorLane(ARMOR, { namespace: NS, mcVersion: v, pkg: "p.q" }));
      assert.deepEqual(EQ.blocksLane(BLOCKS, { namespace: NS, mcVersion: v, pkg: "p.q", textures: [RUBY.name] }), blocksLane(BLOCKS, { namespace: NS, mcVersion: v, pkg: "p.q", textures: [RUBY.name] }));
    }
  });
});

describe("lanes: service request flags, prompt sections, Dockerfile", () => {
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const TX = require(path.join(SVC, "textures.js"));
  // eslint-disable-next-line @typescript-eslint/no-require-imports
  const P = require(path.join(SVC, "prompts.js"));
  const parse = (raw: unknown) => TX.parseAssetsRequest(raw, "1.21.11", new Set(["1.21.11"]), () => true, () => true, new Set(), () => false, () => true, new Set());
  it("armor / blocks ride on textures; malformed values are refused; absent = byte-identical", () => {
    assert.equal(parse({ texture: true, namespace: NS, armor: true, blocks: true }).armor, true);
    const off = parse({ texture: false, namespace: NS, armor: true });
    assert.equal(off.armor, false); assert.ok(off.notes.some((n: string) => /armor sets are off/.test(n)));
    assert.match(parse({ texture: true, namespace: NS, armor: "yes" }).error, /assets\.armor must be true or false/);
    assert.equal("armor" in parse({ texture: true, namespace: NS }), false);
  });
  it("the sections are in the system prompt only when routed", () => {
    assert.match(P.ARMOR_SECTION, /assets\/armor\.json/); assert.match(P.BLOCKS_SECTION, /disable-noteblock-updates: true/);
    assert.ok(!P.systemPrompt("1.21.11", { textures: true }).includes("CUSTOM ARMOR (this build"));
    assert.ok(P.systemPrompt("1.21.11", { textures: true, armor: true }).includes(P.ARMOR_SECTION));
    assert.ok(P.systemPrompt("1.21.11", { textures: true, blocks: true }).includes(P.BLOCKS_SECTION));
  });
  it("the image carries the lane module and its bundle", () => {
    const df = fs.readFileSync(path.join(SVC, "Dockerfile"), "utf8");
    assert.match(df, /equipment\.js equipment-spec\.js \/opt\/mb\/app\//);
  });
});

describe("lanes: the resource pack", () => {
  const files = (r: ReturnType<typeof buildPack>) => (r.ok ? r.pack.files : []);
  it("armor on 1.21.4+: equipment asset, worn layers, icons, item definitions; absent = byte-identical pack", () => {
    const base = buildPack({ namespace: NS, description: "d", mcVersion: "1.21.11", textures: [RUBY] });
    const withA = buildPack({ namespace: NS, description: "d", mcVersion: "1.21.11", textures: [RUBY], armor: ARMOR });
    assert.ok(base.ok && withA.ok);
    assert.ok(base.ok && withA.ok && base.pack.sha1 !== withA.pack.sha1);
    const again = buildPack({ namespace: NS, description: "d", mcVersion: "1.21.11", textures: [RUBY] });
    assert.ok(again.ok && base.ok && again.pack.sha1 === base.pack.sha1, "no lane = same bytes");
    for (const p of [`assets/${NS}/equipment/ember.json`, `assets/${NS}/textures/entity/equipment/humanoid/ember.png`, `assets/${NS}/textures/entity/equipment/humanoid_leggings/ember.png`, `assets/${NS}/items/ember_helmet.json`, `assets/${NS}/textures/item/ember_boots.png`]) assert.ok(files(withA).includes(p), p);
    assert.equal(withA.ok && withA.pack.lanes?.armor, 2 + 1 + 4 * 3);
    const armorOnly = buildPack({ namespace: NS, description: "d", mcVersion: "1.21.11", textures: [], armor: ARMOR });
    assert.ok(armorOnly.ok && armorOnly.pack.files.includes(`assets/${NS}/equipment/ember.json`), "an armor-only pack builds");
  });
