// Cyrus real-client test-day kit. Builds, from COMMITTED fixtures only (no model, no paid call), per version:
// a resource pack (ruby sword texture, the pistol's item model states, the banshee sounds rendered with node-2's ffmpeg,
// the HUD showcase glyph fonts) and, with --compile on node-2, the four designer showcase plugins compiled by the
// pinned Test Flight JDK against the Paper API. Writes manifest.json, CHECKLIST.md and a results.json form.
//
//   scripts/devhost run -- npx tsx scripts/cyrus/testday-kit.ts build --out /tank/nxeon-build/tmp/testday/kit --compile
//   npx tsx scripts/cyrus/testday-kit.ts ingest --kit DIR --results results.json [--apply]
// `ingest` prints the per-version verdict; --apply writes lib/cyrus/versions/registry.json (resourcePackClientVerified)
// and lib/cyrus/versions/client-verify.json (the evidence) in THIS checkout, for review + commit like any change.
// Normally run through scripts/cyrus/testday.sh (build / start / stop / ingest).
import { spawnSync } from "node:child_process";
import fs from "node:fs";
import path from "node:path";
import { buildPack } from "../../lib/cyrus/textures/pack";
import { gunTemplate } from "../../lib/cyrus/itemmodel/templates";
import { compileMod } from "../../lib/cyrus/designer/gameplay/compile";
import { hudFont } from "../../lib/cyrus/designer/hud/font";
import { designFeatures } from "../../lib/cyrus/designer/spec";
import type { HudDesign } from "../../lib/cyrus/designer/hud/spec";
import { getVersion } from "../../lib/cyrus/versions/registry";
import { acceptRendered, checkReturnedSound, packSoundsOf, renderJobFor } from "../../lib/cyrus/assets/sounds";
import { runJob } from "../../lib/cyrus/sound/runner";
import { cyrusConfig } from "../../lib/cyrus/config";
import { applyVerdicts, checklistMarkdown, ingestResults, kitIdOf, resultsTemplate, TESTDAY_VERSIONS, type Kit, type KitVersion } from "../../lib/cyrus/eval/testday";
import { goldenDesigns, GOLDEN_NS, GOLDEN_PLUGIN } from "./designer-golden";
import { loadGameplayFixtures, GP_NS, GP_PLUGIN } from "./gameplay-golden";
import { loadHudFixtures, HUD_NS, HUD_PLUGIN } from "./hud-golden";

const ROOT = path.join(__dirname, "..", "..");
const argv = process.argv.slice(2);
const opt = (n: string, d = "") => { const i = argv.indexOf(`--${n}`); return i >= 0 && argv[i + 1] && !argv[i + 1].startsWith("--") ? argv[i + 1] : d; };
const TF = cyrusConfig().testFlightRoot;
const JDK = path.join(TF, "jdk", "21", "bin");
const MOTION_NS = "nx_r33mot01";
const motionDesigns = () => ["lab_pistol", "lab_door"].map((n) => JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-motion-mc", `${n}.json`), "utf8")));
const MODS: { name: string; ns: string; designs: () => unknown[] }[] = [
  { name: GOLDEN_PLUGIN, ns: GOLDEN_NS, designs: goldenDesigns },
  // money costs need vault-api on the compile classpath (not on node-2): the kit's copy charges emeralds instead
  { name: GP_PLUGIN, ns: GP_NS, designs: () => loadGameplayFixtures().map((d) => JSON.parse(JSON.stringify(d).replace(/\{"type":"economy","amount":([0-9.]+)\}/g, (_m, a) => `{"type":"item","item":"minecraft:emerald","cou
  { name: HUD_PLUGIN, ns: HUD_NS, designs: loadHudFixtures },
49:## Real-client test-day kit (r33)

  for (const v of versions) {
    const row = getVersion(v)!;
    const dir = path.join(out, v);
    fs.mkdirSync(dir, { recursive: true });
    const itemModels = row.capabilities.includes("itemModelDefinitions");
    const gun = gunTemplate();
    const ruby = JSON.parse(fs.readFileSync(path.join(ROOT, "test/fixtures/cyrus-textures/ruby_sword.json"), "utf8"));
    const plugins: KitVersion["plugins"] = [];
    let fonts: { path: string; data: Buffer }[] = [];
    let hudCmd: string[] = [];
    for (const m of MODS) {
      if (!designFeatures(v).ok) { plugins.push({ name: m.name, jar: null, command: null, readme: null, skipped: `the designer does not support ${v}` }); continue; }
      const c = compileMod(m.designs(), { version: v, namespace: m.ns, pluginName: m.name });
      if (!c.ok) { plugins.push({ name: m.name, jar: null, command: null, readme: null, skipped: `designer compile failed: ${JSON.stringify(c.errors).slice(0, 300)}` }); continue; }
      fs.writeFileSync(path.join(dir, `${m.name}-README.md`), c.readme);
      if (m.name === HUD_PLUGIN && (c as { huds?: HudDesign[] }).huds?.length) {
        const hf = hudFont((c as { huds: HudDesign[] }).huds, HUD_NS);
        fonts = hf.files.map((f) => ({ path: f.path, data: Buffer.from(f.data) }));
        const glyphs = hf.glyphs.slice(0, 6).map((g) => String.fromCodePoint(g.codepoint)).join("");
        hudCmd = [`/title @s actionbar {"text":"${esc(glyphs, snbtText(v))}","font":"${hf.font}"}`];
      }
      const j = compile ? compileJar(m.name, c.files, dir, c.deps, classpathFor(v, c.features.attributeNames)) : { jar: null, skipped: "not compiled (build without --compile)" };
      plugins.push({ name: m.name, jar: j.jar, command: c.command, readme: `${v}/${m.name}-README.md`, ...(j.skipped ? { skipped: j.skipped } : {}) });
    }
    const p = buildPack({ namespace: HUD_NS, description: "Cyrus test day pack", mcVersion: v, textures: itemModels ? [ruby, ...gun.textures] : [], itemModels: itemModels ? [gun.spec] : [], sounds: snd, fonts });
    if (!p.ok) throw new Error(`${v}: pack: ${p.error}`);
    fs.writeFileSync(path.join(dir, "pack.zip"), p.pack.zip);
    const rubyModel = p.pack.textures.find((t) => t.name === "ruby_sword")?.model;
    const gunModel = p.pack.itemModels?.[0]?.model;
    const nm = (t: string) => (snbtText(v) ? `"${t}"` : `'"${t}"'`); // item_name: SNBT text from 1.21.5, a JSON string before
    const commands: Record<string, string[]> = {
      "snd.play": p.pack.sounds.map((s) => `/playsound ${s.key} master @s`),
      "hud.glyph": hudCmd,
      ...(itemModels && rubyModel ? {
        "tex.hand": [`/give @s minecraft:iron_sword[minecraft:item_model="${rubyModel}",minecraft:item_name=${nm("Ruby Sword")}]`],
        "ctx.frame": ["/give @s minecraft:item_frame"],
        "ctx.head": [`/item replace entity @s armor.head with minecraft:iron_sword[minecraft:item_model="${rubyModel}"]`],
      } : {}),
      ...(itemModels && gunModel ? {
        "states.idle": [`/give @s minecraft:iron_horse_armor[minecraft:item_model="${gunModel}",minecraft:consumable={consume_seconds:72000,animation:"bow",has_consume_particles:false},minecraft:item_name=${nm("Pistol")}]`],
        "states.reloading": [`/give @s minecraft:iron_horse_armor[minecraft:item_model="${gunModel}",minecraft:custom_model_data={strings:["reloading"]},minecraft:item_name=${nm("Pistol (reloading)")}]`],
      } : {}),
    };
    kv.push({ version: v, packSha1: p.pack.sha1, packUrlPath: `${v}/pack.zip`, itemModels, sounds: p.pack.sounds.map((s) => s.key), fonts: fonts.length > 0, plugins, commands });
  }
  const kit: Kit = { kitId: kitIdOf(kv), createdAt: new Date().toISOString(), namespace: HUD_NS, versions: kv };
  fs.writeFileSync(path.join(out, "manifest.json"), JSON.stringify(kit, null, 1) + "\n");
  fs.writeFileSync(path.join(out, "CHECKLIST.md"), checklistMarkdown(kit));
  const rf = path.join(out, "results.json");
  if (!fs.existsSync(rf) || JSON.parse(fs.readFileSync(rf, "utf8")).kitId !== kit.kitId) fs.writeFileSync(rf, JSON.stringify(resultsTemplate(kit), null, 1) + "\n");
  for (const l of log) console.log(l);
  for (const v of kv) console.log(`${v.version}: pack ${v.packSha1} (item models ${v.itemModels ? "yes" : "no"}, ${v.sounds.length} sounds, fonts ${v.fonts ? "yes" : "no"}); plugins: ${v.plugins.map((p) => `${p.name}=${p.jar ? "ok" : `skipped (${p.skipped})`}`
  console.log(`kit ${kit.kitId} in ${out}`);
}

function ingest() {
  const kitDir = opt("kit");
  const kit = JSON.parse(fs.readFileSync(path.join(kitDir, "manifest.json"), "utf8")) as Kit;
  const verdicts = ingestResults(JSON.parse(fs.readFileSync(opt("results", path.join(kitDir, "results.json")), "utf8")), kit);
  for (const v of verdicts) console.log(`${v.version}: ${v.verdict} (${v.passed}/${v.required} required steps)${v.reasons.length ? ` - ${v.reasons.slice(0, 6).join("; ")}` : ""}`);
  if (!argv.includes("--apply")) { console.log("(dry: add --apply to write registry.json + client-verify.json in this checkout)"); return; }
  const regFile = path.join(ROOT, "lib/cyrus/versions/registry.json");
  let text = fs.readFileSync(regFile, "utf8");
  const { registry, changed } = applyVerdicts(JSON.parse(text), verdicts);
  // targeted edit (keeps the file's hand formatting): the flag inside each version's own object
  for (const row of registry.versions) {
    const at = text.indexOf(`"id": "${row.id}"`);
    const end = text.indexOf("\n    }", at);
    if (at < 0 || end < 0) throw new Error(`registry.json: cannot find ${row.id}`);
    text = text.slice(0, at) + text.slice(at, end).replace(/"resourcePackClientVerified": (true|false)/, `"resourcePackClientVerified": ${row.resourcePackClientVerified}`) + text.slice(end);
  }
  if (JSON.stringify(JSON.parse(text)) !== JSON.stringify(registry)) throw new Error("registry.json: the targeted edit did not produce the expected rows; edit by hand");
  fs.writeFileSync(regFile, text);
  const evFile = path.join(ROOT, "lib/cyrus/versions/client-verify.json");
  const ev = fs.existsSync(evFile) ? JSON.parse(fs.readFileSync(evFile, "utf8")) : { schema: "cyrus-client-verify-1", versions: {} };
  for (const v of verdicts.filter((x) => x.verdict !== "incomplete")) ev.versions[v.version] = { verdict: v.verdict, tester: v.tester, testedAt: v.testedAt, clientVersion: v.clientVersion, kitId: kit.kitId, packSha1: kit.versions.find((k) => k.version === v.ve
  fs.writeFileSync(evFile, JSON.stringify(ev, null, 1) + "\n");
  console.log(changed.length ? `registry: ${changed.join(", ")}` : "registry unchanged");
}

