// Cyrus eval, feature/cyrus-mc-techniques: scores a build against the technique expectations of an eval prompt
// (services/modbuilder/eval/sets/techniques.jsonl): `expectDesign` (a design item has an ability with that trigger, those
// action kinds anywhere in its graph, the trigger's block groups and those condition kinds), `expectApi` (each entry, with
// "|" alternatives, appears in the plugin's Java sources: the golden recipe's essentials), `expectSpec` (the lane spec the
// service returned: assets/armor.json / assets/blocks.json) and `expectLimit` (modbuilder.json limitations are not empty).
// Pure; no model. The reference goldens of every prompt score ok (test/cyrus-eval-techniques.test.ts), so a future paid
// run is comparable to them. Prompts with `switches` only make sense with those switches on (the runner must set them).
import { walkActions, type ItemDesign } from "../designer/spec";
import type { EvalPrompt } from "./set";

export type TechniqueInput = {
  /** item designs the build shipped (assetResult.designs[].spec) */
  designs?: unknown[];
  /** Java sources of the plugin (path -> text) */
  java?: Record<string, string>;
  /** assetResult (for the lane specs) */
  assetResult?: Record<string, unknown> | null;
  /** modbuilder.json "limitations" */
  limitations?: string[];
};
export type TechniqueScore = { applies: boolean; ok: boolean; missing: string[] };

function designHas(d: ItemDesign, want: NonNullable<EvalPrompt["expectDesign"]>): boolean {
  return (d.abilities ?? []).some((ab) => {
    if (ab.trigger.type !== want.trigger) return false;
    const kinds = new Set<string>();
    walkActions(ab.actions, (a) => kinds.add(a.type));
    if (!want.actions.every((k) => kinds.has(k))) return false;
    const tb = (ab.trigger as { blocks?: string[] }).blocks ?? [];
    if (want.blocks && !want.blocks.every((b) => tb.includes(b))) return false;
    if (want.conditions) {
      const ck = new Set((ab.conditions ?? []).map((c) => c.type));
      walkActions(ab.actions, (a) => { if (a.type === "branch") for (const c of a.if) ck.add(c.type); });
      if (!want.conditions.every((c) => ck.has(c))) return false;
    }
    return true;
  });
}

export function scoreTechnique(p: EvalPrompt, r: TechniqueInput): TechniqueScore {
  const applies = !!(p.expectDesign || p.expectApi || p.expectSpec || p.expectLimit);
  const missing: string[] = [];
  if (p.expectDesign) {
    const designs = (r.designs ?? []).filter((d): d is ItemDesign => !!d && typeof d === "object" && Array.isArray((d as ItemDesign).abilities));
    if (!designs.some((d) => designHas(d, p.expectDesign!))) missing.push(`design: no ability with ${p.expectDesign.trigger} -> ${p.expectDesign.actions.join(" + ")}${p.expectDesign.blocks ? ` on ${p.expectDesign.blocks.join("/")}` : ""}${p.expectDesign.conditions ? ` if ${p.expectDesign.conditions.join(" + ")}` : ""}`);
  }
  if (p.expectApi) {
    const src = Object.values(r.java ?? {}).join("\n");
    for (const e of p.expectApi) if (!e.split("|").some((alt) => src.includes(alt))) missing.push(`java: ${e}`);
  }
  if (p.expectSpec) {
    const lane = p.expectSpec === "assets/armor.json" ? "armor" : p.expectSpec === "assets/blocks.json" ? "blocks" : null;
    const got = lane ? (r.assetResult?.[lane] as { path?: string } | undefined) : undefined;
    if (!got || got.path !== p.expectSpec) missing.push(`lane spec: ${p.expectSpec} was not returned`);
  }
  if (p.expectLimit && !(r.limitations ?? []).some((l) => typeof l === "string" && l.trim().length > 10)) missing.push(`limitations: should name "${p.expectLimit}"`);
  return { applies, ok: applies && !missing.length, missing };
}
