// Cyrus eval, feature/cyrus-mc-techniques: the technique eval set (services/modbuilder/eval/sets/techniques.jsonl) and its
// scorer (lib/cyrus/eval/techniques.ts). Pure, no model: every prompt's reference golden scores ok (so a future paid run
// is comparable), a wrong answer scores a named miss, the version-trap prompts name the javap-verified rules, and the
// golden designs are valid designs (techniques on) on the prompt's versions.
import { describe, it } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import { scoreTechnique } from "../lib/cyrus/eval/techniques";
import type { EvalPrompt } from "../lib/cyrus/eval/set";
import { validateDesign } from "../lib/cyrus/designer/spec";

const ROOT = path.join(__dirname, "..");
const SET: EvalPrompt[] = fs.readFileSync(path.join(ROOT, "services/modbuilder/eval/sets/techniques.jsonl"), "utf8").split("\n").filter((l) => l.trim()).map((l) => JSON.parse(l));
const RULES = JSON.parse(fs.readFileSync(path.join(ROOT, "services/modbuilder/rules/failure-rules.json"), "utf8")).rules as { id: string; versions: string[]; source: string[] }[];
const by = (k: string) => SET.find((p) => p.key === k)!;
const javaOf = (dir: string) => {
  const out: Record<string, string> = {};
  const walk = (d: string) => { for (const e of fs.readdirSync(d, { withFileTypes: true })) { const p = path.join(d, e.name); if (e.isDirectory()) walk(p); else if (p.endsWith(".java")) out[path.relative(ROOT, p)] = fs.readFileSync(p, "utf8"); } };
  walk(path.join(ROOT, dir, "src"));
  return out;
};

describe("technique eval set", () => {
  it("covers every item of the batch: version traps, designer techniques, limits, golden recipes, lanes", () => {
    const cats = new Set(SET.map((p) => p.category));
    for (const c of ["bugfix", "gameplay", "unsafe", "stateful", "asset"]) assert.ok(cats.has(c), c);
    assert.ok(SET.filter((p) => p.expectDesign).length >= 6);
    assert.ok(SET.some((p) => p.switches?.includes("CYRUS_ARMOR_LANE")) && SET.some((p) => p.switches?.includes("CYRUS_NOTEBLOCK_LANE")) && SET.some((p) => p.switches?.includes("MB_MC_TECHNIQUES")));
  });
  it("the version-trap prompts name javap-verified rules that apply to their version", () => {
    const fixes = SET.filter((p) => p.category === "bugfix");
    assert.ok(fixes.length >= 9);
    for (const p of fixes) {
      const r = RULES.find((x) => x.id === p.rule);
      assert.ok(r, `${p.key}: ${p.rule}`);
      assert.ok(r!.versions.includes("*") || r!.versions.includes(p.v), `${p.key}: ${p.rule} @ ${p.v}`);
      assert.ok(r!.source.some((s) => /javap|Test Flight/.test(s)), `${p.key}: ${p.rule} is verified`);
    }
  });
  it("every reference golden scores ok", () => {
    for (const p of SET.filter((x) => x.golden)) {
      const isDesign = p.golden!.endsWith(".json");
